def timesince(when, now=time.time):
    delta = now() - when
    result = []
    for (unit, seconds) in [('year', 365 * 24 * 60 * 60), ('month', 30 * 24 * 60 * 60), ('week', 7 * 24 * 60 * 60), ('day', 24 * 60 * 60), ('hour', 60 * 60), ('minute', 60), ('second', 1)]:
        if delta >= seconds:
            n = int(delta / seconds)
            delta -= n * seconds
            result.append((n, unit))
            if len(result) >= 2:
                break
    if not result:
        result = [(1, 'second')]
    return ', '.join((f"{n} {unit}{('s' if n != 1 else '')}" for (n, unit) in result))

