def __init__(self, graph_a, graph_b):
    self.can_be_reprocessed = True
    self._graph_a = graph_a
    self._graph_b = graph_b
    self._matched_recipe_inputs = {}
    self._identical_nodes = {}
    self._changed_nodes = {}
    self._new_nodes = set()
    self._deleted_nodes = set()
    self._topo_a_nodes = self._graph_a.get_topological_order()
    self._topo_b_nodes = self._graph_b.get_topological_order()
    self._unresolved_a_nodes = set(self._topo_a_nodes)
    self._unresolved_b_nodes = set(self._topo_b_nodes)
    self._match_recipe_inputs()
    if not self.can_be_reprocessed:
        return
    self._match_identical_nodes()
    for job_name_b in self._topo_b_nodes:
        if job_name_b not in self._identical_nodes:
            job_name_a = self._find_changed_node(job_name_b)
            if job_name_a:
                self._changed_nodes[job_name_b] = job_name_a
    self._new_nodes = self._unresolved_b_nodes
    self._deleted_nodes = self._unresolved_a_nodes
    self._unresolved_a_nodes = set()
    self._unresolved_b_nodes = set()

def set_time_range_for_session():
    if 'start_time' in request.values:
        session['start_time'] = localized_datetime(iso8601.parse_date(request.values.get('start_time')))
    elif 'start_time' not in session:
        session['start_time'] = get_default_start_time()
    elif session['start_time'].tzinfo is None:
        session['start_time'] = session['start_time'].replace(tzinfo=pytz.utc).astimezone(get_timezone())
    if 'end_time' in request.values:
        session['end_time'] = localized_datetime(iso8601.parse_date(request.values.get('end_time')))
    elif 'end_time' not in session:
        session['end_time'] = get_default_end_time()
    elif session['end_time'].tzinfo is None:
        session['end_time'] = session['end_time'].replace(tzinfo=pytz.utc).astimezone(get_timezone())
    session['start_time'] = session['start_time'].replace(year=2015)
    session['end_time'] = session['end_time'].replace(year=2015)
    if session['start_time'] >= session['end_time']:
        raise BadRequest('Start time %s is not after end time %s.' % (session['start_time'], session['end_time']))
    session['resolution'] = decide_resolution(session['start_time'], session['end_time'])
    if 'forecast_horizon' in request.values:
        session['forecast_horizon'] = request.values.get('forecast_horizon')
    allowed_horizons = forecast_horizons_for(session['resolution'])
    if session.get('forecast_horizon') not in allowed_horizons and len(allowed_horizons) > 0:
        session['forecast_horizon'] = allowed_horizons[0]

def in_JOINBATTLE(self, client, battle_id, password=None, scriptPassword=None):
    if scriptPassword:
        client.scriptPassword = scriptPassword
    try:
        battle_id = int32(battle_id)
    except:
        client.Send('JOINBATTLEFAILED Invalid battle id: %s.' % str(battle_id))
        return
    username = client.username
    if client.current_battle in self._root.battles:
        client.Send('JOINBATTLEFAILED You are already in a battle.')
        return
    if battle_id not in self._root.battles:
        client.Send('JOINBATTLEFAILED Unable to join battle.')
        return
    battle = self._root.battles[battle_id]
    if client.session_id in battle.users:
        client.Send('JOINBATTLEFAILED client is already in battle')
        return
    host = self.clientFromSession(battle.host)
    if battle.passworded == 1 and (not battle.password == password):
        client.Send('JOINBATTLEFAILED Incorrect password.')
        return
    if battle.locked:
        client.Send('JOINBATTLEFAILED Battle is locked.')
        return
    if host.user_id in host.battle_bans:
        client.Send('JOINBATTLEFAILED <%s> has banned you from their battles.' % host.username)
        return
    if host.compat['b'] and (not (host.bot and 'mod' in client.accesslevels)):
        if client.session_id in battle.pending_users:
            client.Send('JOINBATTLEFAILED waiting for JOINBATTLEACCEPT/JOINBATTLEDENIED from host')
        else:
            battle.pending_users.add(client.session_id)
        if client.ip_address in self._root.trusted_proxies:
            client_ip = client.local_ip
        else:
            client_ip = client.ip_address
        host.Send('JOINBATTLEREQUEST %s %s' % (username, client_ip))
        return
    self._joinBattle(client, battle)

