def buildImportFromNode(provider, node, source_ref):
    module_name = node.module if node.module is not None else ''
    level = node.level
    if module_name == '__future__':
        if not provider.isCompiledPythonModule():
            SyntaxErrors.raiseSyntaxError(reason='\nfrom __future__ imports must occur at the beginning of the file', col_offset=8 if python_version >= 300 or not Options.isFullCompat() else None, source_ref=source_ref)
        for import_desc in node.names:
            (object_name, _local_name) = (import_desc.name, import_desc.asname)
            enableFutureFeature(object_name=object_name, future_spec=source_ref.getFutureSpec(), source_ref=source_ref)
        node.source_ref = source_ref
        _future_import_nodes.append(node)
    target_names = []
    import_names = []
    for import_desc in node.names:
        (object_name, local_name) = (import_desc.name, import_desc.asname)
        if object_name == '*':
            target_names.append(None)
        else:
            target_names.append(local_name if local_name is not None else object_name)
        import_names.append(object_name)
    if None in target_names:
        assert target_names == [None]
        if not provider.isCompiledPythonModule() and python_version >= 300:
            SyntaxErrors.raiseSyntaxError('import * only allowed at module level', provider.getSourceReference())
        if provider.isExpressionFunctionBody():
            provider.markAsStarImportContaining()
        return StatementImportStar(module_import=ExpressionImportModule(module_name=module_name, import_list=('*',), level=level, source_ref=source_ref), source_ref=source_ref)
    else:

        def makeImportName(import_name):
            if module_name == '__future__':
                return ExpressionImportModuleHard(module_name='__future__', import_name=import_name, source_ref=source_ref)
            else:
                import_module = ExpressionImportModule(module_name=module_name, import_list=tuple(import_names), level=level, source_ref=source_ref)
                return ExpressionImportName(module=import_module, import_name=import_name, source_ref=source_ref)
        import_nodes = []
        for (target_name, import_name) in zip(target_names, import_names):
            import_nodes.append(StatementAssignmentVariable(variable_ref=ExpressionTargetVariableRef(variable_name=mangleName(target_name, provider), source_ref=source_ref), source=makeImportName(import_name=import_name), source_ref=source_ref))
        return StatementsSequence(statements=import_nodes, source_ref=source_ref)

def find_common_filenames(list1, list2):
    lf = [Path(d['file']).stem for d in list1]
    rf = [Path(d['file']).stem for d in list2]
    if 'image' in rf[0][0:5]:
        if len(lf[0]) == 32:
            lf = [Path(d['file']).stem[13:28] for d in list1]
            rf = [Path(d['file']).stem[13:28] for d in list2]
        else:
            lf = [Path(d['file']).stem[5:] for d in list1]
            rf = [Path(d['file']).stem[5:] for d in list2]
    result = []
    for (i, lname) in enumerate(lf):
        for (j, rname) in enumerate(rf):
            if lname == rname:
                result.append((list1[i], list2[j]))
    return result

def isAddressInSections(self, address, length=0, sectiontype=''):
    if not self.internalblue.fw.SECTIONS:
        return False
    for section in self.internalblue.fw.SECTIONS:
        if sectiontype.upper() == 'ROM' and (not section.is_rom) or (sectiontype.upper() == 'RAM' and (not section.is_ram)):
            continue
        if address >= section.start_addr and address <= section.end_addr:
            if address + length <= section.end_addr:
                return True
            else:
                return False
    return False

def _patchLog(self, log, count):
    log.setHeader(self.logHeader)
    log(self.logWeightValue % self.weight)
    log(self.logMsg % sum(count.values()))
    for srcMod in bosh.modInfos.getOrdered(count.keys()):
        log(u'  * %s: %d' % (srcMod.s, count[srcMod]))

def _generate_bridge_operation(self, version=1):
    addrs = self._generate_addresses(version=version)
    bridge_operation = self._get_initial_params()
    if version == 1:
        bridge_operation.update({'id': self.name, 'type': 'bridge', 'name': self.name, 'mac_address': str(self.iface.mac_address), 'bridge_interfaces': [parent.get_name() for parent in self.iface.parents.order_by('name')], 'params': self._get_bridge_params()})
        if addrs:
            bridge_operation['subnets'] = addrs
    elif version == 2:
        bridge_operation.update({'interfaces': [parent.get_name() for parent in self.iface.parents.order_by('name')]})
        bridge_params = get_netplan_bridge_parameters(self._get_bridge_params())
        if len(bridge_params) > 0:
            bridge_operation['parameters'] = bridge_params
        bridge_operation.update(addrs)
    return bridge_operation

def post(resource):
    if len(request.form) == 0:
        abort(400)
    response = dict()
    date_utc = datetime.utcnow()
    schema = app.config['DOMAIN'][resource]['schema']
    validator = app.validator(schema, resource)
    for (key, value) in request.form.items():
        response_item = dict()
        issues = list()
        try:
            document = parse(value, resource)
            validation = validator.validate(document)
            if validation:
                document[LAST_UPDATED] = document[DATE_CREATED] = date_utc
                document[ID_FIELD] = app.data.insert(resource, document)
                document[ID_FIELD] = key
                response_item[ID_FIELD] = document[ID_FIELD]
                response_item[LAST_UPDATED] = document[LAST_UPDATED]
                response_item['link'] = document_link(resource, response_item[ID_FIELD])
            else:
                issues.append(validator.errors)
        except ValidationError as e:
            raise e
        except Exception as e:
            issues.append(str(e))
        if len(issues):
            response_item['issues'] = issues
            response_item['status'] = STATUS_ERR
        else:
            response_item['status'] = STATUS_OK
        response[key] = response_item
    return (response, None, None, 200)

def build_func(context):
    proc = Popen([os.path.join(config['paths']['download'], filename), '/VERYSILENT', '/DIR={}'.format(context['build_path'])], cwd=config['paths']['download'], env=config['__environment'])
    proc.communicate()
    if proc.returncode != 0:
        logging.error('failed to run installer (returncode %s)', proc.returncode)
        return False
    relevant_files = [os.path.join(context['build_path'], f) for f in ['file1', 'file2', 'file3']]
    for file in relevant_files:
        while not os.path.exists(file):
            time.sleep(1)
    return True

def _EmptyStrOrError(self, val, token=None):
    assert isinstance(val, runtime.value), val
    if val.tag == value_e.Undef:
        if self.exec_opts.nounset:
            token = None
            log(f'UNDEFINED: {token} (todo: show error)')
            raise _EvalError('Undefined variable', token=token)
        else:
            return runtime.Str('')
    else:
        return val

def get_det_bboxes(self, rois, cls_score, bbox_pred, img_shape, scale_factor, rescale=False, cfg=None):
    if isinstance(cls_score, list):
        cls_score = sum(cls_score) / float(len(cls_score))
    scores = F.softmax(cls_score, dim=1) if cls_score is not None else None
    if bbox_pred is not None:
        bboxes = delta2bbox(rois[:, 1:], bbox_pred, self.target_means, self.target_stds, img_shape)
    else:
        bboxes = rois[:, 1:]
        bboxes = bboxes.clamp(min=0)
    if rescale:
        bboxes /= scale_factor
    if cfg is None:
        return (bboxes, scores)
    else:
        (det_bboxes, det_labels) = multiclass_nms(bboxes, scores, cfg.score_thr, cfg.nms, cfg.max_per_img)
        return (det_bboxes, det_labels)

