def _standardize_curie_or_iri(curie_or_iri: str, *, converter: Converter) -> str:
    if converter.is_uri(curie_or_iri):
        return converter.compress_uri(curie_or_iri)
    if converter.is_curie(curie_or_iri):
        return converter.standardize_curie(curie_or_iri, strict=True)
    return curie_or_iri

def get_application(type):
    extension = _get_extension(type)
    progId = _get_prog_id(extension)
    if progId:
        aReg = ConnectRegistry(None, HKEY_CLASSES_ROOT)
        subkey = OpenKey(aReg, '%s\\shell\\open\\command' % progId)
        (n, command, type) = EnumValue(subkey, 0)
        if type == REG_EXPAND_SZ:
            command = command.replace('%SystemRoot%', os.getenv('SystemRoot'))
        description = _get_application_description(progId)
        return (command, description)
    return None

def imul(info, a, b=None, c=None):
    e = []
    if b == None:
        if a.get_size() == 32:
            c_hi = ExprOp('imul32_hi', eax, a)
            c_lo = ExprOp('imul32_lo', eax, a)
            e.append(ExprAff(edx, c_hi))
            e.append(ExprAff(eax, c_lo))
        elif a.get_size() == 16:
            c_hi = ExprOp('imul16_hi', r_ax, a)
            c_lo = ExprOp('imul16_lo', r_ax, a)
            e.append(ExprAff(r_dx, c_hi))
            e.append(ExprAff(r_ax, c_lo))
        elif a.get_size() == 8:
            c = ExprOp('imul08', eax, a)
            e.append(ExprAff(eax[:16], c))
    else:
        if c == None:
            c = b
            b = a
        c = ExprOp('*', b, c)
        e.append(ExprAff(a, c))
    return e

def cv(self, kfold=5, random_state=None):
    kf = KFold(n_splits=kfold, shuffle=True, random_state=random_state)
    eras = self.df.era.unique().astype(str)
    for (train_index, test_index) in kf.split(eras):
        idx = np.zeros(self.size, dtype=np.bool)
        for i in train_index:
            idx = np.logical_or(idx, self.df.era.values.astype(str) == eras[i])
        dtrain = self[idx]
        idx = np.zeros(self.size, dtype=np.bool)
        for i in test_index:
            idx = np.logical_or(idx, self.df.era.values.astype(str) == eras[i])
        dtest = self[idx]
        yield (dtrain, dtest)

def add(self, conn: Conn, packet: server_packets.PublicChannelJoined):
    if not conn.is_main:
        return
    conn.channels[packet.channel_id] = packet
    if not conn.org_id and self.is_org_channel_id(packet.channel_id):
        conn.org_channel_id = packet.channel_id
        conn.org_id = 4294967295 & packet.channel_id
        if packet.name != 'Clan (name unknown)':
            self.setting_service.get('org_name').set_value(packet.name)
            conn.org_name = packet.name
        self.logger.info(f"Org info for '{conn.id}': {conn.org_name} ({conn.org_id})")

def base_test_protocol(folder_name: str, protocol: SourceProto | DestinationProto):
    modules = dag_utils.import_modules_from_folder(folder_name)
    for module in modules:
        target_class = 'Source' if protocol.__name__ == 'SourceProto' else 'Destination' if protocol.__name__ == 'DestinationProto' else None
        if not target_class:
            raise ValueError(f'Provided protocol {protocol} not supported.')
        implementation = getattr(module, target_class)
        assert issubclass(implementation, protocol)
        target_methods = inspect.getmembers(implementation, inspect.isfunction)
        protocol_methods = inspect.getmembers(protocol, inspect.isfunction)
        for (required_name, required_method) in protocol_methods:
            for (target_name, target_method) in target_methods:
                if required_name == target_name and target_name != '__init__':
                    assert inspect.signature(required_method) == inspect.signature(target_method)

def talk_schedule(talk):
    events = talk.get_events()
    if not events:
        return ''
    if len(events) > 1:
        return 'This talk has multiple events.'
    event = events[0]
    timerange = event.get_time_range()
    return '{}, {}'.format(str(timerange[0]), str(timerange[1]))

def __call__(self, entries):
    accounts = set()
    for entry in entries:
        method = getattr(self, entry.__class__.__name__)
        for account in method(entry):
            accounts.add(account)
    return accounts

def __init__(self, limits):
    self._limits = limits
    logging.debug('Created SubsetConstraint of type %s', self.__class__.__name__)

def __getitem__(self, key):
    if key in self._pb_body.keys():
        value = self._pb_body[key]
        if isinstance(value, struct_pb2.Struct):
            return StructView(value)
        elif isinstance(value, struct_pb2.ListValue):
            return ListValueView(value)
        else:
            return value
    else:
        raise KeyError()

