def _create_tables(self):
    s = LRState(self, 0, AUGSYMBOL, [LRItem(self.grammar.productions[0], 0)])
    state_queue = [s]
    state_id = 1
    while state_queue:
        state = state_queue.pop(0)
        state.closure()
        self._states.append(state)
        goto = OrderedDict()
        self._goto.append(goto)
        actions = OrderedDict()
        if state.state_id == 1:
            actions[EOF] = Action(ACCEPT)
        self._actions.append(actions)
        per_next_symbol = OrderedDict()
        max_prior_per_symbol = {}
        for i in state.items:
            symbol = i.production.rhs[i.position]
            if symbol:
                per_next_symbol.setdefault(symbol, []).append(i)
                prod_prior = i.production.prior
                if symbol in max_prior_per_symbol:
                    old_prior = max_prior_per_symbol[symbol]
                    max_prior_per_symbol[symbol] = max(prod_prior, old_prior)
                else:
                    max_prior_per_symbol[symbol] = prod_prior
            else:
                for t in self._follow_sets[i.production.symbol]:
                    if t is EOF and i.production.prod_id == 0:
                        actions[t] = Action(ACCEPT)
                    elif t in actions:
                        if actions[t].prod is not i.production:
                            if actions[t].prod.prior < i.production.prior:
                                actions[t] = Action(REDUCE, prod=i.production)
                        else:
                            actions[t] = Action(REDUCE, prod=i.production)
                    else:
                        actions[t] = Action(REDUCE, prod=i.production)
        for (symbol, items) in per_next_symbol.items():
            inc_items = [i.get_pos_inc() for i in items]
            maybe_new_state = LRState(self, state_id, symbol, inc_items)
            target_state = maybe_new_state
            try:
                idx = self._states.index(maybe_new_state)
                target_state = self._states[idx]
            except ValueError:
                try:
                    idx = state_queue.index(maybe_new_state)
                    target_state = state_queue[idx]
                except ValueError:
                    pass
            if target_state is maybe_new_state:
                state_queue.append(target_state)
                state_id += 1
            if isinstance(symbol, NonTerminal):
                goto[symbol] = target_state
            elif symbol in actions:
                prod = actions[symbol].prod
                prior = max_prior_per_symbol[symbol]
                if prod.prior == prior:
                    if prod.assoc == ASSOC_NONE:
                        self.print_debug()
                        raise ShiftReduceConflict(state, symbol, prod)
                    elif prod.assoc == ASSOC_RIGHT:
                        actions[symbol] = Action(SHIFT, state=target_state)
                elif prod.prior < prior:
                    actions[symbol] = Action(SHIFT, state=target_state)
            else:
                actions[symbol] = Action(SHIFT, state=target_state)
    if self.debug:
        self.print_debug()

def _field_from_data(self, port=8983):
    (session, host) = self._get_session(port=port)
    url = f'http://{host}/{self.api_base}/{self.name}/admin/luke?numTerms=0&wt=json'
    res = session.get(url)
    if res.ok:
        collection_data = {}
        fields = res.json()['fields']
        for (field_name, field) in fields.items():
            if field_name.startswith('_') or '//' in field_name:
                continue
            if not Collection.FIELD_SANITIZER.match(field_name):
                continue
            collection_data[field_name] = {'indexed': field.get('schema', '').startswith('I'), 'stored': field.get('schema', '')[:3].endswith('S'), 'type': field['type']}
        return collection_data
    else:
        try:
            j = res.json()
            message = j['error']['msg']
            if 'IOException' in message or 'Server refused' in message:
                raise SearchRetryException()
            else:
                raise SearchException(message)
        except SearchException:
            raise
        except Exception:
            if res.status_code == 404:
                return {}
            elif res.status_code == 500:
                raise SearchRetryException()
            else:
                raise SearchException(res.content)

def position(self):
    timestamp = int(self._setstate.nowPlayingInfo.timestamp)
    if timestamp == 0:
        return 0
    now_utc = datetime.datetime.utcnow()
    timeshift = datetime.datetime(2001, 1, 1, 0, 0) + datetime.timedelta(seconds=timestamp)
    diff = (now_utc - timeshift).total_seconds()
    base = self._setstate.nowPlayingInfo.elapsedTime
    return int(base + diff)

def rtype_lt((r_tup1, r_tup2), hop):
    v_tuple1 = hop.inputargs(r_tup1)
    v_tuple2 = hop.inputargs(r_tup2)
    ll_lt = r_tup1.get_ll_lt_function()
    return hop.gendirectcall(ll_lt, v_tuple1, v_tuple2)

