async def convert(self, ctx: commands.Converter, argument: str) -> str:
    if self.check_command:
        if self.is_tag_name_registered(ctx.guild, argument):
            raise commands.BadArgument('Tag name is already registered to this guild.')
    if len(argument) > 32:
        raise commands.BadArgument('Slash command names may not exceed 32 characters.')
    match = SLASH_NAME.match(argument)
    if not match:
        raise commands.BadArgument("Slash command characters must be alphanumeric or '_' or '-'.")
    return match.group(1)

