def get_fwhm(instrument):
    if instrument == 'naco27':
        if 'fwhm' in VLT_NACO:
            fwhm = VLT_NACO['fwhm']
        else:
            tel_diam = VLT_NACO['diam']
            fwhm = VLT_NACO['lambdal']/tel_diam*206265/VLT_NACO['plsc']
    elif instrument == 'lmircam':
        if 'fwhm' in LBT:
            fwhm = LBT['fwhm']
        else:
            fwhm = LBT['lambdal']/LBT['diam']*206265/LBT['plsc']
    elif not instrument:
        msg = 'One of parameters 'fwhm' or 'instrument' must be given'
        raise RuntimeError(msg)
    else:
        raise RuntimeError('Instrument not recognized')
    return fwhm

def _find_domain(self, vm):
    found = None
    for domain in self.conn().listAllDomains():
        name = domain.name()
        if not (vm.match_uid_name(name) or vm.fqdn == name or vm.fqdn.startswith(name + '.')):
            continue
        if found is not None:
            raise HypervisorError('Same VM is defined multiple times as "{}" and "{}".'.format(found.name(), name))
        found = domain
    return found

def getHostGuestMapping(self):
    guests = []
    (connection, headers) = self.connect()
    hypervsoap = HyperVSoap(self.url, connection, headers, self.logger)
    try:
        if not self.useNewApi:
            uuid = hypervsoap.Enumerate('select BIOSGUID, ElementName from Msvm_VirtualSystemSettingData where SettingType = 3', 'root/virtualization')
        else:
            uuid = hypervsoap.Enumerate("select BIOSGUID, ElementName from Msvm_VirtualSystemSettingData where VirtualSystemType = 'Microsoft:Hyper-V:System:Realized'", 'root/virtualization/v2')
    except HyperVException:
        if not self.useNewApi:
            self.logger.debug('Error when enumerating using root/virtualization namespace, trying root/virtualization/v2 namespace')
            self.useNewApi = True
            return self.getHostGuestMapping()
        raise
    guest_states = hypervsoap.Invoke_GetSummaryInformation('root/virtualization/v2' if self.useNewApi else 'root/virtualization')
    for instance in hypervsoap.Pull(uuid):
        try:
            uuid = instance['BIOSGUID']
        except KeyError:
            self.logger.warning('Guest without BIOSGUID found, ignoring')
            continue
        try:
            elementName = instance['ElementName']
        except KeyError:
            self.logger.warning('Guest %s is missing ElementName', uuid)
            continue
        try:
            state = guest_states[elementName]
        except KeyError:
            self.logger.warning('Unknown state for guest %s', elementName)
            state = virt.Guest.STATE_UNKNOWN
        guests.append(virt.Guest(HyperV.decodeWinUUID(uuid), self, state))
    if self.config.hypervisor_id == 'uuid':
        uuid = hypervsoap.Enumerate('select UUID from Win32_ComputerSystemProduct', 'root/cimv2')
        host = None
        for instance in hypervsoap.Pull(uuid, 'root/cimv2'):
            host = HyperV.decodeWinUUID(instance['UUID'])
    elif self.config.hypervisor_id == 'hostname':
        data = hypervsoap.Enumerate('select DNSHostName from Win32_ComputerSystem', 'root/cimv2')
        for instance in hypervsoap.Pull(data, 'root/cimv2'):
            host = instance['DNSHostName']
    else:
        raise virt.VirtError('Reporting of hypervisor %s is not implemented in %s backend' % (self.config.hypervisor_id, self.CONFIG_TYPE))
    hypervisor = virt.Hypervisor(hypervisorId=host, guestIds=guests, name=host)
    return {'hypervisors': [hypervisor]}

