def receive_message(conn):
    while True:
        frame_type_str = conn.read(1)
        frame_type = ord(frame_type_str[0])
        if frame_type & 128 == 128:
            length = _payload_length(conn)
            _receive_bytes(conn, length)
        else:
            bytes = _read_until(conn, 'ÿ')
            message = bytes.decode('utf-8')
            if frame_type == 0:
                return message

def __iter__(self):
    for (index, component) in enumerate(self._components):
        if index % 2 == 1:
            yield 'glue'
        yield component

def upload_submit_async(self, **kwargs):
    if 'validate' in kwargs:
        fields = json.loads(kwargs['validate'])
        err = {}
        for field in fields:
            if field in tmpl_context.form_errors:
                err[field] = tmpl_context.form_errors[field]
        return json.dumps(dict(valid=len(err) == 0, err=err))
    else:
        if len(tmpl_context.form_errors) != 0:
            return json.dumps(dict(success=False))
        kwargs.setdefault('name')
        kwargs.setdefault('tags')
        media_obj = self._save_media_obj(kwargs['name'], kwargs['email'], kwargs['title'], kwargs['description'], kwargs['tags'], kwargs['file'])
        email.send_media_notification(media_obj)
        return json.dumps(dict(success=True, redirect=url_for(action='upload_success')))

def store_subtitles_movie(file):
    logging.debug('BAZARR started subtitles indexing for this file: ' + file)
    actual_subtitles = []
    if os.path.exists(file):
        q4ws.append('Analyzing this file for subtitles: ' + file)
        if os.path.splitext(file)[1] == '.mkv':
            logging.debug('BAZARR is trying to index embedded subtitles.')
            try:
                with open(file, 'rb') as f:
                    mkv = enzyme.MKV(f)
                for subtitle_track in mkv.subtitle_tracks:
                    try:
                        if alpha2_from_alpha3(subtitle_track.language) is not None:
                            lang = str(alpha2_from_alpha3(subtitle_track.language))
                            logging.debug('BAZARR embedded subtitles detected: ' + lang)
                            actual_subtitles.append([lang, None])
                    except:
                        logging.debug('BAZARR unable to index this unrecognized language: ' + subtitle_track.language)
                        pass
            except Exception as e:
                logging.exception('BAZARR error when trying to analyze this mkv file: ' + file)
                pass
        else:
            logging.debug("BAZARR This file isn't an .mkv file.")
        subtitles = search_external_subtitles(file)
        brazilian_portuguese = ['.pt-br', '.pob', 'pb']
        try:
            subtitles = core.search_external_subtitles(file)
        except Exception as e:
            logging.exception('BAZARR unable to index external subtitles.')
            pass
        else:
            for (subtitle, language) in subtitles.iteritems():
                if str(os.path.splitext(subtitle)[0]).lower().endswith(tuple(brazilian_portuguese)) is True:
                    logging.debug('BAZARR external subtitles detected: ' + 'pb')
                    actual_subtitles.append([str('pb'), path_replace_reverse_movie(os.path.join(os.path.dirname(file), subtitle))])
                elif str(language) != 'und':
                    logging.debug('BAZARR external subtitles detected: ' + str(language))
                    actual_subtitles.append([str(language), path_replace_reverse_movie(os.path.join(os.path.dirname(file), subtitle))])
                elif os.path.splitext(subtitle)[1] != '.sub':
                    logging.debug('BAZARR falling back to file content analysis to detect language.')
                    with open(path_replace_movie(os.path.join(os.path.dirname(file), subtitle)), 'r') as f:
                        text = list(islice(f, 100))
                        text = ' '.join(text)
                        encoding = UnicodeDammit(text)
                        try:
                            text = text.decode(encoding.original_encoding)
                            detected_language = langdetect.detect(text)
                        except Exception as e:
                            logging.exception('BAZARR Error trying to detect language for this subtitles file: ' + path_replace(os.path.join(os.path.dirname(file), subtitle)) + ' You should try to delete this subtitles file manually and ask Bazarr to download it again.')
                        else:
                            if len(detected_language) > 0:
                                logging.debug('BAZARR external subtitles detected and analysis guessed this language: ' + str(detected_language))
                                actual_subtitles.append([str(detected_language), path_replace_reverse_movie(os.path.join(os.path.dirname(file), subtitle))])
        conn_db = sqlite3.connect(os.path.join(args.config_dir, 'db', 'bazarr.db'), timeout=30)
        c_db = conn_db.cursor()
        logging.debug('BAZARR storing those languages to DB: ' + str(actual_subtitles))
        c_db.execute('UPDATE table_movies SET subtitles = ? WHERE path = ?', (str(actual_subtitles), path_replace_reverse_movie(file)))
        conn_db.commit()
        c_db.close()
    else:
        logging.debug("BAZARR this file doesn't seems to exist or isn't accessible.")
    logging.debug('BAZARR ended subtitles indexing for this file: ' + file)
    return actual_subtitles

from PyQt5.QtCore import QThread

class FlightTrackThread(QThread):

    def __init__(self, parent, start, end):
        super().__init__()
        self.parent = parent
        self.start = start
        self.end = end

    def run(self):
        time.sleep(0.5)
        self.flighttrackAdded(self.parent, self.start, self.end)

    def flighttrackAdded(self, parent, start, end):
        pass

def wait(self, parent, start, end):
    self.flighttrack_added = True
    thread = FlightTrackThread(parent, start, end)
    thread.start()

def do_sample(sample_obj, rest, count, full_olist):
    samples = [('cycles:pp', 'Precise cycles')]

    def sample_list(obj):
        return [(s, obj.name) for s in obj.sample]
    for obj in sample_obj:
        if len(obj.sample) == 0:
            m = full_name(obj) + '*'
            csamples = flatten([sample_list(o) for o in full_olist if fnmatch.fnmatch(full_name(o), m) and o.level <= obj.level + SAMPLE_EXTEND])
            if len(csamples) > 2:
                samples += csamples
                continue
        for s in obj.sample:
            samples.append((s, obj.name))
    nsamp = [x for x in samples if not unsup_event(x[0], unsup_events)]
    nsamp = [(remove_pp(x[0]), x[1]) if unsup_event(x[0], unsup_pebs) else x for x in nsamp]
    if nsamp != samples:
        missing = [x[0] for x in set(samples) - set(nsamp)]
        if not args.quiet:
            print('warning: update kernel to handle sample events:', file=sys.stderr)
            print('\n'.join(missing), file=sys.stderr)

    def force_pebs(ev):
        return ev.startswith('FRONTEND_') or 'PREC_DIST' in ev
    no_pebs = not supports_pebs()
    if no_pebs:
        nsamp = [x for x in nsamp if not force_pebs(x[0])]
    sl = [raw_event(s[0], s[1] + '_' + clean_event(s[0]), period=True, nopebs=False) for s in nsamp]
    sl = add_filter(sl)
    sample = ','.join([x for x in sl if x])
    if no_pebs:
        sample = re.sub('/p+', '/', sample)
        sample = re.sub(':p+', '', sample)
    print('Sampling:')
    extra_args = args.sample_args.replace('+', '-').split()
    perf_data = args.sample_basename
    if count:
        perf_data += '.%d' % count
    sperf = [perf, 'record'] + extra_args + ['-e', sample, '-o', perf_data] + [x for x in rest if x != '-A']
    print(' '.join(sperf))
    if args.run_sample:
        ret = os.system(' '.join(sperf))
        if ret:
            print('Sampling failed')
            sys.exit(1)
        if not args.quiet:
            print('Run `' + perf + " report %s%s' to show the sampling results" % ('-i %s' % perf_data if perf_data != 'perf_data' else '', ' --no-branch-history' if '-b' in extra_args else ''))

def _RunInstrumentCommand(command, options, args, option_parser):
    if not (options.input_path and options.output_path and options.coverage_file and options.sources_file and options.sources and options.src_root and options.emma_jar):
        option_parser.error('All arguments are required.')
    coverage_file = os.path.join(os.path.dirname(options.output_path), options.coverage_file)
    sources_file = os.path.join(os.path.dirname(options.output_path), options.sources_file)
    temp_dir = tempfile.mkdtemp()
    try:
        build_utils.CheckCallDie(['java', '-cp', options.emma_jar, 'emma', 'instr', '-ip', options.input_path, '-d', temp_dir, '-out', coverage_file, '-m', 'fullcopy', '-ix'], suppress_output=True)
        if command == 'instrument_jar':
            for jar in os.listdir(os.path.join(temp_dir, 'lib')):
                shutil.copy(os.path.join(temp_dir, 'lib', jar), options.output_path)
        else:
            if os.path.isdir(options.output_path):
                shutil.rmtree(options.output_path, ignore_errors=True)
            shutil.copytree(os.path.join(temp_dir, 'classes'), options.output_path)
    finally:
        shutil.rmtree(temp_dir)
    _CreateSourcesFile(options.sources, sources_file, options.src_root)
    if options.stamp:
        build_utils.Touch(options.stamp)
    return 0

def _print_injection_summary(channel):
    prefix = channel.data.get('prefix', '').replace('\n', '\\n')
    render = channel.data.get('render', '%(code)s').replace('\n', '\\n') % {'code': '*'}
    suffix = channel.data.get('suffix', '').replace('\n', '\\n')
    idiom = channel.data.get('evaluate')
    if idiom:
        evaluation = 'yes, %s code' % idiom
        if channel.data.get('evaluate_blind'):
            evaluation += ' (blind)'
    else:
        evaluation = 'no'
    if channel.data.get('execute_blind'):
        execution = 'yes (blind)'
    elif channel.data.get('execute'):
        execution = 'yes'
    else:
        execution = 'no'
    log.info('Tplmap identified the following injection point:\n\n  Engine: %(engine)s\n  Injection: %(prefix)s%(render)s%(suffix)s\n  Context: %(context)s\n  OS: %(os)s\n  Technique: %(injtype)s\n  Capabilities:\n    Code evaluation: %(evaluate)s\n    OS command execution: %(execute)s\n    File write: %(write)s\n    File read: %(read)s\n\n')

def create_machine(session, machine, dblocation, dbmodel, cpuname, cpuvendor, cpuspeed, cpucount, memory, serial):
    dbcpu = None
    if not (cpuname or cpuvendor or cpuspeed is not None):
        if not dbmodel.machine_specs:
            raise ArgumentError('Model %s does not have machine specification defaults, please specify --cpuvendor, --cpuname, and --cpuspeed.' % dbmodel.name)
        dbcpu = dbmodel.machine_specs.cpu
    else:
        q = session.query(Cpu)
        if cpuname:
            q = q.filter(Cpu.name.like(cpuname.lower() + '%'))
        if cpuspeed is not None:
            q = q.filter_by(speed=cpuspeed)
        if cpuvendor:
            q = q.join('vendor').filter_by(name=cpuvendor.lower())
        cpulist = q.all()
        if not cpulist:
            raise ArgumentError('Could not find a CPU with the given attributes.')
        if len(cpulist) == 1:
            dbcpu = cpulist[0]
        elif dbmodel.machine_specs:
            dbcpu = dbmodel.machine_specs.cpu
            if cpuname and (not dbcpu.name.startswith(cpuname.lower())) or (cpuspeed is not None and dbcpu.speed != cpuspeed) or (cpuvendor and dbcpu.vendor.name != cpuvendor.lower()):
                raise ArgumentError('Could not uniquely identify a CPU with the attributes given.')
        else:
            raise ArgumentError('Could not uniquely identify a CPU with the attributes given.')
    if cpucount is None:
        if dbmodel.machine_specs:
            cpucount = dbmodel.machine_specs.cpu_quantity
        else:
            raise ArgumentError('Model %s does not have machine specification defaults, please specify --cpucount.' % dbmodel.name)
    if memory is None:
        if dbmodel.machine_specs:
            memory = dbmodel.machine_specs.memory
        else:
            raise ArgumentError('Model %s does not have machine specification defaults, please specify --memory (in MB).' % dbmodel.name)
    dbmachine = Machine(location=dblocation, model=dbmodel, name=machine, cpu=dbcpu, cpu_quantity=cpucount, memory=memory, serial_no=serial)
    session.add(dbmachine)
    if dbmodel.machine_specs and dbmodel.machine_type != 'aurora_node' and (dbmodel.machine_specs.disk_type == 'local'):
        device_name = 'sda'
        dbdisk = LocalDisk(machine=dbmachine, device_name=device_name, controller_type=dbmodel.machine_specs.controller_type, capacity=dbmodel.machine_specs.disk_capacity)
        session.add(dbdisk)
    session.flush()
    return dbmachine

def get_program_enrollment_url(self, program_uuid):
    if configuration_helpers is None:
        raise NotConnectedToOpenEdX(_('This package must be installed in an EdX environment to look up configuration.'))
    return reverse('enterprise_program_enrollment_page', kwargs={'enterprise_uuid': self.uuid, 'program_uuid': program_uuid})

def tasks(self, kpi_id, recent_only=False):

    def browse_url(issue):
        return self.__url + 'browse/' + issue['key']

    def match_id(issue, kpi_id):
        return 'KPI %s' % kpi_id in issue['fields']['description']

    def match_recent(issue):
        if recent_only:
            date_time_string = issue['fields']['updated']
            updated = utils.parse_iso_date_time(date_time_string)
            age = datetime.datetime.now() - updated
            return age < datetime.timedelta(weeks=2)
        else:
            return True
    return [browse_url(issue) for issue in self.__all_tasks() if match_id(issue, kpi_id) and match_recent(issue)]

def invalidate(self):
    for key in self._store:
        if isinstance(self._store[key], list):
            self._store[key] = []
    self._store['arrays_resetted'] = True

def _client(self, restart_server=True):
    if self.on_this_cluster():
        return None
    if not self.client:
        self.check_server(restart_server=restart_server)
        return self.client
    return self.client

def ext_tasks_search(request):
    resp = {}
    if request.method != 'POST':
        resp = {'error': True, 'error_value': 'Method not allowed'}
        return jsonize(resp, response=True)
    if not apiconf.extendedtasksearch.get('enabled'):
        resp = {'error': True, 'error_value': 'Extended Task Search API is Disabled'}
        return jsonize(resp, response=True)
    term = request.POST.get('option', '')
    value = request.POST.get('argument', '')
    if term and value:
        records = False
        if not term in search_term_map.keys() and term not in ('malscore', 'ttp'):
            resp = {'error': True, 'error_value': "Invalid Option. '%s' is not a valid option." % term}
            return jsonize(resp, response=True)
        if term == 'ids':
            if all([v.strip().isdigit() for v in value.split(',')]):
                value = [int(v.strip()) for v in filter(None, value.split(','))]
            else:
                return jsonize({'error': True, 'error_value': 'Not all values are integers'}, response=True)
        try:
            if term == 'malscore':
                records = perform_malscore_search(value)
            elif term == 'ttp':
                records = perform_ttps_search(value)
            else:
                records = perform_search(term, value)
        except ValueError:
            if not term:
                resp = {'error': True, 'error_value': 'No option provided.'}
            if not value:
                resp = {'error': True, 'error_value': 'No argument provided.'}
            if not term and (not value):
                resp = {'error': True, 'error_value': 'No option or argument provided.'}
        if records:
            ids = list()
            for results in records:
                if repconf.mongodb.enabled:
                    ids.append(results)
                if es_as_db:
                    ids.append(results['_source'])
            if term == 'ids':
                task_details = {task.id: task.status for task in db.list_tasks(task_ids=value) or []}
                for block in ids:
                    if block['info']['id'] in task_details:
                        block['status'] = task_details[block['info']['id']]
            resp = {'error': False, 'data': ids}
        else:
            resp = {'error': True, 'error_value': 'Unable to retrieve records'}
    else:
        if not term:
            resp = {'error': True, 'error_value': 'No option provided.'}
        if not value:
            resp = {'error': True, 'error_value': 'No argument provided.'}
        if not term and (not value):
            resp = {'error': True, 'error_value': 'No option or argument provided.'}
    return jsonize(resp, response=True)

def _sync_step_from_queue(self, step):
    try:
        item = self._get_json_response(step.data['master'], '/queue/item/{}'.format(step.data['item_id']))
    except NotFound:
        pass
        step.status = Status.finished
        step.result = Result.infra_failed
        db.session.add(step)
        self.logger.exception('Queued step not found in queue: {} (build: {})'.format(step.id, step.job.build_id))
        statsreporter.stats().incr('jenkins_item_not_found_in_queue')
        return
    if item.get('executable'):
        build_no = item['executable']['number']
        step.data['queued'] = False
        step.data['build_no'] = build_no
        step.data['uri'] = item['executable']['url']
        db.session.add(step)
    if item['blocked']:
        step.status = Status.queued
        db.session.add(step)
    elif item.get('cancelled') and (not step.data.get('build_no')):
        step.status = Status.finished
        step.result = Result.aborted
        db.session.add(step)
    elif item.get('executable'):
        return self._sync_step_from_active(step)

def expired(self):
    now_tz = timezone.now()
    now_local = now_tz.astimezone(timezone.get_default_timezone())
    if (self.date_expired is None or self.date_expired < now_local.date()) or (self.time_expired and self.time_expired < now_local.time() and (self.date_expired is None or self.date_expired == now_local.date())):
        return True
    return False

def _save_checkpoint(self, training_state, phase='main', new_best_macro=False, keep_all=False):
    if not self._serialization_dir:
        raise ConfigurationError('serialization_dir not specified - cannot restore a model without a directory path.')
    epoch = training_state['epoch']
    if phase == 'eval':
        model_path = os.path.join(self._serialization_dir, 'model_state_eval_best.th')
    else:
        best_str = '.best_macro' if new_best_macro else ''
        model_path = os.path.join(self._serialization_dir, 'model_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str))
    model_state = self._model.state_dict()
    keys_to_skip = [key for key in model_state if dont_save(key)]
    for key in keys_to_skip:
        del model_state[key]
    torch.save(model_state, model_path)
    if phase != 'eval':
        torch.save(training_state, os.path.join(self._serialization_dir, 'training_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str)))
        task_states = {}
        for (task_name, task_info) in self._task_infos.items():
            task_states[task_name] = {}
            task_states[task_name]['total_batches_trained'] = task_info['total_batches_trained']
            task_states[task_name]['stopped'] = task_info['stopped']
            if self._g_optimizer is None:
                task_states[task_name]['optimizer'] = task_info['optimizer'].state_dict()
                sched = task_info['scheduler']
                sched_params = {}
                task_states[task_name]['scheduler'] = sched_params
        task_states['global'] = {}
        task_states['global']['optimizer'] = self._g_optimizer.state_dict() if self._g_optimizer is not None else None
        if self._g_scheduler is not None:
            sched = self._g_scheduler
            sched_params = {}
            task_states['global']['scheduler'] = sched_params
        else:
            task_states['global']['scheduler'] = None
        torch.save(task_states, os.path.join(self._serialization_dir, 'task_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str)))
        metric_states = {}
        for (metric_name, metric_info) in self._metric_infos.items():
            metric_states[metric_name] = {}
            metric_states[metric_name]['hist'] = metric_info['hist']
            metric_states[metric_name]['stopped'] = metric_info['stopped']
            metric_states[metric_name]['best'] = metric_info['best']
        torch.save(metric_states, os.path.join(self._serialization_dir, 'metric_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str)))
    log.info('Saved files to %s', self._serialization_dir)
    if phase != 'eval' and new_best_macro:
        self._unmark_previous_best(phase, epoch)
    if not self._keep_all_checkpoints:
        self._delete_old_checkpoints(phase, epoch)

def on_darken_background_scale_change_value(self, widget, scroll, value):
    self.config['background_darkness'] = round(value, 1)
    self.config.save()

def _format_class_body(statements: List, context: Context) -> (List[str], int):
    formatted_lines = []
    previously_processed_line_number = context.previously_processed_line_number
    for statement in statements:
        formatted_lines += _reconstruct_blank_lines_in_range(previously_processed_line_number, statement.line, context.comments, ' ' * context.indent)
        previously_processed_line_number = statement.line
        if statement.data == 'tool_stmt':
            formatted_lines.append('{}tool'.format(' ' * context.indent))
        elif statement.data == 'class_def':
            name = statement.children[0].value
            formatted_lines.append('{}class {}:'.format(' ' * context.indent, name))
            (class_lines, last_processed_line) = _format_class_body(statement.children[1:], Context(indent=context.indent + 4, previously_processed_line_number=previously_processed_line_number, comments=context.comments))
            formatted_lines += class_lines
            previously_processed_line_number = last_processed_line
        if context.comments[statement.line] is not None:
            formatted_lines[-1] = '{}  {}'.format(formatted_lines[-1], context.comments[statement.line])
    formatted_lines += _reconstruct_blank_lines_in_range(previously_processed_line_number, -1, context.comments, ' ' * context.indent)
    return (formatted_lines, previously_processed_line_number)

def job_30_run(self, cr, uid, build, lock_path, log_path):
    log_all = build.path('logs', 'job_20_test_all.txt')
    log_time = time.localtime(os.path.getmtime(log_all))
    v = {'job_end': time.strftime(openerp.tools.DEFAULT_SERVER_DATETIME_FORMAT, log_time), 'result': 'ko'}
    if grep(log_all, 'openerp.modules.loading: Modules loaded.'):
        if not grep(log_all, 'FAIL'):
            v['result'] = 'ok'
    else:
        v['result'] = 'ko'
    build.write(v)
    try:
        state = 'success' if v['result'] == 'ok' else 'failure'
        status = {'state': state, 'target_url': 'http://runbot.odoo.com/runbot/build/%s' % build.name, 'description': 'runbot build %s (runtime %ss)' % (build.dest, build.job_time), 'context': 'continuous-integration/runbot'}
        build.repo_id.github('/repos/:owner/:repo/statuses/%s' % build.name, status)
        _logger.debug('github status %s update to %s', build.name, state)
    except Exception as e:
        _logger.exception('github status error')
    (cmd, mods) = build.cmd()
    if os.path.exists(build.path('openerp/addons/im')):
        cmd += ['--workers', '2']
        cmd += ['--longpolling-port', '%d' % (build.port + 1)]
        cmd += ['--max-cron-threads', '1']
    else:
        cmd += ['--max-cron-threads', '0']
    cmd += ['--log-level=debug']
    cmd += ['-d', '%s-all' % build.dest]
    if grep(build.path('openerp/tools/config.py'), 'db-filter'):
        if build.repo_id.nginx:
            cmd += ['--db-filter', '%d.*$']
        else:
            cmd += ['--db-filter', '%s.*$' % build.dest]
    return self.spawn(cmd, lock_path, log_path, cpu_limit=None)

def schedule(self, seen=None) -> List[ScheduleItem]:
    if seen is None:
        seen = set()
    if self in seen or self.realized or self.is_unrealized_const():
        return []
    seen.add(self)
    if self.base != self:
        return self.base.schedule(seen)
    op = self.op if self.op.op != LoadOps.CONTIGUOUS else LazyOp(UnaryOps.NOOP, self.op.src)
    if self.optype is BinaryOps:
        op = _ast_binaryops(op, self.shape)
    elif self.optype is ReduceOps:
        op = _ast_reduceops(op)
    ret = []
    for x in op.buffers:
        ret += x.schedule(seen)
    self.var_vals = dict(sorted(merge_dicts([self.var_vals] + [buf.var_vals for buf in op.buffers]).items(), key=lambda kv: cast(Variable, kv[0]).key))
    (op, base_bufs) = _replace_bufferops(op)
    return ret + [ScheduleItem(op, self, tuple(base_bufs))]

def _is_parent_child_types_consistent(type_parent, type_child):
    if type_parent in root_types:
        return True
    if type_child in root_types:
        return type_parent is None
    for acc_types in (assetliab_types, equity_types, incexp_types, trading_types):
        if type_child in acc_types and type_parent in acc_types:
            return True
    return False

def build_pipeline(path: PathLike, synonym_table_cache: SynonymTableCache, labels: List[str]) -> spacy.language.Language:
    synonym_table_paths = synonym_table_cache.get_synonym_table_paths()
    return assemble_pipeline(parquet_files=synonym_table_paths, labels=labels, output_dir=path)

def call_function(function_context: FunctionContext, function: typing.Callable, function_type: api_pb2.Function.FunctionType, buffer_item: api_pb2.BufferItem):
    input = unpack_input_buffer_item(buffer_item)
    output_buffer_id = input.output_buffer_id
    input_id = buffer_item.item_id
    args = function_context.deserialize(input.args)
    kwargs = function_context.deserialize(input.kwargs)
    try:
        res = function(*args, **kwargs)
        if function_type == api_pb2.Function.FunctionType.GENERATOR:
            if inspect.isgenerator(res):
                for value in res:
                    function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
                function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)
            elif inspect.isasyncgen(res):

                async def run_asyncgen():
                    async for value in res:
                        await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=await function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
                    await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)
                asyncio_run(run_asyncgen())
            else:
                raise Exception('Function of type generator returned a non-generator output')
        elif function_type == api_pb2.Function.FunctionType.FUNCTION:
            if inspect.iscoroutine(res):
                res = asyncio_run(res)
            function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(res))
        else:
            raise Exception(f'Unknown function type {function_type}')
    except Exception as exc:
        function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.FAILURE, data=function_context.serialize(exc), exception=repr(exc), traceback=traceback.format_exc())

def downloadPkgs(self, pkglist, callback=None):
    errors = {}
    self.plugins.run('predownload', pkglist=pkglist)
    repo_cached = False
    remote_pkgs = []
    for po in pkglist:
        if hasattr(po, 'pkgtype') and po.pkgtype == 'local':
            continue
        local = po.localPkg()
        if os.path.exists(local):
            cursize = os.stat(local)[6]
            totsize = int(po.size)
            try:
                result = self.verifyPkg(local, po, raiseError=1)
            except URLGrabError, e:
                repo = self.repos.getRepo(po.repoid)
                if repo.cache:
                    repo_cached = True
                    msg = 'package fails checksum but caching is enabled for %s' % repo.id
                    if not errors.has_key(po): errors[po] = []
                    errors[po].append(msg)
                if cursize >= totsize:
                    os.unlink(local)
            else:
                if result:
                    continue
                else:
                    if cursize >= totsize:
                        os.unlink(local)
        remote_pkgs.append(po)
        if (self.conf.cache or repo_cached) and errors:
            return errors
    i = 0
    for po in remote_pkgs:
        i += 1
        repo = self.repos.getRepo(po.repoid)
        checkfunc = (self.verifyPkg, (po, 1), {})
        statvfs = os.statvfs(repo.localpath)
        available_space = statvfs.f_frsize * statvfs.f_bavail
        if available_space < po.size:
            raise Exception('Not enough disk space to download the package: %s' % os.path.basename(po.returnSimple('relativepath')))
        try:
            text = '(%s/%s): %s' % (i, len(remote_pkgs),
                                    os.path.basename(po.returnSimple('relativepath')))
            mylocal = repo.getPackage(po,
                               checkfunc=checkfunc,
                               text=text,
                               cache=repo.http_caching != 'none',
                               )
        except Errors.RepoError, e:
            if not errors.has_key(po):
                errors[po] = []
            errors[po].append(str(e))
        else:
            po.localpath = mylocal
            if errors.has_key(po):
                del errors[po]
    self.plugins.run('postdownload', pkglist=pkglist, errors=errors)
    return errors

def free_energy(self, v_sample):
    h_mean = T.nnet.sigmoid(T.dot(v_sample, self.W) + self.hbias)
    stable_log_h_mean = T.log(T.clip(h_mean, 1e-10, 1 - 1e-10))
    return -T.sum(stable_log_h_mean) - T.sum(T.dot(v_sample, self.vbias))

from typing import Iterable
from math import prod
import functools
import operator

def prod(x: Iterable[int]) -> int:
    return functools.reduce(operator.__mul__, x, 1)

def _append_required_defaults(self, kwargs, algorithm_inputs):
    if algorithm_inputs is None:
        return
    for entry in algorithm_inputs:
        if entry[self.KEY_NAME] not in kwargs and entry.get(self.KEY_REQUIRED) is True and (self.KEY_DEFAULT in entry) and (entry[self.KEY_TYPE] != xml_reader.TYPE_DICT):
            kwargs[entry[self.KEY_NAME]] = entry[self.KEY_DEFAULT]
    for entry in algorithm_inputs:
        if entry.get(self.KEY_REQUIRED) is True and entry.get(ABCAdapter.KEY_OPTIONS) is not None:
            for option in entry[ABCAdapter.KEY_OPTIONS]:
                if option[self.KEY_VALUE] == kwargs[entry[self.KEY_NAME]] and ABCAdapter.KEY_ATTRIBUTES in option:
                    option[ABCAdapter.KEY_ATTRIBUTES] = self._append_required_defaults(kwargs, option[self.KEY_ATTRIBUTES]) or option[ABCAdapter.KEY_ATTRIBUTES]

def center_land(world):
    min_sum_on_y = None
    y_with_min_sum = None
    latshift = 0
    for y in range(world.height):
        sum_on_y = world.elevation['data'][y].sum()
        if min_sum_on_y is None or sum_on_y < min_sum_on_y:
            min_sum_on_y = sum_on_y
            y_with_min_sum = y
    if get_verbose():
        print('geo.center_land: height complete')
    min_sum_on_x = None
    x_with_min_sum = None
    for x in range(world.width):
        sum_on_x = world.elevation['data'].T[x].sum()
        if min_sum_on_x is None or sum_on_x < min_sum_on_x:
            min_sum_on_x = sum_on_x
            x_with_min_sum = x
    if get_verbose():
        print('geo.center_land: width complete')
    new_elevation_data = numpy.zeros((world.height, world.width))
    new_plates = numpy.empty((world.height, world.width), dtype=object)
    for y in range(world.height):
        src_y = (y_with_min_sum + y - latshift) % world.height
        for x in range(world.width):
            src_x = (x_with_min_sum + x) % world.width
            new_elevation_data[y, x] = world.elevation['data'][src_y, src_x]
            new_plates[y, x] = world.plates[src_y][src_x]
    world.elevation['data'] = new_elevation_data
    world.plates = new_plates
    if get_verbose():
        print('geo.center_land: width complete')

def describe_resource(source, *, expand=False, nostats=False, **options):
    resource = Resource(source, **options)
    resource.infer(stats=not nostats)
    if expand:
        resource.expand()
    return resource

