def _initialize_system(self):
    if self.install_config['ui']:
        self.progress_bar.update_message('Initializing system...')
    self._bind_installer()
    self._bind_repo_dir()
    self.cmd.run(['mkdir', '-p', os.path.join(self.photon_root, 'var/lib/rpm')])
    retval = self.cmd.run(['rpm', '--root', self.photon_root, '--initdb', '--dbpath', '/var/lib/rpm'])
    if retval != 0:
        self.logger.error('Failed to initialize rpm DB')
        self.exit_gracefully()
    tdnf_cmd = 'tdnf install filesystem --installroot {0} --assumeyes -c {1}'.format(self.photon_root, self.tdnf_conf_path)
    retval = self.cmd.run(tdnf_cmd)
    if retval != 0:
        retval = self.cmd.run(['docker', 'run', '-v', self.rpm_cache_dir + ':' + self.rpm_cache_dir, '-v', self.working_directory + ':' + self.working_directory, 'photon:3.0', '/bin/sh', '-c', tdnf_cmd])
        if retval != 0:
            self.logger.error('Failed to install filesystem rpm')
            self.exit_gracefully()
    devices = {'console': (600, stat.S_IFCHR, 5, 1), 'null': (666, stat.S_IFCHR, 1, 3), 'random': (444, stat.S_IFCHR, 1, 8), 'urandom': (444, stat.S_IFCHR, 1, 9)}
    for (device, (mode, dev_type, major, minor)) in devices.items():
        os.mknod(os.path.join(self.photon_root, 'dev', device), mode | dev_type, os.makedev(major, minor))

