def dump_lic(self, location, license_dict):
    license_name = license_context = license_url = ''
    loc = util.to_posix(location)
    parent = posixpath.dirname(loc)
    license_key_name_context_url = []
    if not posixpath.exists(parent):
        os.makedirs(add_unc(parent))
    if self.license_expression.present:
        (special_char_in_expression, lic_list) = parse_license_expression(self.license_expression.value)
        self.license_key.value = lic_list
        self.license_key.present = True
        if not special_char_in_expression:
            for lic_key in lic_list:
                try:
                    if license_dict[lic_key]:
                        license_path = posixpath.join(parent, lic_key)
                        license_path += u'.LICENSE'
                        license_path = add_unc(license_path)
                        (license_name, license_filename, license_context, license_url) = license_dict[lic_key]
                        license_info = (lic_key, license_name, license_filename, license_context, license_url)
                        license_key_name_context_url.append(license_info)
                        with io.open(license_path, mode='w', encoding='utf-8', newline='\n', errors='replace') as lic:
                            lic.write(license_context)
                except Exception as e:
                    return str(e)
    return license_key_name_context_url

def TransformerRevnetLM(vocab_size, d_model=512, d_ff=2048, d_attention_key=64, d_attention_value=64, n_layers=6, n_heads=8, dropout=0.1, max_len=2048, n_chunks=32, n_attention_chunks=8, attention_type=DotProductAttention, mode='train'):
    positional_embedder = [tl.Embedding(d_model, vocab_size), tl.Dropout(rate=dropout), tl.PositionalEncoding(max_len=max_len)]
    return tl.Model(tl.Concatenate(n_items=n_chunks), tl.ShiftRight(), positional_embedder, tl.Dup(), tl.ReversibleSerial([DecoderBlock(d_model, d_ff, d_attention_key, d_attention_value, n_heads, n_attention_chunks, attention_type, dropout, mode) for _ in range(n_layers)]), tl.Parallel(tl.LayerNorm(), tl.LayerNorm()), tl.Concatenate(), Split(n_sections=n_chunks, axis=-2), Map([tl.Dense(vocab_size), tl.LogSoftmax()], n_sections=n_chunks))

