def get_make_environment_vars():
    environment = {}
    result = subprocess.run(
        ["make", "-f", "Makefile.envs", ".output_vars"],
        capture_output=True,
        text=True,
    )
    for line in result.stdout.splitlines():
        equalPos = line.find("=")
        if equalPos != -1:
            varname = line[0:equalPos]
            value = line[equalPos + 1 :]
            value = value.strip("'\").strip()
            environment[varname] = value
    return environment

def connectionLost(self, reason):
    txtorlog.msg('connection terminated: ' + str(reason))
    if reason.check(ConnectionDone):
        self._when_disconnected.fire(self)
    else:
        self._when_disconnected.fire(reason)
    outstanding = [self.command] + self.commands if self.command else self.commands
    for (d, cmd, cmd_arg) in outstanding:
        if not d.called:
            d.errback(Failure(TorDisconnectError(text='Tor unexpectedly disconnected while running: {}'.format(cmd.decode('ascii')), error=reason)))
    return None

