def on_key_press(self, event):
    if event.native.isAutoRepeat() or event.key is None:
        return
    comb = components_to_key_combo(event.key.name, event.modifiers)
    layer = self.viewer.active_layer
    if layer is not None and comb in layer.keymap:
        parent = layer
    elif comb in self.viewer.keymap:
        parent = self.viewer
    else:
        return
    func = parent.keymap[comb]
    gen = func(parent)
    if inspect.isgeneratorfunction(func):
        try:
            next(gen)
        except StopIteration:
            pass
        else:
            self._key_release_generators[event.key] = gen

def load(source):
    data = (yield from BytesType.load(source))
    return data.decode('utf-8', 'strict')

async def post_ev_segment(profile: Profile, session: Session, event_types: list, load_segments: Callable) -> dict:
    segmentation_result = {'errors': [], 'ids': []}
    try:
        if profile.needs_update() or profile.needs_segmentation():
            async for (event_type, segment_id, error) in _segment(profile, session, event_types, load_segments):
                if error:
                    segmentation_result['errors'].append(error)
                segmentation_result['ids'].append(segment_id)
    except Exception as e:
        logger.error(str(e))
        logger.error('Segmentation error occurred')
    finally:
        return segmentation_result

