def rm_old_files(rootdir, excludes=None, includes=None, expire_time=30 * DAY):
    if excludes is None:
        excludes = []
    if includes is None:
        includes = []

    def is_wanted(path):
        return not any((fnmatch.fnmatch(path, pattern) for pattern in excludes)) and (not includes or any((fnmatch.fnmatch(path, pattern) for pattern in includes)))
    os.chdir(rootdir)
    expiration_date = time.time() - expire_time
    for path in filter(lambda e: os.stat(e).st_ctime < expiration_date and is_wanted(e), os.listdir('.')):
        sys.stdout.write('Removing "%s/%s"\n' % (rootdir, path))
        if os.path.isdir(path):
            for (root, __, files) in os.walk(path, topdown=False):
                for f in files:
                    os.unlink(os.path.join(root, f))
            os.rmdir(path)
        else:
            os.unlink(path)

def remove(self, docid_or_path_tuple):
    if isinstance(docid_or_path_tuple, int):
        path_tuple = self.docid_to_path[docid_or_path_tuple]
    elif isinstance(docid_or_path_tuple, tuple):
        path_tuple = docid_or_path_tuple
    else:
        raise ValueError('remove accepts only a docid or a path tuple, got' % (docid_or_path_tuple,))
    pathlen = len(path_tuple)
    dmap = self.pathindex.get(path_tuple)
    if dmap is None:
        return set()
    removed = set()
    items = sorted(dmap.items())
    for (k, dm) in list(self.pathindex.items()):
        if k[:pathlen] == path_tuple:
            for didset in dm.values():
                removed.update(didset)
                for did in didset:
                    if did in self.docid_to_path:
                        p = self.docid_to_path[did]
                        del self.docid_to_path[did]
                        del self.path_to_docid[p]
            del self.pathindex[k]
    for x in range(pathlen - 1):
        offset = x + 1
        els = path_tuple[:pathlen - offset]
        dmap2 = self.pathindex.get(els)
        for (level, didset) in items:
            i = level + offset
            didset2 = dmap2.get(i)
            if didset2 is None:
                continue
            for did in didset:
                if did in didset2:
                    didset2.remove(did)
                    assert did in removed, did
                    assert not did in self.docid_to_path, did
            if not didset2:
                del dmap2[i]
    return removed

def list_evaluation_jobs(self, parent, filter_, page_size=None, retry=google.api_core.gapic_v1.method.DEFAULT, timeout=google.api_core.gapic_v1.method.DEFAULT, metadata=None):
    if 'list_evaluation_jobs' not in self._inner_api_calls:
        self._inner_api_calls['list_evaluation_jobs'] = google.api_core.gapic_v1.method.wrap_method(self.transport.list_evaluation_jobs, default_retry=self._method_configs['ListEvaluationJobs'].retry, default_timeout=self._method_configs['ListEvaluationJobs'].timeout, client_info=self._client_info)
    request = data_labeling_service_pb2.ListEvaluationJobsRequest(parent=parent, filter=filter_, page_size=page_size)
    if metadata is None:
        metadata = []
    metadata = list(metadata)
    try:
        routing_header = [('parent', parent)]
    except AttributeError:
        pass
    else:
        routing_metadata = google.api_core.gapic_v1.routing_header.to_grpc_metadata(routing_header)
        metadata.append(routing_metadata)
    iterator = google.api_core.page_iterator.GRPCIterator(client=None, method=functools.partial(self._inner_api_calls['list_evaluation_jobs'], retry=retry, timeout=timeout, metadata=metadata), request=request, items_field='evaluation_jobs', request_token_field='page_token', response_token_field='next_page_token')
    return iterator

def _get_pod_unschedulable_reason(self, pod: KubernetesPod) -> PodUnschedulableReason:
    pod_resource_request = total_pod_resources(pod)
    for (node_ip, pods_on_node) in self._pods_by_ip.items():
        node = self._nodes_by_ip.get(node_ip)
        if node and pod_resource_request < total_node_resources(node) - allocated_node_resources(pods_on_node):
            return PodUnschedulableReason.Unknown
    return PodUnschedulableReason.InsufficientResources

def __init__(self, path, mode='r', schema=None, dshape=None, dialect=None, header=None, open=open, **kwargs):
    if 'r' in mode and os.path.isfile(path) is not True:
        raise ValueError('CSV file "%s" does not exist' % path)
    self.path = path
    self.mode = mode
    self.open = open
    if not schema and (not dshape):
        schema = self.dshape
        if schema is None:
            raise ValueError('No schema detected')
    if not schema and dshape:
        dshape = datashape.dshape(dshape)
        if isinstance(dshape[0], datashape.Var):
            schema = dshape.subarray(1)
    self._schema = schema
    if os.path.exists(path) and mode != 'w':
        with self.open(path, 'r') as f:
            sample = f.read(1024)
    else:
        sample = ''
    dialect = discover_dialect(sample, dialect, **kwargs)
    assert dialect
    if header is None:
        header = has_header(sample)
    self.header = header
    self.dialect = dialect

