def _upload_data_frame(self, data_frame, end_stream):
    data = {'name': self._timeline_name, 'sketch_id': self._sketch.id, 'enable_stream': not end_stream, 'data_label': self._data_label, 'provider': self._provider, 'events': data_frame.to_json(orient='records', lines=True)}
    if self._index:
        data['index_name'] = self._index
    if self._upload_context:
        data['context'] = self._upload_context
    response = self._sketch.api.session.post(self._resource_url, data=data)
    self._chunk += 1
    if response.status_code not in definitions.HTTP_STATUS_CODE_20X:
        response = self._sketch.api.session.post(self._resource_url, data=data)
        if response.status_code not in definitions.HTTP_STATUS_CODE_20X:
            raise RuntimeError('Error uploading data: [{0:d}] {1!s} {2!s}, index {3:s}'.format(response.status_code, response.reason, response.text, self._index))
    response_dict = response.json()
    object_dict = response_dict.get('objects', [{}])[0]
    self._timeline_id = object_dict.get('id')
    self._index = object_dict.get('searchindex', {}).get('index_name')
    self._last_response = response_dict

def _validate(self, efs_id, avail_zones_mapping: dict, are_all_security_groups_customized):
    for (avail_zone, subnets) in avail_zones_mapping.items():
        head_node_target_id = AWSApi.instance().efs.get_efs_mount_target_id(efs_id, avail_zone)
        if head_node_target_id:
            sg_ids = AWSApi.instance().efs.get_efs_mount_target_security_groups(head_node_target_id)
            if not _check_in_out_access(sg_ids, port=2049, is_cidr_optional=are_all_security_groups_customized):
                self._add_failure("There is an existing Mount Target {0} in the Availability Zone {1} for EFS {2}, but it does not have a security group that allows inbound and outbound rules to support NFS. Please modify the Mount Target's security group, to allow traffic on port 2049.".format(head_node_target_id, avail_zone, efs_id), FailureLevel.ERROR)
            if not are_all_security_groups_customized:
                self._check_cidrs_cover_subnets(head_node_target_id, avail_zone, sg_ids, efs_id, subnets)
        elif AWSApi.instance().efs.is_efs_standard(efs_id):
            self._add_failure('There is no existing Mount Target in the Availability Zone {0} for EFS {1}. Please create an EFS Mount Target for the Availability Zone {0}.'.format(avail_zone, efs_id), FailureLevel.ERROR)
        else:
            self._add_failure('EFS is in OneZone storage class, please ensure appropriate configurations are in place for OneZone EFS in Availability Zone {0}.'.format(avail_zone), FailureLevel.WARNING)

def visit_Call(self, node):
    self.generic_visit(node)
    func = node.func
    if not isinstance(func, ast.Name):
        return
    if func.id != '_':
        return
    for arg in node.args:
        if isinstance(arg, ast.BinOp) and isinstance(arg.op, ast.Add):
            return (node, 'G100 string concatenation that will break xgettext')
        if isinstance(arg, ast.Name):
            return (node, 'G101 variable reference that will break xgettext')
        if isinstance(arg, ast.BinOp) and isinstance(arg.op, ast.Mod):
            return (node, 'G102 Mod operator is acceptable for translation')

def extract(self, parent_sequence, references=None):
    if self.ref or self.ref_db:
        if not references:
            raise ValueError(f'Feature references another sequence ({self.ref}), references mandatory')
        elif self.ref not in references:
            raise ValueError(f'Feature references another sequence ({self.ref}), not found in references')
        parent_sequence = references[self.ref]
    f_seq = parent_sequence[int(self.start):int(self.end)]
    if isinstance(f_seq, MutableSeq):
        f_seq = Seq(f_seq)
    if self.strand == -1:
        f_seq = reverse_complement(f_seq, inplace=False)
    return f_seq

