def _loadChangelog(self):
    result = []
    if not self._changelog:
        if not self.sack.otherdb.has_key(self.repo):
            raise Exception('Repository not found in otherdb')
            self._changelog = result
            return
        cache = self.sack.otherdb[self.repo]
        cur = cache.cursor()
        cur.execute('select changelog.date as date, changelog.author as author, changelog.changelog as changelog from packages,changelog where packages.pkgId = %s and packages.pkgKey = changelog.pkgKey', self.pkgId)
        for ob in cur.fetchall():
            result.append((ob['date'], ob['author'], ob['changelog']))
    self._changelog = result

def geteltorito(self, cdfile, outfile):
    cdfile = open(cdfile, "r")
    cdfile.seek(17*2048)
    fmt = "=B5sB23s41sI"
    spec = cdfile.read(struct.calcsize(fmt))
    (boot, isoIdent, version, toritoSpec, unused, bootP) = struct.unpack(fmt, spec)
    if boot != 0x0:
        raise Exception, "invalid boot"
    if version != 0x1:
        raise Exception, "invalid version"
    if isoIdent != "CD001" or toritoSpec != "EL TORITO SPECIFICATION":
        raise Exception, "isoIdentification not correct"
    cdfile.seek(bootP*2048)
    fmt = "=BBH24sHBB"
    bootdata = cdfile.read(struct.calcsize(fmt))
    (header, platform, unused, manu, checksum, five, aa) = struct.unpack(fmt, bootdata)
    if header != 0x1:
        raise Exception, "invalid header"
    if platform != 0x0 and platform != 0x1 and platform != 0x2:
        raise Exception, "invalid platform"
    if unused != 0x0:
        raise Exception, "invalid unused boot sector field"
    if five != 0x55 or aa != 0xaa:
        raise Exception, "invalid footer"
    if (sum(struct.unpack("=H", bootdata[i:i+2])[0] for i in range(0, len(bootdata), 2)) % 65536) != 0:
        raise Exception, "invalid checksum"
    cdfile.seek(bootP*2048+32)
    fmt = "=BBHBBHIB"
    defaultentry = cdfile.read(struct.calcsize(fmt))
    (boot, media, loadsegment, systemtype, unused, scount, imgstart, unused2) = struct.unpack(fmt, defaultentry)
    if boot != 0x88:
        raise Exception, "invalid boot indicator"
    if unused != 0x0 or unused2 != 0x0:
        raise Exception, "invalid unused initial boot field"
    if media == 0 or media == 4:
        count = scount
    elif media == 1:
        count = 1200*1024/512
    elif media == 2:
        count = 1440*1024/512
    elif media == 3:
        count = 2880*1024/512
    else:
        raise Exception, "invalid media type"
    cdfile.seek(imgstart*2048)
    eltoritodata = cdfile.read(count*2048)
    cdfile.close()
    out = open(outfile, "w")
    out.write(eltoritodata)
    out.close()

def _CsvToExample(pipeline: beam.Pipeline, exec_properties: Dict[Text, Any], split_pattern: Text) -> beam.pvalue.PCollection:
    input_base_uri = exec_properties[utils.INPUT_BASE_KEY]
    csv_pattern = os.path.join(input_base_uri, split_pattern)
    logging.info('Processing input csv data %s to TFExample.', csv_pattern)
    csv_files = tf.io.gfile.glob(csv_pattern)
    if not csv_files:
        raise RuntimeError('Split pattern {} does not match any files.'.format(csv_pattern))
    column_names = io_utils.load_csv_column_names(csv_files[0])
    for csv_file in csv_files[1:]:
        if io_utils.load_csv_column_names(csv_file) != column_names:
            raise RuntimeError('Files in same split {} have different header.'.format(csv_pattern))
    parsed_csv_lines = pipeline | 'ReadFromText' >> beam.io.ReadFromText(file_pattern=csv_pattern, skip_header_lines=1) | 'ParseCSVLine' >> beam.ParDo(csv_decoder.ParseCSVLine(delimiter=','))
    parsed_csv_lines = parsed_csv_lines | 'ExtractParsedCSVLines' >> beam.Keys() if getattr(csv_decoder, 'PARSE_CSV_LINE_YIELDS_RAW_RECORDS', False) else parsed_csv_lines
    column_infos = beam.pvalue.AsSingleton(parsed_csv_lines | 'InferColumnTypes' >> beam.CombineGlobally(csv_decoder.ColumnTypeInferrer(column_names, skip_blank_lines=True)))
    return parsed_csv_lines | 'ToTFExample' >> beam.ParDo(_ParsedCsvToTfExample(), column_infos)

def visitMultiplyingExpression(self, ctx):
    left = float(self.visit(ctx.powExpression(0)))
    ops = [char for char in ctx.getText() if char == '*' or char == '/']
    for i in range(1, len(ctx.powExpression())):
        right = float(self.visit(ctx.powExpression(i)))
        if ops[i - 1] == '*':
            left *= right
        else:
            left /= right
    return left

