def path2url(path):
    if sys.platform.startswith('java'):
        href = os.path.abspath(path)
        return 'file:' + href.replace('\\', '/')
    else:
        return u'file:' + urllib.pathname2url(os.path.abspath(path))

def validate_output_dir(directory):
    if os.path.isfile(directory):
        directory = os.path.split(directory)[0]
    if not os.path.isdir(directory):
        LOG.info('Directory [{}] does not exist. Trying to create it.'.format(directory))
        os.makedirs(directory)
    elif not os.access(directory, os.W_OK):
        LOG.error(f'No write access allowed to output directory [{directory}]. Aborting.')
        exit(1)

