def room_input_cb(server_name, buffer, input_data):
    server = SERVERS[server_name]
    if not server.connected:
        message = '{prefix}you are not connected to the server'.format(prefix=W.prefix('error'))
        W.prnt(buffer, message)
        return W.WEECHAT_RC_ERROR

    def send_message(server, buffer, input_data):
        room_id = list(server.buffers.keys())[list(server.buffers.values()).index(buffer)]
        body = {'msgtype': 'm.text', 'body': input_data}
        message = generate_matrix_request(server, MessageType.POST_MSG, data=body, room_id=room_id)
        send_or_queue(server, message)
    send_message(server, buffer, input_data)
    return W.WEECHAT_RC_OK

def write_full_dns_config(zones=None, reverse_zones=None, callback=None, **kwargs):
    if zones is None:
        zones = {}
    if reverse_zones is None:
        reverse_zones = {}
    for (zone_name, zone_data) in zones.items():
        DNSZoneConfig(zone_name).write_config(**zone_data)
    for (zone_name, zone_data) in reverse_zones.items():
        DNSZoneConfig(zone_name).write_config(**zone_data)
    config = DNSConfig(zone_names=list(zones), reverse_zone_names=list(reverse_zones))
    config.write_config(**kwargs)
    if callback is not None:
        callback.delay()

