def create_javadoc_command(self, classpath, gendir, *targets):
    sources = []
    for target in targets:
        sources.extend(target.sources_relative_to_buildroot())
    if not sources:
        return None
    command = ['javadoc', '-quiet', '-encoding', 'UTF-8', '-notimestamp', '-use', '-classpath', ':'.join(classpath), '-d', gendir]
    command.extend(['-J{0}'.format(jvm_option) for jvm_option in self.jvm_options])
    offlinelinks = set(['http://download.oracle.com/javase/6/docs/api/'])

    def link(target):
        for jar in target.jar_dependencies:
            if jar.apidocs:
                offlinelinks.add(jar.apidocs)
    for target in targets:
        target.walk(link, lambda t: t.is_jvm)
    for link in offlinelinks:
        command.extend(['-linkoffline', link, link])
    command.extend(self.args)
    command.extend(sources)
    return command

def _create_row_control(self, option):
    if isinstance(option, Backend.SliderOption):
        return self.widgets.create_row_widget(option.label, self._create_control_slider(option))
    elif isinstance(option, Backend.ToggleOption):
        return self.widgets.create_row_widget(option.label, self._create_control_toggle(option))
    elif isinstance(option, Backend.MultipleChoiceOption):
        return self.widgets.create_row_widget(option.label, self._create_control_select(option))
    elif isinstance(option, Backend.ButtonOption):
        return self.widgets.create_row_widget(option.label, self._create_control_button(option))

def get_record(self, record, archive):
    r = super(AWEKASThread, self).get_record(record, archive)
    rr = archive.getSql('select rainRate from archive where dateTime=?', (r['dateTime'],))
    if rr is not None:
        datadict = dict(zip(['rainRate'], rr))
