def from_json_dict(cls, json_dict: dict):
    if 'output_of' in json_dict:
        output_of = json_dict['output_of']
        try:
            (node_id, node_output_name) = output_of.rsplit('.', maxsplit=1)
        except ValueError:
            raise ValueError('Invalid format for output_of: {}'.format(output_of))
        return cls(node_id, node_output_name)
    return None

def _get_done_status(self, generated, batch):
    done_idx = torch.minimum((generated != self.EOS_TOKEN_ID).sum(dim=-1) - batch.prompt_rindex, torch.tensor(self.max_new_tokens - 1))
    done = torch.zeros(done_idx.numel(), self.max_new_tokens, dtype=torch.bool, device=generated.device)
    return done.scatter(-1, done_idx.unsqueeze(-1), 1).unsqueeze(-1)

def send_bytes(self, packet_id, payload=[], system_id='N'):
    length = len(payload)
    payload_size = 0
    if packet_id in ('0', '1'):
        payload_size = 4 * length + 1
    if packet_id in '2':
        payload_size = 2 * length + 1
    packet_size = 3 + payload_size + 1
    if packet_size >= MAX_PACKET_SIZE:
        return False
    byte_array = struct.pack("cc",
                             START_OF_PACKET.encode('ascii'),
                             packet_id.encode('ascii'))
    if packet_id in ('0', '1'):
        byte_array += payload_size.to_bytes(1, 'big')
        byte_array += system_id.encode('ascii')
        for float_value in payload:
            byte_array += float_to_bin(float_value)
    if packet_id in '2':
        byte_array += payload_size.to_bytes(1, 'big')
        byte_array += system_id.encode('ascii')
        for pixel in payload:
            byte_array += 2_bytes_to_bin(pixel)
    if packet_id in ('0', '1', '2'):
        crc = 0
        for char in byte_array[3:]:
            crc = compute_crc8ccitt(crc, char)
        byte_array += struct.pack("c", crc.to_bytes(1, 'big'))
    self.serial.write(byte_array)
    if self.prints:
        print(f'Sending {START_OF_PACKET} {packet_id} {payload_size} {system_id} {payload} {crc} as {byte_array}')
    return True

def get_persisted_stats(self, index_node=None):
    persisted_stats_list = ['last_known_scan_time', 'avg_scan_rate', 'num_rows_scanned', 'num_rollbacks', 'num_rollbacks_to_zero']
    if index_node is None:
        index_node = self.get_nodes_from_services_map(service_type='index', get_all_nodes=True)[0]
    self.index_rest = RestConnection(index_node)
    stats = self.index_rest.get_all_index_stats()
    result = {}
    for (stat, value) in stats.items():
        for persisted_stat in persisted_stats_list:
            if f':{persisted_stat}' in stat:
                result[stat] = value
    return result

def next_inputs(self, time, outputs, state, sample_ids):
    (finished, base_next_inputs, state) = super(ScheduledOutputTrainingSampler, self).next_inputs(time=time, outputs=outputs, state=state, sample_ids=sample_ids)
    sample_ids = tf.cast(sample_ids, tf.bool)

    def maybe_sample():

        def maybe_concatenate_auxiliary_inputs(outputs_, indices=None):
            if self._auxiliary_input_tas is None:
                return outputs_
            next_time = time + 1
            auxiliary_inputs = tf.nest.map_structure(lambda ta: ta.read(next_time), self._auxiliary_input_tas)
            if indices is not None:
                auxiliary_inputs = tf.gather_nd(auxiliary_inputs, indices)
            return tf.nest.map_structure(lambda x, y: tf.concat((x, y), -1), outputs_, auxiliary_inputs)
        if self.next_inputs_fn is None:
            return tf.compat.v1.where(sample_ids, maybe_concatenate_auxiliary_inputs(outputs), base_next_inputs)
        where_sampling = tf.cast(tf.where(sample_ids), tf.int32)
        where_not_sampling = tf.cast(tf.where(tf.logical_not(sample_ids)), tf.int32)
        outputs_sampling = tf.gather_nd(outputs, where_sampling)
        inputs_not_sampling = tf.gather_nd(base_next_inputs, where_not_sampling)
        sampled_next_inputs = maybe_concatenate_auxiliary_inputs(self.next_inputs_fn(outputs_sampling), where_sampling)
        base_shape = tf.shape(base_next_inputs)
        return tf.scatter_nd(indices=where_sampling, updates=sampled_next_inputs, shape=base_shape) + tf.scatter_nd(indices=where_not_sampling, updates=inputs_not_sampling, shape=base_shape)
    all_finished = tf.reduce_all(finished)
    no_samples = tf.logical_not(tf.reduce_any(sample_ids))
    next_inputs = tf.cond(tf.logical_or(all_finished, no_samples), lambda : base_next_inputs, maybe_sample)
    return (finished, next_inputs, state)

def get_fallback_value(self, bounds=None, bases=None) -> Value:
    if bounds and bases:
        return SomeSmartValue(bounds, bases)
    return AnyValue(AnySource.inference)

def new_netting_channel(self, peer1, peer2, settle_timeout):
    if not isaddress(peer1):
        raise ValueError('The peer1 must be a valid address')
    if not isaddress(peer2):
        raise ValueError('The peer2 must be a valid address')
    if settle_timeout < NETTINGCHANNEL_SETTLE_TIMEOUT_MIN:
        raise ValueError('settle_timeout must be larger-or-equal to {}'.format(NETTINGCHANNEL_SETTLE_TIMEOUT_MIN))
    if privatekey_to_address(self.client.privkey) == peer1:
        other = peer2
    else:
        other = peer1
    transaction_hash = estimate_and_transact(self, self.proxy.newChannel, other, settle_timeout)
    try:
        self.client.poll(transaction_hash.decode('hex'), timeout=self.poll_timeout)
    except JSONRPCPollTimeoutException as e:
        raise e
    except InvalidTransaction as e:
        raise e
    netting_channel_results_encoded = self.proxy.getChannelWith.call(other, startgas=self.startgas)
    netting_channel_address_encoded = netting_channel_results_encoded
    if not netting_channel_address_encoded:
        log.error('netting_channel_address failed', peer1=pex(peer1), peer2=pex(peer2))
        raise RuntimeError('netting_channel_address failed')
    netting_channel_address_bin = address_decoder(netting_channel_address_encoded)
    log.info('new_netting_channel called', peer1=pex(peer1), peer2=pex(peer2), netting_channel=pex(netting_channel_address_bin))
    return netting_channel_address_bin

def iterTiltPairs(self):
