def run(self):
    while True:
        signal = self.link.get()
        if signal == 'pause':
            continue
        elif signal == 'stop':
            logger.info('Acquirer is stopping')
            return
        try:
            self.runAcquirer()
            if self.done:
                logger.info('Acquirer is exiting')
                return
        except Exception as e:
            logger.error('Acquirer exception during run: {}'.format(e))
            break

def _visit_partitionable_operation(self, operation_def, upstream_views):
    if len(upstream_views) < 2:
        (upstream_view,) = upstream_views
    else:
        raise ValueError('Multiple upstream views are not supported yet.')
    prefer_fine_grained_view = upstream_view.prefer_fine_grained_view or (upstream_view.fine_grained_view and operation_def.cache_coder is not None)
    next_hashed_path = self._make_next_hashed_path([v.hashed_path for v in upstream_views], operation_def)
    if upstream_view.fine_grained_view:
        fine_grained_views = (self._apply_operation_on_fine_grained_view(operation_def, upstream_view.fine_grained_view, next_hashed_path),)
    else:
        fine_grained_views = (None,) * operation_def.num_outputs
    flattened_views = nodes.OperationNode(operation_def, (upstream_view.flattened_view,)).outputs
    assert len(fine_grained_views) == len(flattened_views)
    return tuple((_OptimizationView(prefer_fine_grained_view=prefer_fine_grained_view, flattened_view=flat, fine_grained_view=fine, hashed_path=next_hashed_path) for (flat, fine) in zip(flattened_views, fine_grained_views)))

def _preprocess(features, wires, pad_with, normalize):
    if qml.tape_mode_active():
        shape = qml.math.shape(features)
        if len(shape) != 1:
            raise ValueError(f'Features must be a one-dimensional tensor; got shape {shape}.')
        n_features = shape[0]
        if pad_with is None and n_features != 2 ** len(wires):
            raise ValueError(f"Features must be of length {2 ** len(wires)}; got length {n_features}. Use the 'pad' argument for automated padding.")
        if pad_with is not None and n_features > 2 ** len(wires):
            raise ValueError(f'Features must be of length {2 ** len(wires)} or smaller to be padded; got length {n_features}.')
        if pad_with is not None and n_features < 2 ** len(wires):
            padding = [pad_with] * (2 ** len(wires) - n_features)
            features = qml.math.concatenate([features, padding], axis=0)
        norm = qml.math.sum(qml.math.abs(features) ** 2)
        if not qml.math.allclose(norm, 1.0, atol=TOLERANCE):
            if normalize or pad_with:
                features = features / np.sqrt(norm)
            else:
                raise ValueError(f"Features must be a vector of length 1.0; got length {norm}. Use 'normalize=True' to automatically normalize.")
    else:
        n_amplitudes = 2 ** len(wires)
        expected_shape = (n_amplitudes,)
        if len(get_shape(features)) > 1:
            raise ValueError(f'Features must be a one-dimensional vector; got shape {get_shape(features)}.')
        if pad_with is None:
            shape = check_shape(features, expected_shape, msg="Features must be of length {}; got {}. Use the 'pad' argument for automated padding.".format(expected_shape, get_shape(features)))
        else:
            shape = check_shape(features, expected_shape, bound='max', msg='Features must be of length {} or smaller to be padded; got {}'.format(expected_shape, get_shape(features)))
        check_type(pad_with, [float, complex, type(None)], msg="'pad' must be a float or complex; got {}".format(pad_with))
        check_type(normalize, [bool], msg="'normalize' must be a boolean; got {}".format(normalize))
        n_features = shape[0]
        if pad_with is not None and n_amplitudes > n_features:
            features = np.pad(features, (0, n_amplitudes - n_features), mode='constant', constant_values=pad_with)
        if isinstance(features[0], Variable):
            feature_values = [s.val for s in features]
            norm = np.sum(np.abs(feature_values) ** 2)
        else:
            norm = np.sum(np.abs(features) ** 2)
        if not np.isclose(norm, 1.0, atol=TOLERANCE):
            if normalize or pad_with:
                features = features / np.sqrt(norm)
            else:
                raise ValueError("Features must be a vector of length 1.0; got length {}.Use 'normalize=True' to automatically normalize.".format(norm))
        features = np.array(features)
    return features

def handle_game_request(self, request: Node) -> Optional[Node]:
    method = request.attribute('method')
    if method == 'get':
        root = Node.void('game')
        root.set_attribute('game_phase', request.attribute('game_phase'))
        root.set_attribute('psp_phase', request.attribute('psp_phase'))
        return root
    if method == 'active':
        self.update_machine_name(request.attribute('shop_name'))
        return Node.void('game')
    if method == 'taxphase':
        return Node.void('game')
    return None

def GetEntry(self, number, entry=None):
    if number in self.protofiles:
        fh = self.protofiles[number]
    else:
        fh = self.zipfile.open('plaso_proto.%06d' % number, 'r')
        self.protofiles[number] = fh
    if entry:
        fh.seek(entry * 4)
    unpacked = fh.read(4)
    if len(unpacked) != 4:
        return None
    size = struct.unpack('<I', unpacked)[0]
    if size > 1024 * 1024 * 40:
        raise errors.WrongProtobufEntry('Protobuf size too large: %d', size)
    proto_serialized = fh.read(size)
    proto = plaso_storage_pb2.EventObject()
    proto.ParseFromString(proto_serialized)
    return proto

