def handle_event(self, event, filetype):
    (start_time, compressed_blob) = (time.time(), None)
    site = event.get('site', self.find_site_for_file(event['full_path']))
    original_file_size = os.stat(event['full_path']).st_size
    self.log.debug('Starting to compress: %r, filetype: %r, original_size: %r', event['full_path'], filetype, original_file_size)
    if event.get('compress_to_memory', False):
        (compressed_blob, compression_algorithm, compressed_file_size) = self.compress_filepath_to_memory(event['full_path'])
    else:
        (compressed_filepath, compression_algorithm, compressed_file_size) = self.compress_filepath(event['full_path'], self.get_compressed_file_path(site, filetype, os.path.dirname(event['full_path'])))
    self.log.debug('Compressed %d byte file: %r to %d bytes, took: %.3fs', original_file_size, event['full_path'], compressed_file_size, time.time() - start_time)
    if event.get('delete_file_after_compression', True):
        try:
            self.delete_file_and_ignore_error(event['full_path'])
        except Exception as e:
            self.log.error(f"Error deleting file {event['full_path']}: {e}")
    metadata = {'compression_algorithm': compression_algorithm, 'original_file_size': original_file_size}
    if 'start_wal_segment' in event:
        metadata['start_wal_segment'] = event['start_wal_segment']
    self.set_state_defaults_for_site(site)
    self.state[site][filetype]['original_data'] += original_file_size
    self.state[site][filetype]['compressed_data'] += compressed_file_size
    self.state[site][filetype]['count'] += 1
    if self.config['backup_clusters'][site].get('object_storage'):
        transfer_object = {'metadata': metadata, 'site': site, 'file_size': compressed_file_size, 'filetype': filetype}
        if event.get('compress_to_memory', False):
            transfer_object['blob'] = compressed_blob
            transfer_object['local_path'] = event['full_path']
            transfer_object['callback_queue'] = event.get('callback_queue')
        else:
            transfer_object['local_path'] = compressed_filepath
        self.transfer_queue.put(transfer_object)
    elif 'callback_queue' in event and event['callback_queue']:
        event['callback_queue'].put({'success': True})
    return True

def show_widget(self, request, video_url, is_remote, base_state=None):
    (video, create) = models.Video.get_or_create_for_url(video_url)
    video.widget_views_count += 1
    video.save()
    self._maybe_add_video_session(request)
    return_value = {'video_id': video.video_id, 'writelock_expiration': models.WRITELOCK_EXPIRATION, 'embed_version': settings.EMBED_JS_VERSION, 'languages': LANGUAGES, 'metadata_languages': settings.METADATA_LANGUAGES}
    if request.user.is_authenticated():
        return_value['username'] = request.user.username
    if video.video_type == models.VIDEO_TYPE_BLIPTV:
        video_urls = [video.bliptv_flv_url]
    else:
        video_urls = [video_url]
    return_value['video_urls'] = video_urls
    return_value['drop_down_contents'] = self._drop_down_contents(request.user, video)
    if base_state is not None:
        subtitles = self._autoplay_subtitles(request.user, video, base_state.get('language', None), base_state.get('revision', None))
        return_value['subtitles'] = subtitles
    elif is_remote:
        autoplay_language = self._find_remote_autoplay_language(request)
        if autoplay_language is not None:
            subtitles = self._autoplay_subtitles(request.user, video, autoplay_language, None)
            return_value['subtitles'] = subtitles
    return return_value

def _findOperationHost(self, target, operation_host):
    if not operation_host or operation_host in ['localhost', 'ORCHESTRATOR']:
        return None
    if operation_host == 'SELF':
        return target
    if operation_host == 'HOST':
        return target.parent
    host = target.root.findResource(operation_host)
    if host:
        return host
    raise UnfurlTaskError(self, 'can not find operation_host: %s' % operation_host)

