        self.assertFalse(form.is_valid(), domain)

def verify(self, verify_nested_ops: bool=True) -> None:
    for operand in self.operands:
        if isinstance(operand, ErasedSSAValue):
            raise Exception('Erased SSA value is used by the operation')
    parent_block = self.parent
    parent_region = None if parent_block is None else parent_block.parent
    if self.successors:
        if parent_block is None or parent_region is None:
            raise VerifyException(f'Operation {self.name} with block successors does not belong to a block or a region')
        if parent_block.last_op is not self:
            raise VerifyException(f'Operation {self.name} with block successors must terminate its parent block')
        for succ in self.successors:
            if succ.parent != parent_block.parent:
                raise VerifyException(f'Operation {self.name} is branching to a block of a different region')
    if parent_block is not None and parent_region is not None:
        if len(parent_region.blocks) > 1:
            if parent_block.last_op is self and (not self.has_trait(IsTerminator)):
                raise VerifyException(f'Operation {self.name} terminates block in multi-block region but is not a terminator')
    if verify_nested_ops:
        for region in self.regions:
            region.verify()
    try:
        self.verify_()
    except VerifyException as err:
        self.emit_error('Operation does not verify: ' + str(err))

def _create(cls, target_class, *args, **kwargs):
    if args:
        assert False, "Positional args aren't supported, use keyword args."
    context = {'user': kwargs.get('user', helpers.call_action('get_site_user')['name'])}
    group_dict = helpers.call_action('organization_create', context=context, **kwargs)
    return group_dict

def _undefine_domain(self, instance):
    try:
        guest = self._host.get_guest(instance)
        virt_dom = guest
    except exception.InstanceNotFound:
        virt_dom = None
    if virt_dom:
        try:
            try:
                virt_dom.undefineFlags(libvirt.VIR_DOMAIN_UNDEFINE_MANAGED_SAVE)
            except libvirt.libvirtError:
                LOG.debug('Error from libvirt during undefineFlags. Retrying with undefine', instance=instance)
                virt_dom.undefine()
            except AttributeError:
                try:
                    if virt_dom.hasManagedSaveImage(0):
                        virt_dom.managedSaveRemove(0)
                except AttributeError:
                    pass
                virt_dom.undefine()
        except libvirt.libvirtError as e:
            with excutils.save_and_reraise_exception():
                errcode = e.get_error_code()
                LOG.error(_LE('Error from libvirt during undefine. Code=%(errcode)s Error=%(e)s'), {'errcode': errcode, 'e': e}, instance=instance)

def get_block_type(self, block_index):
    mp = self.get_type_map()
    bi = BlockIndex.parse(str(block_index))
    try:
        return mp[bi.i][bi.j]
    except IndexError:
        raise BlockTypeNotSupported(f'type x{bi.i}~{bi.j} is not supported')

def partition(self, substr):
    if not isinstance(substr, str):
        raise TypeError
    if len(substr) == 0:
        raise ValueError
    mypoints = self._codepoints
    subpoints = [ord(ch) for ch in substr]
    if not subpoints:
        raise ValueError
    substrlen = len(subpoints)
    for start in range(1 + len(mypoints) - substrlen):
        if mypoints[start:start + substrlen] != subpoints:
            continue
        prefix_points = mypoints[:start]
        suffix_points = mypoints[start + substrlen:]
        with NoTracing():
            return (LazyIntSymbolicStr(prefix_points), substr, LazyIntSymbolicStr(suffix_points))
    return (self, '', '')

async def _create_pipeline(auth_info: mlrun.api.schemas.AuthInfo, request: Request, namespace: str, experiment_name: str, run_name: str, project: typing.Optional[str]=None):
    if project:
        await mlrun.api.utils.auth.verifier.AuthVerifier().query_project_resource_permissions(mlrun.api.schemas.AuthorizationResourceTypes.pipeline, project, '', mlrun.api.schemas.AuthorizationAction.create, auth_info)
    run_name = run_name or experiment_name + ' ' + datetime.now().strftime('%Y-%m-%d %H-%M-%S')
    data = await request.body()
    if not data:
        log_and_raise(HTTPStatus.BAD_REQUEST.value, reason='Request body is empty')
    content_type = request.headers.get('content-type', '')
    project = _try_resolve_project_from_body(content_type, data)
    if not project:
        raise mlrun.errors.MLRunInvalidArgumentError('Pipelines can not be created without a project - you are probably running with old client - try upgrade to the server version')
    else:
        await mlrun.api.utils.auth.verifier.AuthVerifier().query_project_resource_permissions(mlrun.api.schemas.AuthorizationResourceTypes.pipeline, project, '', mlrun.api.schemas.AuthorizationAction.create, auth_info)
    arguments = {}
    run = await run_in_threadpool(mlrun.api.crud.Pipelines().create_pipeline, experiment_name, run_name, content_type, data, arguments, namespace)
    return {'id': run.id, 'name': run.name}

