def staging_file_delete(request, staging_file_id):
    staging_file = StagingFile.get(staging_file_id)
    next = request.POST.get('next', request.GET.get('next', request.META.get('HTTP_REFERER', None)))
    previous = request.POST.get('previous', request.GET.get('previous', request.META.get('HTTP_REFERER', None)))
    if request.method == 'POST':
        if not user_has_permission(request.user):
            messages.error(request, _(u'You do not have permission to delete this file.'))
            return HttpResponseRedirect(next)
        try:
            staging_file.delete()
            messages.success(request, _(u'Staging file deleted successfully.'))
        except Exception as e:
            messages.error(request, e)
        return HttpResponseRedirect(next)
    return render_to_response('generic_confirm.html', {'delete_view': True, 'object': staging_file, 'next': next, 'previous': previous}, context_instance=RequestContext(request))

def _apply_to_impl(self, instance, **kwds):
    config = self.CONFIG(kwds.pop('options', {}))
    if 'default_bigM' in kwds:
        logger.warn("DEPRECATED: the 'default_bigM=' argument has been "
                    "replaced by 'bigM='")
        config.bigM = kwds.pop('default_bigM')
    config.set_value(kwds)
    bigM = config.bigM
    self.assume_fixed_vars_permanent = config.assume_fixed_vars_permanent
    targets = config.targets
    if targets is None:
        targets = (instance, )
        _HACK_transform_whole_instance = True
    else:
        _HACK_transform_whole_instance = False
    knownBlocks = {}
    for t in targets:
        if not is_child_of(parent=instance, child=t,
                           knownBlocks=knownBlocks):
            raise GDP_Error(
                "Target '%s' is not a component on instance '%s'!"
                % (t.name, instance.name))
        elif t.ctype is Disjunction:
            if t.is_indexed():
                self._transform_disjunction(t, bigM)
            else:
                self._transform_disjunctionData( t, bigM, t.index())
        elif t.ctype in (Block, Disjunct):
            if t.is_indexed():
                self._transform_block(t, bigM)
            else:
                self._transform_blockData(t, bigM)
        else:
            raise GDP_Error(
                "Target '%s' was not a Block, Disjunct, or Disjunction. "
                "It was of type %s and can't be transformed."
                % (t.name, type(t)))
    if bigM is not None:
        unused_args = ComponentSet(bigM.keys()) -
                      ComponentSet(self.used_args.keys())
        if len(unused_args) > 0:
            warning_msg = ("Unused arguments in the bigM map! "
                           "These arguments were not used by the "
                           "transformation:\n")
            for component in unused_args:
                if hasattr(component, 'name'):
                    warning_msg += "\t%s\n" % component.name
                else:
                    warning_msg += "\t%s\n" % component
            logger.warn(warning_msg)

def parse_shader(sres, c, con, defs, lines, parse_attributes):
    skip_till_endif = 0
    skip_else = False
    vertex_structure_parsed = False
    vertex_structure_parsing = False
    stack = []
    if parse_attributes == False:
        vertex_structure_parsed = True
    for line in lines:
        line = line.lstrip()
        if line.startswith('#ifdef') or line.startswith('#ifndef'):
            s = line.split(' ')[1]
            found = find_def(defs, s)
            if line.startswith('#ifndef'):
                found = not found
            if found == False:
                stack.append(0)
            else:
                stack.append(1)
            continue
        if line.startswith('#else'):
            stack[-1] = 1 - stack[-1]
            continue
        if line.startswith('#endif'):
            stack.pop()
            continue
        if len(stack) > 0 and stack[-1] == 0:
            continue
        if vertex_structure_parsed == False and line.startswith('in '):
            vertex_structure_parsing = True
            vd = {}
            s = line.split(' ')
            vd['size'] = int(s[1][-1:])
            vd['name'] = s[2][:-1]
            sres['vertex_structure'].append(vd)
        if vertex_structure_parsing == True and len(line) > 0 and (line.startswith('//') == False) and (line.startswith('in ') == False):
            vertex_structure_parsed = True
        if line.startswith('uniform ') or line.startswith('//!uniform'):
            s = line.split(' ')
            if s[1].startswith('layout'):
                ctype = s[2]
                cid = s[3][:-1]
            else:
                ctype = s[1]
                cid = s[2][:-1]
            found = False
            if ctype == 'sampler2D' or ctype == 'sampler2DShadow' or ctype == 'sampler3D' or (ctype == 'image2D') or (ctype == 'image3D'):
                for tu in con['texture_units']:
                    if tu['name'] == cid:
                        found = True
                        break
                if found == False:
                    tu = {}
                    tu['name'] = cid
                    if ctype == 'image2D' or ctype == 'image3D':
                        tu['is_image'] = True
                    for l in c['links']:
                        if l['name'] == cid:
                            valid_link = True
                            if 'ifdef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifdef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if not def_found:
                                    valid_link = False
                            if 'ifndef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifndef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if def_found:
                                    valid_link = False
                            if valid_link:
                                tu['link'] = l['link']
                            break
                    con['texture_units'].append(tu)
            else:
                if cid.find('[') != -1:
                    cid = cid.split('[')[0]
                    ctype = 'floats'
                for const in con['constants']:
                    if const['name'] == cid:
                        found = True
                        break
                if found == False:
                    const = {}
                    const['type'] = ctype
                    const['name'] = cid
                    for l in c['links']:
                        if l['name'] == cid:
                            valid_link = True
                            if 'ifdef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifdef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if not def_found:
                                    valid_link = False
                            if 'ifndef' in l:
                                def_found = False
                                for d in defs:
                                    for link_def in l['ifndef']:
                                        if d == link_def:
                                            def_found = True
                                            break
                                    if def_found:
                                        break
                                if def_found:
                                    valid_link = False
                            if valid_link:
                                const['link'] = l['link']
                            break
                    con['constants'].append(const)

def add_entry_from_tx(self, raw_tx):
    coindb = self.model.get_coin_manager()
    (spent_coins, received_coins) = coindb.get_coins_for_transaction(raw_tx)
    if not spent_coins and (not received_coins):
        return
    if not spent_coins:
        self.add_receive_entry(raw_tx.get_hex_txhash(), received_coins)
    else:
        self.classify_and_send_transaction(raw_tx)

    def classify_and_send_transaction(self, raw_tx):
        pass

def get_current_user():
    if settings.UNIT_TEST_MODE:
        user_via_env = None
        if os.environ['USER_EMAIL'] != '':
            user_via_env = User(email=os.environ['USER_EMAIL'])
        return user_via_env
    (user_info, signature) = session.get('signed_user_info', (None, None))
    if user_info:
        try:
            xsrf.validate_token(signature, str(user_info), timeout=xsrf.REFRESH_TOKEN_TIMEOUT_SEC)
            user_via_signed_user_info = User(email=user_info['email'])
            return user_via_signed_user_info
        except xsrf.TokenIncorrect:
            session.clear()
            pass
    return None

def get_kube_client(cluster=None, in_cluster=conf.getboolean('kubernetes', 'in_cluster')):
    if cluster:
        return _load_kube_config(in_cluster, cluster)
    return _load_kube_config(in_cluster)

def _load_kube_config(in_cluster, cluster=None):
    from kubernetes import config, client
    if in_cluster:
        config.load_incluster_config()
        return client.CoreV1Api()
    else:
        if cluster:
            pass
        config.load_kube_config()
        return client.CoreV1Api()

