def __init__(self, opt, shared=None):
    self.opt = copy.deepcopy(opt)
    print('[DialogTeacher initializing.]')
    if not hasattr(self, 'setup_data'):
        raise RuntimeError('Must implement setup_data or subclass a class' + ' which implements it (e.g. FbDialogTeacher)' + ' in order to use this class.')
    self.datatype = opt['datatype']
    self.startTime = time.time()
    if not hasattr(self, 'id'):
        self.id = opt.get('task', 'teacher')
    if shared and shared.get('data'):
        self.data = shared['data']
    elif opt.get('numthreads', 1) == 1:
        self.data = TextData(self.setup_data(opt['datafile']), cands=self.label_candidates(), random=self.datatype == 'train')
    else:
        self.data = HogwildTextData(self.setup_data(opt['datafile']), cands=self.label_candidates(), random=self.datatype == 'train')
    if shared and shared.get('metrics'):
        self.metrics = shared['metrics']
    else:
        self.metrics = Metrics(opt)
    self.reset()

def _detect_local_metal():
    dev = tvm.metal()
    if not dev.exist:
        return None
    return tvm.target.Target({'kind': 'metal', 'max_shared_memory_per_block': 32768, 'max_threads_per_block': dev.max_threads_per_block, 'thread_warp_size': 32}, host=tvm.target.Target({'kind': 'llvm'}))

def normalize_layers_pearson_residuals(adata: AnnData, layers: list=[], select_genes_layer='X', select_genes_key='use_for_pca', copy=False, **normalize_pearson_residual_args) -> None:
    if len(layers) == 0:
        main_warning('layers arg has zero length. return and do nothing in normalize_layers_pearson_residuals.')
    if not select_genes_layer in layers:
        main_warning('select_genes_layer: %s not in layers, using layer: %s instead to select genes instead.' % (select_genes_layer, layers[0]))
        select_genes_layer = layers[0]
    for layer in layers:
        temp_select_genes_key = None
        if select_genes_layer == layer:
            temp_select_genes_key = select_genes_key
        temp_adata = _normalize_single_layer_pearson_residuals(adata, layer=layer, var_select_genes_key=temp_select_genes_key, copy=copy, **normalize_pearson_residual_args)
        if temp_adata is None:
            temp_adata = adata
        if layer == DKM.X_LAYER:
            main_info('skipping set X as layer in adata.layers', indent_level=2)
            continue
        new_X_key = DKM.gen_layer_X_key(layer)
        main_info_insert_adata_layer(new_X_key, indent_level=2)
        adata.layers[new_X_key] = DKM.select_layer_data(temp_adata, layer)

def browser(request, percy, live_server):
    window_size = request.config.getoption('window_size')
    (window_width, window_height) = list(map(int, window_size.split('x', 1)))
    driver_type = request.config.getoption('selenium_driver')
    if driver_type == 'chrome':
        options = webdriver.ChromeOptions()
        options.add_argument('headless')
        options.add_argument('disable-gpu')
        options.add_argument('window-size={}'.format(window_size))
        chrome_path = request.config.getoption('chrome_path')
        if chrome_path:
            options.binary_location = chrome_path
        chromedriver_path = request.config.getoption('chromedriver_path')
        if chromedriver_path:
            driver = webdriver.Chrome(executable_path=chromedriver_path, chrome_options=options)
        else:
            driver = webdriver.Chrome(chrome_options=options)
    elif driver_type == 'firefox':
        driver = webdriver.Firefox()
    elif driver_type == 'phantomjs':
        phantomjs_path = request.config.getoption('phantomjs_path')
        if not phantomjs_path:
            phantomjs_path = os.path.join('node_modules', 'phantomjs-prebuilt', 'bin', 'phantomjs')
        driver = webdriver.PhantomJS(executable_path=phantomjs_path)
    else:
        raise pytest.UsageError('--driver must be specified')
    driver.set_window_size(window_width, window_height)

    def fin():
        try:
            driver.close()
        except Exception:
            pass
        driver.quit()
    request.node._driver = driver
    request.addfinalizer(fin)
    browser = Browser(driver, live_server, percy)
    if hasattr(request, 'cls'):
        request.cls.browser = browser
    request.node.browser = browser
    percy.loader.webdriver = driver
    return driver

def validate(self, exclusion):
    geo_group = exclusion.modified_measure.geographical_area
    excluded = exclusion.excluded_geographical_area
    if not geo_group.members.filter(member__sid=excluded.sid, valid_between__contains=exclusion.modified_measure.effective_valid_between).exists():
        raise self.violation(exclusion)

def _addExtraCfg(self, cmd, devices=tuple(), use_lvmpolld=True):
    newcmd = [constants.EXT_LVM, cmd[0]]
    if devices:
