def geometry_to_bitmap(geometry, radius: int=0, crop_image_shape: tuple=None) -> list:
    thickness = radius + 1
    if isinstance(geometry, Point):
        bbox = geometry.to_bbox()
    else:
        bbox = geometry.to_bbox()
    extended_bbox = Rectangle(top=bbox.top - radius, left=bbox.left - radius, bottom=bbox.bottom + radius, right=bbox.right + radius)
    bitmap_data = np.zeros(shape=(extended_bbox.height, extended_bbox.width), dtype=np.uint8)
    geometry = geometry.translate(-extended_bbox.top, -extended_bbox.left)
    geometry.draw(bitmap_data, 1, thickness=thickness)
    origin = Point(extended_bbox.top, extended_bbox.left)
    bitmap_geometry = Bitmap(origin, bitmap_data.astype(np.bool))
    if crop_image_shape is not None:
        crop_rect = Rectangle.from_size(*crop_image_shape)
        return bitmap_geometry.crop(crop_rect)
    return [bitmap_geometry]

def forward_unbatched(self, x, mask=None, *, weights, state, update_state, rng):
    del update_state
    if self.share_qk:
        (w_q, w_v, w_o) = weights
    else:
        (w_q, w_k, w_v, w_o) = weights
    q = np.matmul(x, w_q)
    k = None
    if not self.share_qk:
        k = np.matmul(x, w_k)
    v = np.matmul(x, w_v)
    mask_fn = functools.partial(mask_self_attention, causal=self.causal, exclude_self=self.share_qk, masked=self.masked)
    q_info = kv_info = jax.lax.tie_in(x, np.arange(q.shape[-2]))
    assert (mask is not None) == self.masked
    if self.masked:
        ones_like_mask = jax.lax.tie_in(x, np.ones_like(mask, dtype=np.int32))
        kv_info = kv_info * np.where(mask, ones_like_mask, -ones_like_mask)
    (o, _) = attend(q, k, v, q_chunk_len=self.chunk_len, kv_chunk_len=self.chunk_len, n_chunks_before=self.n_chunks_before, n_chunks_after=self.n_chunks_after, mask_fn=mask_fn, q_info=q_info, kv_info=kv_info, dropout=self.attention_dropout, rng=rng)
    out = np.matmul(o, w_o)
    return (out, state)

def _build_game_header(self, pgn_game: chess.pgn.Game):
    pgn_game.headers['Event'] = 'PicoChess game'
    pgn_game.headers['Site'] = 'picochess.org'
    pgn_game.headers['Date'] = datetime.datetime.today().strftime('%Y.%m.%d')
    pgn_game.headers['Round'] = '?'
    pgn_game.headers['White'] = '?'
    pgn_game.headers['Black'] = '?'
    user_name = 'User'
    engine_name = 'Picochess'
    user_elo = '-'
    comp_elo = 2900
    if 'system_info' in self.shared:
        if 'user_name' in self.shared['system_info']:
            user_name = self.shared['system_info']['user_name']
        if 'engine_name' in self.shared['system_info']:
            engine_name = self.shared['system_info']['engine_name']
        if 'user_elo' in self.shared['system_info']:
            user_elo = self.shared['system_info']['user_elo']
    engine_elo = {'stockfish': 3360, 'texel': 3050, 'rodent': 2920, 'zurichess': 2790, 'floyd': 2620, 'cinnamon': 2060}
    for (name, elo) in engine_elo.items():
        if engine_name.lower().startswith(name):
            comp_elo = elo
            break
    if 'game_info' in self.shared:
        if 'level_text' in self.shared['game_info']:
            engine_level = ' ({0})'.format(self.shared['game_info']['level_text'].m)
        else:
            engine_level = ''
        if 'level_name' in self.shared['game_info']:
            level_name = self.shared['game_info']['level_name']
            if level_name.startswith('Elo@'):
                comp_elo = int(level_name[4:])
                engine_level = ''
        if 'play_mode' in self.shared['game_info']:
            if self.shared['game_info']['play_mode'] == PlayMode.USER_WHITE:
                pgn_game.headers['White'] = user_name
                pgn_game.headers['Black'] = engine_name + engine_level
                pgn_game.headers['WhiteElo'] = user_elo
                pgn_game.headers['BlackElo'] = comp_elo
            else:
                pgn_game.headers['White'] = engine_name + engine_level
                pgn_game.headers['Black'] = user_name
                pgn_game.headers['WhiteElo'] = comp_elo
                pgn_game.headers['BlackElo'] = user_elo
    if 'ip_info' in self.shared:
        if 'location' in self.shared['ip_info']:
            pgn_game.headers['Site'] = self.shared['ip_info']['location']

def windowize_function(expr, frame):
    assert isinstance(expr, ir.Expr), type(expr)
    assert isinstance(frame, ops.WindowFrame)

    def _windowize(op, frame):
        if isinstance(op, ops.WindowFunction):
            walked_child = _walk(op.func, frame)
            walked = walked_child.to_expr().over(op.frame).op()
        elif isinstance(op, ops.Value):
            walked = _walk(op, frame)
        else:
            walked = op
        if isinstance(walked, (ops.Analytic, ops.Reduction)):
            return op.to_expr().over(frame).op()
        elif isinstance(walked, ops.WindowFunction):
            if frame is not None:
                frame = walked.frame.copy(group_by=frame.group_by + walked.frame.group_by, order_by=frame.order_by + walked.frame.order_by)
                return walked.to_expr().over(frame).op()
            else:
                return walked
        else:
            return walked

    def _walk(op, frame):
        windowed_args = []
        for arg in op.args:
            if isinstance(arg, ops.Value):
                arg = _windowize(arg, frame)
            elif isinstance(arg, tuple):
                arg = tuple((_windowize(x, frame) for x in arg))
            windowed_args.append(arg)
        return type(op)(*windowed_args)
    return _windowize(expr.op(), frame).to_expr()

def identify_sender(peer, email_address, msg):
    addr = M.EmailAddress.query.get(_id=M.EmailAddress.canonical(email_address))
    if addr and addr.claimed_by_user_id:
        return addr.claimed_by_user()
    return M.User.anonymous()

def _getQemuBinariesFromServerCallback(self, result, error=False):
    if self._qemu_binaries_progress_dialog.wasCanceled():
        return
    self._qemu_binaries_progress_dialog.accept()
    if error:
        QtGui.QMessageBox.critical(self, 'Qemu binaries', 'Error: '.format(result['message']))
    else:
        self.uiQemuListComboBox.clear()
        for qemu in result['qemus']:
            if qemu['version']:
                self.uiQemuListComboBox.addItem('{path} (v{version})'.format(path=qemu['path'], version=qemu['version']), qemu['path'])
            else:
                self.uiQemuListComboBox.addItem('{path}'.format(path=qemu['path']), qemu['path'])
        if sys.platform.startswith('win'):
            index = self.uiQemuListComboBox.findData('x86_64w', QtCore.Qt.MatchContains)
        else:
            index = self.uiQemuListComboBox.findData('x86_64 ', QtCore.Qt.MatchContains)
        if index != -1:
            self.uiQemuListComboBox.setCurrentIndex(index)

def setup(self, attempt_remount=False):
    if config.PLATFORM == 'linux' and attempt_remount:
        cmd = 'echo "Please enter your sudo password:"; sudo ' + config.SCRIPT_DIR + '/ios_mount_linux.sh mount'
        if self.catch_err(self.run_command(cmd)) == -1:
            return (False, "Couldn't detect device. See {}/ios_mount_linux.sh.".format(config.SCRIPT_DIR))
    cmd = 'idevicepair pair'
    pairmsg = self.run_command(cmd).stdout.read().decode('utf-8')
    if 'No device found, is it plugged in?' in pairmsg:
        return (False, pairmsg)
    elif 'Please enter the passcode on the device and retry.' in pairmsg:
        return (False, 'Please unlock your device and follow the trust dialog (you will need to enter your passcode). Then try to scan again.')
    elif 'SUCCESS: Paired with device' in pairmsg:
        return (True, 'Device successfully paired. Setup complete.')
    elif 'said that the user denied the trust dialog.' in pairmsg:
        return (False, 'The trust dialog was denied. Please unplug the device, reconnect it, and scan again -- accept the trust dialog to proceed.')
    return (True, 'Follow trust dialog on iOS device to continue.')

def normalize_exception(self, space):
    w_type = self.w_type
    w_value = self.w_value
    if space.full_exceptions:
        while space.is_true(space.isinstance(w_type, space.w_tuple)):
            w_type = space.getitem(w_type, space.wrap(0))
    if space.is_true(space.abstract_isclass(w_type)):
        if space.is_w(w_value, space.w_None):
            w_value = space.call_function(w_type)
            w_type = space.abstract_getclass(w_value)
        else:
            w_valuetype = space.abstract_getclass(w_value)
            if space.is_true(space.abstract_issubclass(w_valuetype, w_type)):
                w_type = w_valuetype
            else:
                if space.full_exceptions and space.is_true(space.isinstance(w_value, space.w_tuple)):
                    w_value = space.call(w_type, w_value)
                else:
                    w_value = space.call_function(w_type, w_value)
                w_type = space.abstract_getclass(w_value)
    elif space.full_exceptions and space.is_w(space.type(w_type), space.w_str):
        pass
    else:
        if not space.is_w(w_value, space.w_None):
            raise OperationError(space.w_TypeError, space.wrap('instance exception may not have a separate value'))
        w_value = w_type
        w_type = space.abstract_getclass(w_value)
        if space.full_exceptions:
            if space.findattr(w_value, space.wrap('__dict__')) is None and space.findattr(w_value, space.wrap('__slots__')) is None:
                msg = "raising built-in objects can be ambiguous, use 'raise type, value' instead"
                raise OperationError(space.w_TypeError, space.wrap(msg))
    self.w_type = w_type
    self.w_value = w_value

def apply_filters(self, table, text_filter, permission_filter=None):
    row_count = table.rowCount()
    permitted_items = [row_num for row_num in range(row_count) if permission_filter is None or permission_filter == 'all' or permission_filter == table.item(row_num, 1).text()]
    for row_num in range(row_count):
        if row_num in permitted_items and text_filter in table.item(row_num, 0).text():
            table.showRow(row_num)
        else:
            table.hideRow(row_num)

def _build_async_indicators(indicator_doc_ids):

    def handle_exception(exception, config_id, doc, adapter):
        metric = None
        if isinstance(exception, (ProtocolError, ReadTimeout)):
            metric = 'commcare.async_indicator.riak_error'
        elif isinstance(exception, (ESError, ConnectionTimeout)):
            metric = 'commcare.async_indicator.es_error'
        elif isinstance(exception, (DatabaseError, InternalError)):
            metric = 'commcare.async_indicator.psql_error'
        elif adapter:
            adapter.handle_exception(doc, exception)
        if metric:
            datadog_counter(metric, 1, tags={'config_id': config_id, 'doc_id': doc['_id']})

    def doc_ids_from_rows(rows):
        formatted_rows = [{column.column.database_column_name.decode('utf-8'): column.value for column in row} for row in rows]
        return set((row['doc_id'] for row in formatted_rows))
    configs_to_remove_by_indicator_id = defaultdict(list)

    def _mark_config_to_remove(config_id, indicator_ids):
        for _id in indicator_ids:
            configs_to_remove_by_indicator_id[_id].append(config_id)
    timer = TimingContext()
    lock_keys = [get_async_indicator_modify_lock_key(indicator_id) for indicator_id in indicator_doc_ids]
    with CriticalSection(lock_keys):
        all_indicators = AsyncIndicator.objects.filter(doc_id__in=indicator_doc_ids)
        if not all_indicators:
            return
        doc_store = get_document_store_for_doc_type(all_indicators[0].domain, all_indicators[0].doc_type)
        failed_indicators = set()
        rows_to_save_by_adapter = defaultdict(list)
        indicator_by_doc_id = {i.doc_id: i for i in all_indicators}
        config_ids = set()
        with timer:
            for doc in doc_store.iter_documents(list(indicator_by_doc_id.keys())):
                indicator = indicator_by_doc_id[doc['_id']]
                eval_context = EvaluationContext(doc)
                for config_id in indicator.indicator_config_ids:
                    config_ids.add(config_id)
                    try:
                        config = _get_config_by_id(config_id)
                    except (ResourceNotFound, StaticDataSourceConfigurationNotFoundError):
                        celery_task_logger.info('{} no longer exists, skipping'.format(config_id))
                        _mark_config_to_remove(config_id, [indicator.pk])
                        continue
                    except ESError:
                        celery_task_logger.info('ES errored when trying to retrieve config')
                        failed_indicators.add(indicator)
                        continue
                    adapter = None
                    try:
                        adapter = get_indicator_adapter(config)
                        rows_to_save_by_adapter[adapter].extend(adapter.get_all_values(doc, eval_context))
                        eval_context.reset_iteration()
                    except Exception as e:
                        failed_indicators.add(indicator)
                        handle_exception(e, config_id, doc, adapter)
            for (adapter, rows) in six.iteritems(rows_to_save_by_adapter):
                doc_ids = doc_ids_from_rows(rows)
                indicators = [indicator_by_doc_id[doc_id] for doc_id in doc_ids]
                try:
                    adapter.save_rows(rows)
                except Exception as e:
                    failed_indicators.union(indicators)
                    message = e.message
                    if isinstance(message, bytes):
                        message = message.decode('utf-8')
                    notify_exception(None, 'Exception bulk saving async indicators:{}'.format(message))
                else:
                    _mark_config_to_remove(config_id, [i.pk for i in indicators])
        processed_indicators = set(all_indicators) - failed_indicators
        AsyncIndicator.objects.filter(pk__in=[i.pk for i in processed_indicators]).delete()
        with transaction.atomic():
            for indicator in failed_indicators:
                indicator.update_failure(configs_to_remove_by_indicator_id.get(indicator.pk, []))
                indicator.save()
        datadog_counter('commcare.async_indicator.processed_success', len(processed_indicators))
        datadog_counter('commcare.async_indicator.processed_fail', len(failed_indicators))
        datadog_histogram('commcare.async_indicator.processing_time', timer.duration / len(indicator_doc_ids), tags=['config_ids:{}'.format(config_ids)])

def transform(self, X, y=None):
    X = check_array(X)
    if self.mean_ is not None:
        X = X - self.mean_
    X = safe_sparse_dot(X, self.components_.T)
    return X

def post(self, workload_pair_list, multi_update_flag=False):
    if multi_update_flag:
        return self.put(workload_pair_list)
    request_args_list = []
