def path_to_location(modulestore, location, course_name=None):

    def flatten(xs):
        p = []
        while xs != ():
            p.append(xs[0])
            xs = xs[1]
        return p

    def find_path_to_course(location, course_name=None):
        queue = [(location, ())]
        while len(queue) > 0:
            (loc, path) = queue.pop()
            loc = Location(loc)
            parents = modulestore.get_parent_locations(loc)
            if loc.category == 'course':
                if course_name is None or course_name == loc.name:
                    path = (loc, path)
                    return flatten(path)
            newpath = (loc, path)
            queue.extend(zip(parents, repeat(newpath)))
        return None
    path = find_path_to_course(location, course_name)
    if path is None:
        raise NoPathToItem(location)
    n = len(path)
    course_id = CourseDescriptor.location_to_id(path[0])
    chapter = path[1].name if n > 1 else None
    section = path[2].name if n > 2 else None
    position = None
    if n > 2 and isinstance(path[2], Sequence):
        position = path[2].index(location)
    return (course_id, chapter, section, position)

def new(request):
    if request.method == 'GET':
        form = CommentForm(initial={'start': request.GET['start'], 'end': request.GET['end'], 'chunk': request.GET['chunk']})
        return render_to_response('comments/comment_form.html', {'form': form}, context_instance=RequestContext(request))
    else:
        form = CommentForm(request.POST)
        if form.is_valid():
            comment = form.save(commit=False)
            comment.author = request.user
            comment.save()
            return redirect(comment.chunk)

import networkx as nx

def find_workflow_tasks(wb_dsl, target_task_name):
    G = nx.DiGraph()
    for (task, dependencies) in wb_dsl:
        G.add_node(task)
        for dep in dependencies:
            G.add_edge(dep, task)
    return list(nx.topological_sort(G)) if target_task_name in G else None

def _infer_on_batch(self, utters, dialog_ids=itertools.repeat(None), history=None):

    def _filter(tokens):
        for t in tokens:
            if t == self.eos_token:
                break
            yield t
    (b_enc_ins, b_src_lens) = ([], [])
    if len(utters) == 1 and (not utters[0]):
        utters = [['hi']]
    for (utter, dialog_id) in zip(utters, dialog_ids):
        enc_in = self._encode_context(utter, dialog_id, history)
        b_enc_ins.append(enc_in)
        b_src_lens.append(len(enc_in))
    max_src_len = max(b_src_lens)
    for (i, src_len) in enumerate(b_src_lens):
        src_padd_len = max_src_len - src_len
        b_enc_ins[i].extend([self.src_vocab[self.eos_token]] * src_padd_len)
    pred_idxs = self.network(b_enc_ins, b_src_lens)
    preds = [list(_filter(self.tgt_vocab(utter_idxs))) for utter_idxs in pred_idxs]
    if self.debug:
        log.debug('Dialog prediction = "{}"'.format(preds[-1]))
    return preds

def restraints_residual_sum(self, sites_cart, gradient_array=None):
    if gradient_array is None:
        from scitbx.array_family import flex
        gradient_array = flex.vec3_double(sites_cart.size(), (0.0, 0.0, 0.0))
    target = 0
    if self.ramachandran_proxies is not None:
        target += self.ramachandran_lookup.restraints_residual_sum(sites_cart=sites_cart, gradient_array=gradient_array)
    return target

def run_command(self, command, cwd=None, user_input=None, ignore_errors=False):
    if cwd is None:
        cwd = os.path.join(self.tempdir, 'superlists')
    if command == 'wget -O bootstrap.zip https://codeload.github.com/twbs/bootstrap/zip/v2.3.2':
        shutil.copy(os.path.join(os.path.dirname(__file__), '../downloads/bootstrap-3-rezipped.zip'), os.path.join(cwd, 'bootstrap.zip'))
        return
    process = subprocess.Popen(command, shell=True, cwd=cwd, executable='/bin/bash', stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.PIPE, preexec_fn=os.setsid, universal_newlines=True)
    process._command = command
    self.processes.append(process)
    if 'runserver' in command:
        return
    if user_input and (not user_input.endswith('\n')):
        user_input += '\n'
    (output, _) = process.communicate(user_input)
    if process.returncode and (not ignore_errors):
        if 'test' in command or 'diff' in command or 'migrate' in command:
            return output
        print('process %s return a non-zero code (%s)' % (command, process.returncode))
        print('output:\n', output)
        raise Exception('process %s return a non-zero code (%s)' % (command, process.returncode))
    return output

def parse_werk_v1(content: str, werk_id: int) -> WerkV1ParseResult:
    werk: dict[str, Any] = {'compatible': 'compat', 'edition': 'cre', 'id': werk_id}
    description = []
    in_header = True
    for line in content.split('\n'):
        if in_header and (not line.strip()):
            in_header = False
        elif in_header:
            (key, text) = line.split(':', 1)
            try:
                value: int | str = int(text.strip())
            except ValueError:
                value = text.strip()
            field = key.lower()
            werk[field] = value
        else:
            description.append(line)
    while description and description[-1] == '':
        description.pop()
    return WerkV1ParseResult(werk, description)

