def test_status_services(runner, httpserver, monkeypatch):
    monkeypatch.setattr(config, 'GATEWAY_LISTEN', httpserver.port)
    services = {'dynamodb': 'starting', 's3': 'running'}
    httpserver.expect_request('/_localstack/health', method='GET').respond_with_json({'services': services})
    result = runner.invoke(cli, ['status', 'services'])
    assert result.exit_code == 0
    assert 'dynamodb' in result.output
    assert 's3' in result.output
    for line in result.output.splitlines():
        if 'dynamodb' in line:
            assert 'starting' in line
            assert 'running' not in line
        if 's3' in line:
            assert 'running' in line
            assert 'starting' not in line

def GetBuildPhaseByType(self, type):
    if not 'buildPhases' in self._properties:
        return None
    found_phase = None
    for phase in self._properties['buildPhases']:
        if isinstance(phase, type):
            if found_phase is not None:
                raise ValueError(f'More than one phase of type {type} found.')
            found_phase = phase
    return found_phase

