def random_points(self, n, random='pseudo'):
    x = np.array([x for x in self.geom1.random_points(n, random=random) if not self.geom2.inside(x)])
    x = np.vstack((x, self.geom2.random_points(n, random=random)))
    if n != len(x):
        print('Warning: {} points required, but {} points sampled. Uniform random is not guaranteed.'.format(n, len(x)))
    return x

def deserialize(dataone_exception_xml):
    try:
        dataone_exception_pyxb = dataoneErrors.CreateFromDocument(dataone_exception_xml)
    except (pyxb.PyXBException, xml.sax.SAXParseException):
        msg = StringIO.StringIO()
        msg.write('Deserialization failed with exception:\n')
        msg.write(traceback.format_exc() + '\n')
        msg.write('On input:\n')
        msg.write('<empty response>' if dataone_exception_xml == '' else dataone_exception_xml)
        raise ServerFailure(msg.getvalue())
    trace = getattr(dataone_exception_pyxb, 'traceInformation', None)
    return create_exception_by_name(dataone_exception_pyxb.name, dataone_exception_pyxb.detailCode, dataone_exception_pyxb.description, trace, dataone_exception_pyxb.identifier, dataone_exception_pyxb.nodeId)

