def collect(self, stream, request_body):
    sha512 = self._stream_to_sha512(stream)
    if sha512 not in self.peers:
        raise RuntimeError('negotiate_server_raw: not authorized')
    else:
        result = self.peers[sha512]
        del self.peers[sha512]
        logging.debug('negotiate_server_raw: del sha512 OK: %s', sha512.encode('hex'))
        complete_result = {'client': request_body, 'server': result}
        BACKEND.store_raw(complete_result)
        return result

def _ompize(self, state, **kwargs):
    processed = []
    for node in state.nodes:
        denormals = FindNodeType(Denormals).visit(state.nodes)
        mapper = {i: List(c.Comment('DLE: moved denormals flag')) for i in denormals}
        for tree in retrieve_iteration_tree(node):
            blocked = [i for i in tree if 'blocked' in i.properties]
            parallelizable = [i for i in tree if 'parallel' in i.properties]
            candidates = blocked or parallelizable
            if not candidates:
                continue
            if psutil.cpu_count(logical=False) < self.thresholds['collapse'] or len(candidates) < 2:
                parallelism = omplang['for']
            else:
                parallelism = omplang['collapse']
            root = candidates[0]
            mapper[root] = Block(header=omplang['par-region'], body=denormals + [Element(parallelism), root])
        processed.append(Transformer(mapper).visit(node))
    return {'nodes': processed}

def __finish_with_outcome(self, outcome):
    self.__finish(outcome)
    for bet in Bet.objects.filter(event=self):
        if bet.outcome == self.BOOLEAN_OUTCOME_DICT[outcome]:
            bet.rewarded_total = self.PRIZE_FOR_WINNING * bet.has
            bet.user.total_cash += bet.rewarded_total
            Transaction.objects.create(user=bet.user, event=self, type=Transaction.EVENT_WON_PRIZE, quantity=bet.has, price=self.PRIZE_FOR_WINNING)
        bet.user.save()
        bet.is_new_resolved = True
        bet.save()

