def _predict_label(self, predict_out: Optional[Dict[Text, tf.Tensor]]) -> Tuple[Dict[Text, Any], List[Dict[Text, Any]]]:
    label: Dict[Text, Any] = {'name': None, 'id': None, 'confidence': 0.0}
    label_ranking = []
    if predict_out is None:
        return (label, label_ranking)
    message_sim = predict_out['i_scores']
    message_sim = message_sim.flatten()
    label_ids = message_sim.argsort()[::-1]
    if self.component_config[RANKING_LENGTH] > 0:
        message_sim[::-1].sort()
    message_sim = message_sim.tolist()
    if label_ids.size > 0:
        label = {'id': hash(self.index_label_id_mapping[label_ids[0]]), 'name': self.index_label_id_mapping[label_ids[0]], 'confidence': message_sim[0]}
        if self.component_config[RANKING_LENGTH] and 0 < self.component_config[RANKING_LENGTH] < LABEL_RANKING_LENGTH:
            output_length = self.component_config[RANKING_LENGTH]
        else:
            output_length = LABEL_RANKING_LENGTH
        ranking = list(zip(list(label_ids), message_sim))
        ranking = ranking[:output_length]
        label_ranking = [{'id': hash(self.index_label_id_mapping[label_idx]), 'name': self.index_label_id_mapping[label_idx], 'confidence': score} for (label_idx, score) in ranking]
    return (label, label_ranking)

