def serialize(self, tabLevelString=''):
    CFGSTring = ''
    for entryName in self.__orderedList:
        if entryName in self.__commentDict:
            for commentLine in List.fromChar(self.__commentDict[entryName], '\n'):
                CFGSTring += '%s#%s\n' % (tabLevelString, commentLine)
        if entryName in self.listSections():
            CFGSTring += '%s%s\n%s{\n' % (tabLevelString, entryName, tabLevelString)
            CFGSTring += self.__dataDict[entryName].serialize('%s    ' % tabLevelString)
            CFGSTring += '%s}\n' % tabLevelString
        elif entryName in self.listOptions():
            valueList = List.fromChar(self.__dataDict[entryName])
            if len(valueList) == 0:
                CFGSTring += '%s%s = \n' % (tabLevelString, entryName)
            else:
                CFGSTring += '%s%s = %s\n' % (tabLevelString, entryName, valueList[0])
                for value in valueList[1:]:
                    CFGSTring += '%s%s += %s\n' % (tabLevelString, entryName, value)
        else:
            raise Exception('Oops. There is an entry in the order which is not a section nor an option')
    return CFGSTring

def SearchableText(self):
    data = []
    charset = self.getCharset()
    for field in self.Schema().fields():
        if not field.searchable:
            continue
        method = field.getIndexAccessor(self)
        try:
            datum = method(mimetype='text/plain')
        except TypeError:
            try:
                datum = method()
            except (ConflictError, KeyboardInterrupt):
                raise
            except:
                continue
        if datum:
            type_datum = type(datum)
            vocab = field.Vocabulary(self)
            if type_datum is ListType or type_datum is TupleType:
                vocab_values = map(lambda value, vocab=vocab: vocab.getValue(value, ''), datum)
                datum = list(datum)
                datum.extend(vocab_values)
                datum = ' '.join(datum)
            elif type_datum in STRING_TYPES:
                if type_datum is UnicodeType:
                    datum = datum.encode(charset)
                datum = '%s %s' % (datum, vocab.getValue(datum, ''))
            data.append(str(datum))
    data = ' '.join(data)
    return data

def ceph_health_check():
    namespace = run_cmd("oc get cephcluster -o jsonpath='{.items[0].metadata.namespace}'") or 'openshift-storage'
    run_cmd(f'oc wait --for condition=ready pod -l app=rook-ceph-tools -n {namespace} --timeout=120s')
    tools_pod = run_cmd(f"oc -n {namespace} get pod -l 'app=rook-ceph-tools' -o jsonpath='{{.items[0].metadata.name}}'")
    health = run_cmd(f'oc -n {namespace} exec {tools_pod} ceph health')
    if health.strip() == 'HEALTH_OK':
        log.info('HEALTH_OK, install successful.')
        return 0
    else:
        raise CephHealthException(f'Ceph cluster health is not OK. Health: {health}')

async def handle(self, event_name: str, event: dict, requested: bool=True) -> None:
    _LOGGER.debug('Handle %s: %s', event_name, event)
    event_name = event_name.lower()
    prefixes = ['on', 'off', 'report', 'get']
    for prefix in prefixes:
        if event_name.startswith(prefix):
            event_name = event_name[len(prefix):]
    if event_name.endswith('_V2'.lower()):
        event_name = event_name[:-3]
    if requested:
        if event.get('ret') == 'ok':
            if event_name == 'cleanlogs':
                await self._handle_clean_logs(event)
                return
            event = event.get('resp', event)
        else:
            _LOGGER.warning('Event %s where ret != "ok": %s', event_name, event)
            return
    event_body = event.get('body', {})
    event_header = event.get('header', {})
    if not (event_body and event_header):
        _LOGGER.warning('Invalid Event %s: %s', event_name, event)
        return
    event_data = event_body.get('data', {})
    fw_version = event_header.get('fwVer')
    if fw_version:
        self.fw_version = fw_version
    event_handlers = {'stats': self._handle_stats, 'error': self._handle_error, 'speed': self._handle_fan_speed, 'battery': self._handle_battery, 'chargestate': self._handle_charge_state_requested if requested else self._handle_charge_state, 'lifespan': self._handle_life_span, 'cleaninfo': self._handle_clean_info, 'waterinfo': self._handle_water_info}
    if event_name in event_handlers:
        await event_handlers[event_name](event_data)
    elif 'map' in event_name or event_name == 'pos':
        await self.map.handle(event_name, event_data, requested)
    elif event_name.startswith('set'):
        pass
    elif event_name in ['playsound', 'charge', 'clean']:
        pass
    else:
        _LOGGER.debug('Unknown event: %s with %s', event_name, event)

def load(self):
    with self._protocol.protocol_environment():
        self._session = ApiProtocolSession.build_and_prep(name=self._protocol.data.contents.protocol_file.path.name, contents=self._protocol.get_contents(), hardware=self._hardware.sync, loop=self._loop, broker=self._broker, motion_lock=self._motion_lock, extra_labware=self._protocol.get_contents().get('custom_labware', []))

def _astype(x, dtype):
    if dtype == 'str':
        if isinstance(x, np.ndarray) and x.dtype.kind not in 'US':
            try:
                x = x.astype(dtype).astype('O')
                mask = np.isnan(x)
                x[mask] = None
            except TypeError:
                pass
        return _to_string_column(x)
    if isinstance(x, vaex.column.ColumnString):
        x = x.to_numpy()
    if isinstance(x, vaex.array_types.supported_arrow_array_types):
        x = x.to_pandas().values
    y = x.astype(dtype if dtype not in ['string', 'large_string'] else 'str')
    if vaex.column._is_stringy(y):
        y = vaex.column._to_string_column(y)
    return y

async def _handle_graphql_message(self, source: 'u.User', intent: IntentAPI, message: graphql.Message) -> List[EventID]:
    reply_to_id = message.replied_to_message.message.message_id if message.replied_to_message else None
    event_ids = []
    if message.sticker:
        event_ids.append(await self._handle_facebook_sticker(source, intent, int(message.sticker.id), reply_to_id, message.timestamp))
    if len(message.blob_attachments) > 0:
        attach_ids = await asyncio.gather(*[self._handle_facebook_attachment(message.message_id, source, intent, attachment, reply_to_id, message.timestamp) for attachment in message.blob_attachments])
        event_ids += [attach_id for attach_id in attach_ids if attach_id]
    if message.extensible_attachment:
        event_ids.append(await self._handle_facebook_attachment(message.message_id, source, intent, message.extensible_attachment, reply_to_id, message.timestamp))
    if message.message and message.message.text:
        event_ids.append(await self._handle_facebook_text(intent, message.message, reply_to_id, message.timestamp))
    return event_ids

def get_weakref_obj_or_repr(obj_weakref: object, obj_repr: str) -> object:
    assert isinstance(obj_repr, str), f'{repr(obj_repr)} not string.'
    obj = None
    if obj_weakref is not _WEAKREF_NONE:
        if not isinstance(obj_weakref, weakref_ref):
            raise PrivateException(f'{repr(obj_weakref)} neither weak reference nor "None".')
        obj = obj_weakref()
        if obj is None:
            obj = obj_repr
    return obj

def size(self, path: str) -> int:
    if path.startswith('toilfile:'):
        if self.file_store is None:
            raise RuntimeError('URL requires a file store: ' + path)
        return self.file_store.getGlobalFileSize(FileID.unpack(path[len('toilfile:'):]))
    elif path.startswith('toildir:'):
        (here, subpath, cache_key) = decode_directory(path)
        if subpath is None:
            raise RuntimeError(f'Attempted to check size of directory {path}')
        for part in subpath.split('/'):
            here = cast(DirectoryContents, here[part])
        if not isinstance(here, str):
            raise RuntimeError(f'Did not find a file at {path}')
        if not here.startswith('toilfile:'):
            raise RuntimeError(f'Did not find a filestore file at {path}')
        return self.size(here)
    elif path.startswith('jobstore:'):
        return self.job_store.get_file_size(path[len('jobstore:'):])
    else:
        return super().size(path)

def process_any_identities_checked(self):
    if len(self.identityCheckerThreads) != 0:
        for identityCheckerThread in self.identityCheckerThreads:
            if not identityCheckerThread.isAlive():
                identityCheckerThread.join()
                log('identityCheckerThread has status: %s  identity: %s  status_msg: %s' % (identityCheckerThread.status, identityCheckerThread.identity, identityCheckerThread.status_msg))
                self.identityCheckerThreads.remove(identityCheckerThread)
                status = identityCheckerThread.status
                botIdentity = identityCheckerThread.identity
                if not self.botIdentities.has_key(botIdentity):
                    log("** checked bot identity (%s) we don't have a bot nickname for.  They must have disconnected." % botIdentity)
                    continue
                botNick = self.botIdentities[botIdentity]
                if not self.bots.has_key(botNick):
                    log("** checked bot nick (%s) we don't have a bots entry for.  They must have disconnected." % botNick)
                    continue
                if self.check_bot_peer_is_connected(botNick):
                    continue
                if 1 == status:
                    self.privmsg(botNick, 'havepeer')
                    self.bots[botNick]['connected'] = True
                elif 0 == status:
                    if self.bots[botNick].has_key('ref') and self.bots[botNick].has_key('ref_terminated') and self.bots[botNick].has_key('ref_is_good'):
                        self.privmsg(botNick, 'haveref')
                    elif self.bots[botNick].has_key('ref'):
                        pass
                    elif self.bot2bot_enabled and self.bot2bot_trades_enabled and self.check_bot_peer_is_connected(botNick):
                        self.after(random.randint(15, 90), self.sendGetRefDirect, botNick)
                else:
                    log('** error checking bot identity (%s): %s' % (botIdentity, identityCheckerThread.status_msg))
    self.after(1, self.process_any_identities_checked)

def search_cell(session, data):
    sql_null = None
    radio = RADIO_TYPE.get(data['radio'], -1)
    results = []
    for cell in data['cell']:
        if cell.get('radio'):
            radio = RADIO_TYPE.get(cell['radio'], -1)
        query = session.query(Cell.lat, Cell.lon).filter(Cell.radio == radio).filter(Cell.mcc == cell['mcc']).filter(Cell.mnc == cell['mnc']).filter(Cell.lac == cell['lac']).filter(Cell.cid == cell['cid']).filter(Cell.lat != sql_null).filter(Cell.lon != sql_null)
        result = query.first()
        if result is not None:
            results.append({'lat': quantize(result[0]), 'lon': quantize(result[1]), 'accuracy': 35000})
    return results if results else None

