def matrix_from_rotor(rotor):
    if len(rotor) != 4:
        raise ValueError('Rotor must be an array-like of shape (4,)')
    return np.column_stack((rotor_apply(rotor, unitx), rotor_apply(rotor, unity), rotor_apply(rotor, unitz)))

def _replay(self, actiongroup):
    self.block()
    for (action, start, end, data) in actiongroup:
        iter = self.buffer.get_iter_at_offset(start)
        bound = self.buffer.get_iter_at_offset(end)
        if action == self.ACTION_INSERT:
            self.buffer.place_cursor(iter)
            self.buffer.insert_parsetree_at_cursor(data)
        elif action == self.ACTION_DELETE:
            self.buffer.place_cursor(iter)
            self.buffer.delete(iter, bound)
            tree = self.buffer.get_parsetree((iter, bound), raw=True)
            if tree.tostring() != data.tostring():
                logger.warn('Mismatch in undo stack\n%s\n%s\n', tree.tostring(), data.tostring())
        elif action == self.ACTION_APPLY_TAG:
            self.buffer.apply_tag(data, iter, bound)
            self.buffer.place_cursor(bound)
        elif action == self.ACTION_REMOVE_TAG:
            self.buffer.remove_tag(data, iter, bound)
            self.buffer.place_cursor(bound)
        else:
            assert False, 'BUG: unknown action type'
    if not actiongroup.cursor is None:
        iter = self.buffer.get_iter_at_offset(actiongroup.cursor)
        self.buffer.place_cursor(iter)
    self.unblock()

def _init_keymanager(self, address):
    srp_auth = self.srpauth
    logger.debug('initializing keymanager...')
    try:
        self._keymanager = KeyManager(address, 'https://nicknym.%s:6425' % (self._provider_config.get_domain(),), self._soledad, token=srp_auth.get_token(), session_id=srp_auth.get_session_id(), ca_cert_path=self._provider_config.get_ca_cert_path(), api_uri=self._provider_config.get_api_uri(), api_version=self._provider_config.get_api_version(), uid=srp_auth.get_uid(), gpgbinary=self._get_gpg_bin_path())
    except Exception as exc:
        logger.exception(exc)
        raise
    logger.debug('sending key to server...')
    try:
        self._keymanager.send_key(openpgp.OpenPGPKey)
    except Exception as exc:
        logger.error('Error sending key to server.')
        logger.exception(exc)

def profile_find(self, context, identity, show_deleted=False):
    if uuidutils.is_uuid_like(identity):
        profile = db_api.profile_get(context, identity)
        if not profile:
            profile = db_api.profile_get_by_name(context, identity, show_deleted=show_deleted)
    else:
        profile = db_api.profile_get_by_name(context, identity, show_deleted=show_deleted)
