def _divisions(self):
    if self.operand('user_divisions') is not None:
        return self.operand('user_divisions')
    kwargs = self.key_kwargs
    key = (kwargs['other'], kwargs['partitions'], kwargs['ascending'], 128000000.0, kwargs['upsample'])
    assert key in divisions_lru
    if self.frame.npartitions < len(divisions_lru[key][0]) - 1:
        return self.frame.divisions
    return divisions_lru[key][0]

def import_image(self, src=None, repository=None, tag=None, image=None):
    u = self._url('/images/create')
    params = {'repo': repository, 'tag': tag}
    if src:
        try:
            with open(src) as fic:
                data = fic.read()
            src = '-'
        except IOError:
            data = None
        if isinstance(src, six.string_types):
            params['fromSrc'] = src
            return self._result(self._post(u, data=data, params=params))
        return self._result(self._post(u, data=src, params=params))
    if image:
        params['fromImage'] = image
        return self._result(self._post(u, data=None, params=params))
    raise Exception('Must specify a src or image')

def _visit_Dlist(self, expr, **settings):
    val = self._visit(expr.val, **settings)
    if isinstance(val, (Tuple, PythonTuple, list, tuple)):
        if len(val) > 1:
            msg = 'List of dimension > 1 not yet supported'
            raise PyccelSemanticError(msg)
    shape = self._visit(expr.length, **settings)
    return Dlist(val, shape)

def directive_definition(self, tree: Tree):
    description = None
    name = None
    on = None
    arguments = None
    for child in tree.children:
        if child.type == 'description':
            description = child.value
        elif child.type == 'DIRECTIVE':
            ast_node = child
        elif child.type == 'IDENT':
            name = String(str(child.value), ast_node=child)
        elif child.type == 'arguments':
            arguments = child.value
        elif child.type == 'ON':
            pass
        elif child.type == 'directive_locations':
            on = child.value
        elif child.type == 'discard':
            pass
        else:
            raise UnexpectedASTNode('Unexpected AST node `{}`, type `{}`'.format(child, child.__class__.__name__))
    directive = GraphQLDirective(name=name, on=on, arguments=arguments, description=description)
    self._schema.add_directive(directive)
    return Tree('directive_definition', [directive])

def dumps(self):
    nc = netcdf.netcdf_file(mode='w')
    for (d, l) in self.dimensions.iteritems():
        nc.createDimension(d, l)
    for (vn, v) in self.variables.iteritems():
        nc.createVariable(vn, v.dtype, v.dimensions)
        nc.variables[vn][:] = v.data[:]
        for (k, a) in v.attributes.iteritems():
            setattr(nc.variables[vn], k, a)
    for (k, a) in self.attributes.iteritems():
        setattr(nc, k, a)
    nc.flush()
    return nc

