def __call__(self, *args, **kwargs):
    if len(args) == 1 and isinstance(args[0], pd.DataFrame):
        df = args[0]
    elif len(args) == 0 and kwargs:
        df = pd.DataFrame(kwargs)
    else:
        raise ValueError('Invalid input: expected a DataFrame or keyword arguments.')
    if self.key_columns:
        sub_tables = df.groupby(list(self.key_columns))
    else:
        sub_tables = [(None, df)]
    result = pd.DataFrame(index=df.index)
    for (key, sub_table) in sub_tables:
        if sub_table.empty:
            continue
        funcs = self.interpolations.get(key, {})
        parameters = tuple((sub_table[k] for k in self.parameter_columns if k in sub_table.columns))
        for (value_column, func) in funcs.items():
            out = func(*parameters)
            if out.shape:
                result.loc[sub_table.index, value_column] = out.reshape((out.shape[0],))
            else:
                result.loc[sub_table.index, value_column] = out
    if self.func:
        return self.func(result)
    return result

def post_validation(self, config, key_name):
    theme_config = config[key_name]
    if not theme_config['name'] and 'custom_dir' not in theme_config:
        raise ValidationError("At least one of 'theme.name' or 'theme.custom_dir' must be defined.")
    if 'custom_dir' in theme_config and (not os.path.isabs(theme_config['custom_dir'])):
        config_dir = os.path.dirname(config.config_file_path)
        theme_config['custom_dir'] = os.path.join(config_dir, theme_config['custom_dir'])
    if 'custom_dir' in theme_config and (not os.path.isdir(theme_config['custom_dir'])):
        raise ValidationError("The path set in {name}.custom_dir ('{path}') does not exist.".format(path=theme_config['custom_dir'], name=self.name))
    config[key_name] = theme.Theme(**theme_config)

