def check_and_call_adjust_trade_position(self, trade: Trade):
    if self.strategy.max_entry_position_adjustment > -1:
        count_of_buys = trade.nr_of_successful_entries
        if count_of_buys > self.strategy.max_entry_position_adjustment:
            logger.debug(f'Max adjustment entries for {trade.pair} has been reached.')
            return
    else:
        logger.debug('Max adjustment entries is set to unlimited.')
    current_rate = self.exchange.get_rate(trade.pair, side='entry', is_short=trade.is_short, refresh=True)
    current_profit = trade.calc_profit_ratio(current_rate)
    min_stake_amount = self.exchange.get_min_pair_stake_amount(trade.pair, current_rate, self.strategy.stoploss)
    max_stake_amount = self.exchange.get_max_pair_stake_amount(trade.pair, current_rate)
    stake_available = self.wallets.get_available_stake_amount()
    logger.debug(f'Calling adjust_trade_position for pair {trade.pair}')
    stake_amount = strategy_safe_wrapper(self.strategy.adjust_trade_position, default_retval=None)(trade=trade, current_time=datetime.now(timezone.utc), current_rate=current_rate, current_profit=current_profit, min_stake=min_stake_amount, max_stake=min(max_stake_amount, stake_available))
    if stake_amount is not None and stake_amount > 0.0:
        self.execute_entry(trade.pair, stake_amount, price=current_rate, trade=trade, is_short=trade.is_short)
    if stake_amount is not None and stake_amount < 0.0:
        self.execute_entry(trade.pair, -stake_amount, price=current_rate, trade=trade, is_short=trade.is_short)

def run(self, edit, mode=None, count=1, register=None):
    if len(self.view.sel()) == 0:
        return
    state = self.state
    (text, linewise) = state.registers.get_for_big_p(register, state.mode)
    if not text:
        return status_message('E353: Nothing in register ' + register)
    for sel in self.view.sel():
        if mode == INTERNAL_NORMAL:
            if linewise:
                row = self.view.rowcol(self.view.line(sel.a).a)[0]
                pt = self.view.text_point(row, 0)
                self.view.insert(edit, pt, text)
                pt = next_non_blank(self.view, pt)
                self.view.sel().clear()
                self.view.sel().add(pt)
            else:
                if '\n' in text:
                    pt = sel.a
                else:
                    pt = sel.a + len(text) - 1
                self.view.insert(edit, sel.a, text)
                self.view.sel().clear()
                self.view.sel().add(pt)
            enter_normal_mode(self.view, mode)
        elif mode == VISUAL:
            self.view.replace(edit, sel, text)
            enter_normal_mode(self.view, mode)
            if linewise:

                def selection_first_non_blank(view, s):
                    return Region(next_non_blank(view, view.line(s).a))
                regions_transformer(self.view, selection_first_non_blank)

