def transform_points(dst_homo_src, points_src):
    if not torch.is_tensor(dst_homo_src) or not torch.is_tensor(points_src):
        raise TypeError('Input type is not a torch.Tensor')
    if not dst_homo_src.device == points_src.device:
        raise TypeError('Tensor must be in the same device')
    if not len(dst_homo_src.shape) == 3 or not len(points_src.shape) == 3:
        raise ValueError('Input size must be a three dimensional tensor')
    if not dst_homo_src.shape[0] == points_src.shape[0]:
        raise ValueError('Input batch size must be the same for both tensors')
    if not dst_homo_src.shape[2] == points_src.shape[2] + 1:
        raise ValueError('Input dimensions must differ by one unit')
    points_src_h = convert_points_to_homogeneous(points_src)
    points_dst_h = torch.matmul(dst_homo_src, points_src_h.transpose(1, 2))
    points_dst_h = points_dst_h.permute(0, 2, 1)
    points_dst = convert_points_from_homogeneous(points_dst_h)
    return points_dst

def timer_alert(self, t, timer_name):
    timer = self.get_timer(timer_name)
    if timer.finished_at > t:
        msg = 'Timer <highlight>%s</highlight> has <highlight>%s</highlight> left.' % (timer.name, self.util.time_to_readable(timer.finished_at - t))
        alert_duration = self.get_next_alert(timer.finished_at - t)
        job_id = self.job_scheduler.scheduled_job(self.timer_alert, t + alert_duration, timer.name)
        self.db.exec('UPDATE timer SET job_id = ? WHERE name = ?', [job_id, timer.name])
    else:
        msg = 'Timer <highlight>%s</highlight> has gone off.' % timer.name
        self.remove_timer(timer.name)
        if timer.repeating_every > 0:
            current_t = int(time.time()) - timer.repeating_every
            new_t = t
            while new_t < current_t:
                new_t += timer.repeating_every
            self.add_timer(timer.name, timer.char_id, timer.channel, new_t, timer.repeating_every, timer.repeating_every)
    if timer.channel == PublicChannelService.ORG_CHANNEL_COMMAND or timer.channel == PrivateChannelService.PRIVATE_CHANNEL_COMMAND:
        for (_id, conn) in self.bot.get_conns(lambda x: x.is_main):
            self.bot.send_org_message(msg, conn=conn)
        self.bot.send_private_channel_message(msg, conn=self.bot.get_primary_conn())
    else:
        self.bot.send_private_message(timer.char_id, msg, conn=self.bot.get_primary_conn())

def get_obs_shape(observation_space: spaces.Space) -> Tuple[int, ...]:
    if isinstance(observation_space, spaces.Box):
        return observation_space.shape
    elif isinstance(observation_space, spaces.Discrete):
        return (1,)
    elif isinstance(observation_space, spaces.MultiDiscrete):
        return observation_space.nvec
    elif isinstance(observation_space, spaces.Binary):
        return observation_space.shape
    elif isinstance(observation_space, spaces.MultiBinary):
        return observation_space.shape
    elif isinstance(observation_space, spaces.Tuple):
        return tuple((get_obs_shape(space) for space in observation_space.spaces))
    elif isinstance(observation_space, spaces.Dict):
        return tuple((get_obs_shape(space) for space in observation_space.spaces.values()))
    else:
        raise NotImplementedError()

def unwrap_arguments(xml_response):
    xml_response = xml_response.encode('utf-8')
    try:
        tree = XML.fromstring(xml_response)
    except XML.ParseError:
        filtered = illegal_xml_re.sub('', xml_response.decode('utf-8'))
        tree = XML.fromstring(filtered)
    action_response = tree.find('{http://schemas.xmlsoap.org/soap/envelope/}Body')[0]
    return dict(((i.tag, i.text or '') for i in action_response))

def urllib_fetcher(url):
    (file_like, mime_type, charset) = urlopen(url)
    if mime_type != 'text/css':
        print('Warning: The fetched URL does not return a CSS file.')
        return None
    content = file_like.read()
    file_like.close()
    return (charset, content)

