def transitive_closure(self):
    from copy import copy
    G = self.copy(immutable=False)
    G.name('Transitive closure of ' + self.name())
    for v in G:
        edges_to_add = []
        for e in G.breadth_first_search(v):
            edges_to_add.append((v, e))
        G.add_edges(edges_to_add)
    return G

def _get_strategy_class(self):
    if self._requested_auth_version == 'v3.0':
        return _V3RequestStrategy
    elif self._requested_auth_version is not None:
        return _V2RequestStrategy
    for klass in _REQUEST_STRATEGIES:
        if self._adapter.get_endpoint(version=klass.AUTH_VERSION):
            msg = _LI('Auth Token confirmed use of %s apis')
            self._LOG.info(msg, self._requested_auth_version)
            return klass
    versions = ['v%d.%d' % s.AUTH_VERSION for s in _REQUEST_STRATEGIES]
    self._LOG.error(_LE('No attempted versions [%s] supported by server') % ', '.join(versions))
    msg = _('No compatible apis supported by server')
    raise ServiceError(msg)

def _get_and_check_in_shardings(args, pjit_in_shardings, pjit_mesh, in_tree):
    try:
        arg_in_shardings = tree_map(lambda x: x.sharding, args)
    except AttributeError:
        arg_in_shardings = None
    arg_in_shardings_flat = tuple(tree_flatten(arg_in_shardings)[0])
    if _is_unspecified(pjit_in_shardings):
        if arg_in_shardings is None:
            raise ValueError('Please specify sharding either on the args or on pjit.')
        else:
            _check_array_device_assignment(pjit_mesh, arg_in_shardings_flat)
            return arg_in_shardings
    elif arg_in_shardings is None:
        _check_array_device_assignment(pjit_mesh, pjit_in_shardings)
        return pjit_in_shardings
    else:
        _check_pjit_arg_shardings(hashable_pytree(pjit_in_shardings), arg_in_shardings_flat, in_tree)
        return arg_in_shardings
    assert False, 'Please open a bug report!'

def targets(self):
    if self._auraType == AuraType.PLAYER_AURA:
        return [self.controller]
    elif self._auraType == AuraType.HAND_AURA:
        return self.controller.hand + self.controller.opponent.hand
    if self.source.type == CardType.MINION and self.source.adjacent_buff:
        return self.source.adjacent_minions
    ret = []
    if self.controller.weapon:
        ret.append(self.controller.weapon)
    ret.extend(self.game.player1.field)
    ret.extend(self.game.player2.field)
    return ret

def factory(cls, resp=None, body=None, **kwargs):
    if body is not None or len(kwargs):
        if AccessInfoV3.is_valid(body, **kwargs):
            token = None
            if resp:
                token = resp.headers['X-Subject-Token']
            if body:
                return AccessInfoV3(token, **body['token'])
            else:
                return AccessInfoV3(token, **kwargs)
        elif AccessInfoV2.is_valid(body, **kwargs):
            if body:
                return AccessInfoV2(**body['access'])
            else:
                return AccessInfoV2(**kwargs)
        else:
            raise NotImplementedError('Unrecognized auth response')
    else:
        return AccessInfoV2(**kwargs)

def __init__(self, location=None, default_location=None):
