def __init__(self, synapses, code, prepost, objname=None):
    if prepost == 'pre':
        self.source = synapses.source
        self.synapse_indices = synapses.indices.pre_synaptic
    elif prepost == 'post':
        self.source = synapses.target
        self.synapse_indices = synapses.indices.post_synaptic
    else:
        raise ValueError('prepost argument has to be either "pre" or "post"')
    self.synapses = synapses
    indices = {'_neuron_idx': Index('_neuron_idx', False), '_postsynaptic_idx': Index('_postsynaptic_idx', False), '_presynaptic_idx': Index('_presynaptic_idx', False)}
    self.delays = DynamicArray1D(len(synapses.indices), dtype=np.int16)
    synapses.indices.register_variable(self.delays)
    self.queue = SpikeQueue()
    self.spiking_synapses = []
    self.specifiers = {'_spiking_synapses': AttributeValue('_spiking_synapses', Unit(1), np.int, self, 'spiking_synapses')}
    if objname is None:
        objname = prepost + '*'
    GroupCodeRunner.__init__(self, synapses, synapses.language.template_synapses, code=code, indices=indices, when=(synapses.clock, 'synapses'), name=synapses.name + '_' + objname, template_specifiers=['_num_neurons', '_presynaptic', '_postsynaptic', '_spiking_synapses'])
    self.objname = self.name[len(synapses.name) + 1:]

