            logger.warning(f'{type(key_error).__name__} in {load_method.__name__}: {key_error}')

def quality(self, offer, modifier=1):
    best_quality = None
    for (mask, quality) in self._parsed:
        if self._match(mask, offer):
            if best_quality is None or quality > best_quality:
                best_quality = quality * modifier
    return best_quality

def state_action_signal(self, model, prop_name, info):
    print('GSME state_action_signal: ', info['arg']) if 'arg' in info else print('XXX' + str(info))
    if 'arg' in info and info['arg'].action in ['change_root_state_type', 'change_state_type', 'substitute_state', 'group_states', 'ungroup_state', 'paste']:
        if info['arg'].after is False:
            self._complex_action = True
            if info['arg'].action in ['group_states', 'paste']:
                self.observe_model(info['arg'].action_parent_m)
            else:
                self.observe_model(info['arg'].affected_models[0])
            self.state_action_signal.__func__.affected_models = info['arg'].affected_models
            self.state_action_signal.__func__.target = info['arg'].action_parent_m

import re
import csv

def _get_numbers(contents):
    pattern = re.compile('^\x08(?:\\+44\\s?\\d{4}\\s?\\d{6}|\\d{10})\\b$')
    reader = csv.DictReader(contents.split('\n'), lineterminator='\n', quoting=csv.QUOTE_NONE)
    (valid, rejects) = ([], [])
    for (i, row) in enumerate(reader):
        if pattern.match(row['phone']):
            valid.append(row)
        else:
            rejects.append({'line_number': i + 2, 'phone': row['phone']})
    return {'valid': valid, 'rejects': rejects}

def requirements(with_pgi=None, with_examples=True, debug=True):
    reqs = list(BASE_REQUIREMENTS)
    if with_pgi is None:
        if is_pypy or is_jython:
            with_pgi = True
        else:
            with_pgi = False
    if debug:
        print('setup options: ')
        print('with_pgi:      ', 'yes' if with_pgi else 'no')
        print('with_examples: ', 'yes' if with_examples else 'no')
    if with_pgi:
        reqs.append('pgi')
        if debug:
            print('warning, as of April 2015 typography does not work with pgi')
    else:
        reqs.append('vext.gi>=0.1.3')
    if with_examples:
        reqs.extend(EXAMPLE_REQUIREMENTS)
    if debug:
        print('')
        print('')
        for req in reqs:
            print(req)
    return reqs

def _GetDecodeFunction(self, data_format: Text, schema: dataset_schema.Schema) -> Any:
    if self._ShouldDecodeAsRawExample(data_format):
        if self._IsDataFormatSequenceExample(data_format):
            absl.logging.warning("TFX Transform doesn't officially support tf.SequenceExample, follow b/38235367 to track official support progress. We do not guarantee not to break your pipeline if you use Transform with a tf.SequenceExample data type. Use at your own risk.")
        return self._DecodeAsRawExample
    return tft.coders.ExampleProtoCoder(schema, serialized=True).decode

def is_callable_method(cls_or_instance, method_name):
    method = getattr(cls_or_instance, method_name)
    if inspect.ismethod(method) and getattr(method, '__self__', None):
        return (method, True)
    try:
        from inspect import getattr_static
        return (method, isinstance(getattr_static(cls_or_instance, method_name, None), staticmethod))
    except ImportError:
        return (method, False)

