def _write_record(self, record):
    fields = ['s', '% -40s' % record.id.replace(' ', '_'), '%15s' % record.annotations.get('start', 0), record.annotations.get('strand', '+'), '%15s' % record.annotations.get('srcSize', 0), str(record.seq)]
    self.handle.write(' '.join(fields) + '\n')

def build_action_group(obj, name=None):
    import gtk
    group = gtk.ActionGroup(name or obj)
    for attrname in dir(obj):
        try:
            method = getattr(obj, attrname)
        except:
            continue
        act = getattr(method, '__action__', None)
        if isinstance(act, radio_action):
            actgroup = None
            if not act.labels: act.labels = [None] * len(act.names)
            if not act.tooltips: act.tooltips = [None] * len(act.names)
            if not act.stock_ids: act.stock_ids = [None] * len(act.names)
            if not act.accels: act.accels = [None] * len(act.names)
            assert len(act.names) == len(act.labels)
            assert len(act.names) == len(act.tooltips)
            assert len(act.names) == len(act.stock_ids)
            assert len(act.names) == len(act.accels)
            for i, n in enumerate(act.names):
                gtkact = gtk.RadioAction(n, act.labels[i], act.tooltips[i], act.stock_ids[i], value=i)
                if act.active == i:
                    gtkact.props.active = True
                if not actgroup:
                    actgroup = gtkact
                    gtkact.connect('changed', _radio_action_changed, obj, attrname)
                else:
                    gtkact.props.group = actgroup
                group.add_action_with_accel(gtkact, act.accels[i])
        elif isinstance(act, toggle_action):
            gtkact = gtk.ToggleAction(act.name, act.label, act.tooltip, act.stock_id)
            gtkact.set_property('active', act.active)
            gtkact.connect('activate', _toggle_action_activate, obj, attrname)
            group.add_action_with_accel(gtkact, act.accel)
        elif isinstance(act, action):
            gtkact = gtk.Action(act.name, act.label, act.tooltip, act.stock_id)
            gtkact.connect('activate', _action_activate, obj, attrname)
            group.add_action_with_accel(gtkact, act.accel)
        elif act is not None:
            raise TypeError, 'Invalid action type: %s' % action
    return group

def _recover_reaching_conditions(self):

    def _immediately_postdominates(node_a, node_b):
        if not self._region.successors:
            return True
        if len(self._region.successors) > 1:
            return any((networkx.immediate_dominators(networkx.reverse(self._region.graph_with_successors), succ)[node_b] is node_a for succ in self._region.successors))
        succ = next(iter(self._region.successors))
        if succ not in self._region.graph_with_successors:
            return True
        inverted_graph = networkx.reverse(self._region.graph_with_successors)
        idoms = networkx.immediate_dominators(inverted_graph, succ)
        return idoms[node_b] is node_a
    edge_conditions = {}
    predicate_mapping = {}
    end_nodes = set()
    for src in self._region.graph.nodes():
        nodes = list(self._region.graph[src])
        if len(nodes) >= 1:
            for dst in nodes:
                edge = (src, dst)
                predicate = self._extract_predicate(src, dst)
                edge_conditions[edge] = predicate
                predicate_mapping[predicate] = dst
        elif not nodes:
            end_nodes.add(src)
    reaching_conditions = {}
    sorted_nodes = CFGUtils.quasi_topological_sort_nodes(self._region.graph)
    for node in sorted_nodes:
        preds = self._region.graph.predecessors(node)
        reaching_condition = None
        if node is self._region.head:
            reaching_condition = claripy.true
        elif len(end_nodes) == 1 and node in end_nodes and _immediately_postdominates(node, self._region.head):
            reaching_conditions[node] = claripy.true
        else:
            for pred in preds:
                edge = (pred, node)
                pred_condition = reaching_conditions.get(pred, claripy.true)
                edge_condition = edge_conditions.get(edge, claripy.true)
                if reaching_condition is None:
                    reaching_condition = claripy.And(pred_condition, edge_condition)
                else:
                    reaching_condition = claripy.Or(claripy.And(pred_condition, edge_condition), reaching_condition)
        if reaching_condition is not None:
            reaching_conditions[node] = self._simplify_condition(reaching_condition)
    self._reaching_conditions = reaching_conditions

def _info(self) -> list:
    attrs = {'window_id': self._window_id}

    def by(val) -> bool:
        for key in attrs.keys():
            try:
                if attrs[key] != val[key]:
                    return False
            except KeyError:
                return False
        return True
    target_windows = list(filter(by, self.server._windows))
    if len(target_windows) == 0 and self.server._windows[0]['window_id'] == '@0':
        target_windows = self.server._windows
    return target_windows[0]

