def _log_model_stats(self, model):
    model = self.load_model(model)
    if model.val_score is not None:
        if model.eval_metric.name != self.eval_metric.name:
            logger.log(20, f'\tNote: model has different eval_metric than default.')
        if not model.eval_metric.greater_is_better:
            sign_str = '-'
        else:
            sign_str = ''
        logger.log(20, f'\t{round(model.val_score, 4)}\t = Validation score   ({sign_str}{model.eval_metric.name})')
    if model.fit_time is not None:
        logger.log(20, f'\t{round(model.fit_time, 2)}s\t = Training   runtime')
    if model.predict_time is not None:
        logger.log(20, f'\t{round(model.predict_time, 2)}s\t = Validation runtime')
    if model.predict_1_time is not None:
        fit_metadata = model.get_fit_metadata()
        predict_1_batch_size = fit_metadata.get('predict_1_batch_size', None)
        assert predict_1_batch_size is not None, 'predict_1_batch_size cannot be None if predict_1_time is not None'
        time_unit = 's'
        predict_1_time = model.predict_1_time
        if round(predict_1_time, 2) == 0:
            time_unit = 'ms'
            predict_1_time = predict_1_time * 1000
        logger.log(20, f'\t{round(predict_1_time, 3)}{time_unit}\t = Validation runtime (1 row | {predict_1_batch_size} batch size)')
        predict_1_time_full = self.get_model_attribute_full(model=model.name, attribute='predict_1_time')
        time_unit = 's'
        if round(predict_1_time_full, 2) == 0:
            time_unit = 'ms'
            predict_1_time_full = predict_1_time_full * 1000
        logger.log(20, f'\t{round(predict_1_time_full, 3)}{time_unit}\t = Validation runtime (1 row | {predict_1_batch_size} batch size | FULL)')

def get_hogql_autocomplete(query: HogQLAutocomplete, team: Team) -> HogQLAutocompleteResponse:
    response = HogQLAutocompleteResponse(suggestions=[], incomplete_list=False)
    database = create_hogql_database(team_id=team.pk, team_arg=team)
    context = HogQLContext(team_id=team.pk, team=team, database=database)
    original_query_select = copy(query.select)
    original_end_position = copy(query.endPosition)
    for (extra_characters, length_to_add) in [('', 0), (MATCH_ANY_CHARACTER, len(MATCH_ANY_CHARACTER)), (' FROM events', 0), (f'{MATCH_ANY_CHARACTER} FROM events', len(MATCH_ANY_CHARACTER))]:
        try:
            query.select = original_query_select[:original_end_position] + extra_characters + original_query_select[original_end_position:]
            query.endPosition = original_end_position + length_to_add
            select_ast = parse_select(query.select)
            if query.filters:
                try:
                    select_ast = cast(ast.SelectQuery, replace_filters(select_ast, query.filters, team))
                except Exception:
                    pass
            if isinstance(select_ast, ast.SelectQuery):
                ctes = select_ast.ctes
            else:
                ctes = select_ast.select_queries[0].ctes
            find_node = GetNodeAtPositionTraverser(select_ast, query.startPosition, query.endPosition)
            node = find_node.node
            parent_node = find_node.parent_node
            nearest_select = find_node.nearest_select_query or select_ast
            table_has_alias = nearest_select is not None and isinstance(nearest_select, ast.SelectQuery) and (nearest_select.select_from is not None) and (nearest_select.select_from.alias is not None)
            if isinstance(node, ast.Field) and isinstance(nearest_select, ast.SelectQuery) and (nearest_select.select_from is not None) and (not isinstance(parent_node, ast.JoinExpr)):
                table = get_table(context, nearest_select.select_from, ctes)
                if table is None:
                    continue
                chain_len = len(node.chain)
                last_table: Table = table
                for (index, chain_part) in enumerate(node.chain):
                    if table_has_alias and index == 0 and (chain_len == 1):
                        alias = nearest_select.select_from.alias
                        assert alias is not None
                        extend_responses(keys=[alias], suggestions=response.suggestions, kind=Kind.Folder, details=['Table'])
                        break
                    if table_has_alias and index == 0:
                        continue
                    is_last_part = index >= chain_len - 2
                    last_table = resolve_table_field_traversers(last_table)
                    if is_last_part:
                        if last_table.fields.get(str(chain_part)) is None:
                            append_table_field_to_response(table=last_table, suggestions=response.suggestions)
                            break
                        field = last_table.fields[str(chain_part)]
                        if isinstance(field, StringJSONDatabaseField):
                            if last_table.to_printed_hogql() == 'events':
                                property_type = PropertyDefinition.Type.EVENT
                            elif last_table.to_printed_hogql() == 'persons':
                                property_type = PropertyDefinition.Type.PERSON
                            elif last_table.to_printed_hogql() == 'groups':
                                property_type = PropertyDefinition.Type.GROUP
                            else:
                                property_type = None
                            if property_type is not None:
                                match_term = query.select[query.startPosition:query.endPosition]
                                if match_term == MATCH_ANY_CHARACTER:
                                    match_term = ''
                                properties = PropertyDefinition.objects.filter(name__contains=match_term, team_id=team.pk, type=property_type)[:PROPERTY_DEFINITION_LIMIT].values('name', 'property_type')
                                extend_responses(keys=[prop['name'] for prop in properties], suggestions=response.suggestions, details=[prop['property_type'] for prop in properties])
                                response.incomplete_list = True
                        elif isinstance(field, VirtualTable) or isinstance(field, LazyTable):
                            fields = list(last_table.fields.items())
                            extend_responses(keys=[key for (key, field) in fields], suggestions=response.suggestions, details=[convert_field_or_table_to_type_string(field) for (key, field) in fields])
                        elif isinstance(field, LazyJoin):
                            fields = list(field.join_table.fields.items())
                            extend_responses(keys=[key for (key, field) in fields], suggestions=response.suggestions, details=[convert_field_or_table_to_type_string(field) for (key, field) in fields])
                        break
                    else:
                        field = last_table.fields[str(chain_part)]
                        if isinstance(field, Table):
                            last_table = field
                        elif isinstance(field, LazyJoin):
                            last_table = field.join_table
            elif isinstance(node, ast.Field) and isinstance(parent_node, ast.JoinExpr):
                if len(node.chain) == 1:
                    table_names = database.get_all_tables()
                    extend_responses(keys=table_names, suggestions=response.suggestions, kind=Kind.Folder, details=['Table'] * len(table_names))
        except Exception:
            pass
        if len(response.suggestions) != 0:
            break
    return response

def ethhub_add_nio(self, request):
    if request is None:
        self.send_param_error()
        return
    log.debug('received request {}'.format(request))
    ethhub_id = request['id']
    if ethhub_id not in self._ethernet_hubs:
        self.send_custom_error("Ethernet hub id {} doesn't exist".format(ethhub_id))
        return
    ethhub = self._ethernet_hubs[ethhub_id]
    port = request['port']
    try:
        nio = self.create_nio(ethhub, request)
        if not nio:
            raise DynamipsError("Requested NIO doesn't exist: {}".format(request['nio']))
    except DynamipsError as e:
        self.send_custom_error(str(e))
        return
    try:
        ethhub.add_nio(nio, port)
    except DynamipsError as e:
        self.send_custom_error(str(e))
        return
    self.send_response(request)

def test_create_no_seed(python, creator, isolated, system, coverage_env, special_name_dir, method):
    dest = special_name_dir
    cmd = ['-v', '-v', '-p', ensure_text(python), ensure_text(str(dest)), '--without-pip', '--activators', '', '--creator', creator, '--{}'.format(method)]
    if isolated == 'global':
        cmd.append('--system-site-packages')
    result = cli_run(cmd)
    coverage_env()
    if IS_PYPY:
        gc.collect()
    content = list(result.creator.purelib.iterdir())
    assert not content, '\n'.join((ensure_text(str(i)) for i in content))
    assert result.creator.env_name == ensure_text(dest.name)
    debug = result.creator.debug
    sys_path = cleanup_sys_path(debug['sys']['path'])
    system_sys_path = cleanup_sys_path(system['sys']['path'])
    our_paths = set(sys_path) - set(system_sys_path)
    our_paths_repr = '\n'.join((ensure_text(repr(i)) for i in our_paths))
    assert len(our_paths) >= 1, our_paths_repr
    for path in our_paths:
        msg = '\n{}\ndoes not start with {}\nhas:\n{}'.format(ensure_text(str(path)), ensure_text(str(dest)), '\n'.join((ensure_text(str(p)) for p in system_sys_path)))
        assert str(path).startswith(str(dest)), msg
    assert any((p for p in our_paths if p.parts[-1] == 'site-packages')), our_paths_repr
    last_from_system_path = next((j for j in reversed(system_sys_path) if str(j).startswith(system['sys']['prefix'])))
    if isolated == 'isolated':
        assert last_from_system_path not in sys_path, 'last from system sys path {} is in venv sys path:\n{}'.format(ensure_text(str(last_from_system_path)), '\n'.join((ensure_text(str(j)) for j in sys_path)))
    else:
        common = []
        for (left, right) in zip(reversed(system_sys_path), reversed(sys_path)):
            if left == right:
                common.append(left)
            else:
                break

        def list_to_str(iterable):
            return [ensure_text(str(i)) for i in iterable]
        assert common, '\n'.join(difflib.unified_diff(list_to_str(sys_path), list_to_str(system_sys_path)))
    if sys.platform == 'win32':
        exes = ('python.exe',)
    else:
        exes = ('python', 'python{}.{}'.format(sys.version_info[0], sys.version_info[1]))
    for exe in exes:
        exe_path = result.creator.bin_dir / exe
        assert exe_path.exists()
        if not exe_path.is_symlink():
            continue
        link = os.readlink(str(exe_path))
        if not os.path.isabs(link):
            continue
        assert not link.startswith(str(result.creator.dest))

def _filter_search(request, qs, data, region=None, profile=None):
    order_by = []
    if data.get('q'):
        qs = qs.query(Q('function_score', query=name_query(data['q'].lower()), functions=[SF('field_value_factor', field='_boost')]))
    else:
        order_by = ['-popularity']
    form_to_es = {'cat': 'category', 'tag': 'tags', 'device': 'device', 'premium_types': 'premium_type', 'app_type': 'app_type', 'manifest_url': 'manifest_url', 'languages': 'supported_locales'}
    terms_fields = ('category', 'premium_type', 'app_type', 'supported_locales')
    for (k, field) in form_to_es.items():
        value = data.get(k)
        if value:
            filter_type = 'terms' if field in terms_fields else 'term'
            qs = qs.filter(filter_type, **{field: value})
    if data.get('offline') in (True, False):
        qs = qs.filter('term', is_offline=data['offline'])
    if profile:
        for (k, v) in profile.to_kwargs(prefix='features.has_').items():
            qs = qs.filter('term', **{k: v})
    if data.get('sort'):
        if 'popularity' in data['sort'] and region and (not region.adolescent):
            order_by = ['-popularity_%s' % region.id]
        else:
            order_by = [DEFAULT_SORTING[name] for name in data['sort'] if name in DEFAULT_SORTING]
    if order_by:
        qs = qs.sort(*order_by)
    return qs

def run(self, ignore_case=True, failfast=False):
    self.results = []
    if self.outlines:
        generator = self.evaluated
    else:
        generator = ((None, self.steps),)
    for (outline, steps) in generator:
        call_hook('before_each', 'scenario', self)
        try:
            if self.background:
                self.background.run(ignore_case=ignore_case)
            for step in steps:
                try:
                    step.pre_run(ignore_case=ignore_case, with_outline=outline)
                except NoDefinitionFound:
                    pass
            for step in steps:
                try:
                    call_hook('before_each', 'step', step)
                    call_hook('before_output', 'step', step)
                    step.run(ignore_case=ignore_case)
                except (NoDefinitionFound, AssertionError) as e:
                    if failfast:
                        raise FailFast()
                    break
                finally:
                    call_hook('after_output', 'step', step)
                    call_hook('after_each', 'step', step)
        except FailFast:
            return False
        finally:
            call_hook('after_each', 'scenario', self)
            if outline:
                call_hook('outline', 'scenario', self, order, outline, reasons_to_fail)
            steps_passed = [step for step in steps if step.passed]
            steps_failed = [step for step in steps if step.failed]
            steps_undefined = [step for step in steps if not step.has_definition]
            steps_skipped = [step for step in steps if step.has_definition and (not step.ran)]
            self.results.append(ScenarioResult(self, steps_passed, steps_failed, steps_skipped, steps_undefined))
    return True

def _call(self, method_name, *args, **kwargs):
    method = getattr(self.sigep, method_name)
    try:
        return method(*args, **kwargs)
    except Exception as e:
        print(f'Error occurred while calling {method_name}: {e}')

def predict(self, graph: Graph, support: Optional[Graph]=None, node_features: Optional[Union[pd.DataFrame, np.ndarray, List[Union[pd.DataFrame, np.ndarray]]]]=None, node_type_features: Optional[Union[pd.DataFrame, np.ndarray, List[Union[pd.DataFrame, np.ndarray]]]]=None, edge_type_features: Optional[Union[pd.DataFrame, np.ndarray, List[Union[pd.DataFrame, np.ndarray]]]]=None, edge_features: Optional[Union[Type[AbstractEdgeFeature], pd.DataFrame, np.ndarray, List[Union[pd.DataFrame, np.ndarray]]]]=None) -> np.ndarray:
    if not graph.has_nodes():
        raise ValueError('The provided graph is empty.')
    if not self._fitting_was_executed:
        raise ValueError('The prediction cannot be executed without having first executed the fitting of the model. Do call the `.fit` method before the `.predict` method.')
    if support is None:
        support = graph
    try:
        predictions = self._predict(graph=graph, support=support, node_features=self.normalize_node_features(graph=graph, support=support, random_state=self._random_state, node_features=node_features, allow_automatic_feature=False), node_type_features=self.normalize_node_type_features(graph=graph, support=support, random_state=self._random_state, node_type_features=node_type_features, allow_automatic_feature=True), edge_type_features=self.normalize_edge_type_features(graph=graph, support=support, random_state=self._random_state, edge_type_features=edge_type_features, allow_automatic_feature=False), edge_features=self.normalize_edge_features(graph=graph, support=support, random_state=self._random_state, edge_features=edge_features, allow_automatic_feature=False))
    except Exception as e:
        raise RuntimeError(f'An exception was raised while calling the `._predict` method of {self.model_name()} implemented using the {self.library_name()} for the {self.task_name()} task. Specifically, the class of the model is {self.__class__.__name__}.') from e
    return predictions

def _process_shade(groups, hostvars):
    options = _identify_shade_auth()
    cloud = shade.operator_cloud(**options)
    machines = cloud.list_machines()
    for machine in machines:
        if 'properties' not in machine:
            machine = cloud.get_machine(machine['uuid'])
        if machine['name'] is None:
            name = machine['uuid']
        else:
            name = machine['name']
        new_machine = {}
        mac_addresses = [port['mac_address'] for port in machine.get('ports', [])]
        new_machine['mac_addresses'] = mac_addresses
        for (key, value) in six.iteritems(machine):
            if key not in ['links', 'ports']:
                new_machine[key] = value
        new_machine['addressing_mode'] = 'dhcp'
        groups['baremetal']['hosts'].append(name)
        hostvars.update({name: new_machine})
    return (groups, hostvars)

def rtype_instantiate(hop):
    if hop.args_s[0].is_constant():
        INSTANCE = hop.s_result.rtyper_makerepr(hop.rtyper).lowleveltype
        v_instance = hop.inputconst(ootype.Void, INSTANCE)
        hop2 = hop.copy()
        (r, s) = hop2.r_s_popfirstarg()
        return rtype_new(hop2)
    else:
        INSTANCE = hop.s_result.rtyper_makerepr(hop.rtyper).lowleveltype
        c_instance = hop.inputconst(ootype.Void, INSTANCE)
        v_cls = hop.inputarg(hop.args_r[0], arg=0)
        v_obj = hop.gendirectcall(ll_instantiate, c_instance, v_cls)
        return hop.genop('oodowncast', [v_obj], resulttype=hop.r_result.lowleveltype)

def verify_checksums(filename):
    import warnings
    warnings.simplefilter('always')
    with warnings.catch_warnings(record=True) as wlist:
        with fits.open(filename, checksum=OPTIONS.checksum_kind) as hdulist:
            for (i, hdu) in enumerate(hdulist):
                if not OPTIONS.ignore_missing:
                    if not hdu._checksum:
                        log.warning('MISSING {!r} .. Checksum not found in HDU #{}'.format(filename, i))
                        return 1
                    if not hdu._datasum:
                        log.warning('MISSING {!r} .. Datasum not found in HDU #{}'.format(filename, i))
                        return 1
    for w in wlist:
        if str(w.message).startswith(('Checksum verification failed', 'Datasum verification failed')):
            log.warning('BAD %r %s', filename, str(w.message))
            return 1
    log.info(f'OK {filename!r}')
    return 0

async def group_int_or_str_attribute(account_map: dict[str, dict], number_of_accounts_resource_on: int, account_resources: Union[dict, list[dict]], key: Union[int, str]) -> Union[int, str, list[dict]]:
    if isinstance(account_resources, list):
        grouped_attribute = await base_group_str_attribute(account_map, account_resources)
    else:
        grouped_attribute = base_group_int_attribute(account_resources)
    if len(grouped_attribute) == 1:
        return list(grouped_attribute.keys())[0]
    response = []
    grouped_attribute = await set_included_accounts_for_grouped_attribute(account_map, number_of_accounts_resource_on, grouped_attribute)
    for (resource_val, included_accounts) in grouped_attribute.items():
        if included_accounts[0] == '*':
            response.append({key: resource_val})
        else:
            response.append({key: resource_val, 'included_accounts': included_accounts})
    return response

def print_tree(root, child_func, prune: int=0, showtags: bool=False, margin=None, visited=None, lastChild: bool=False, singleLineDraw: bool=False) -> None:
    if margin is None:
        margin = [0]
    rname = str(root)
    if visited is None:
        visited = {}
    if showtags:
        if showtags == 2:
            legend = ' E         = exists\n' + '  R        = exists in repository only\n' + '   b       = implicit builder\n' + '   B       = explicit builder\n' + '    S      = side effect\n' + '     P     = precious\n' + '      A    = always build\n' + '       C   = current\n' + '        N  = no clean\n' + '         H = no cache\n' + '\n'
            sys.stdout.write(legend)
        tags = ['[', ' E'[IDX(root.exists())], ' R'[IDX(root.rexists() and (not root.exists()))], ' BbB'[[0, 1][IDX(root.has_explicit_builder())] + [0, 2][IDX(root.has_builder())]], ' S'[IDX(root.side_effect)], ' P'[IDX(root.precious)], ' A'[IDX(root.always_build)], ' C'[IDX(root.is_up_to_date())], ' N'[IDX(root.noclean)], ' H'[IDX(root.nocache)], ']']
    else:
        tags = []

    def MMM(m):
        if singleLineDraw:
            return ['  ', BOX_VERT + ' '][m]
        return ['  ', '| '][m]
    margins = list(map(MMM, margin[:-1]))
    children = child_func(root)
    cross = '+-'
    if singleLineDraw:
        cross = BOX_VERT_RIGHT + BOX_HORIZ
        if lastChild:
            cross = BOX_UP_RIGHT + BOX_HORIZ
        if children:
            if prune and rname in visited and children:
                cross += BOX_HORIZ
            else:
                cross += BOX_HORIZ_DOWN
    if prune and rname in visited and children:
        sys.stdout.write(''.join(tags + margins + [cross, '[', rname, ']']) + '\n')
        return
    sys.stdout.write(''.join(tags + margins + [cross, rname]) + '\n')
    visited[rname] = 1
    if children:
        margin.append(1)
        idx = IDX(showtags)
        _child = 0
        for C in children[:-1]:
            _child = _child + 1
            print_tree(C, child_func, prune, idx, margin, visited, len(children) - _child <= 0, singleLineDraw)
        margin[-1] = 0
        print_tree(children[-1], child_func, prune, idx, margin, visited, True, singleLineDraw)
        margin.pop()

