def LoadSeqs(filename=None, format=None, data=None, moltype=None, name=None, aligned=True, label_to_name=None, parser_kw=None, constructor_kw=None, **kw):
    constructor_kw = constructor_kw or {}
    parser_kw = parser_kw or {}
    if filename is None:
        assert data is not None
        assert format is None
        assert not kw, kw
    else:
        assert data is None, (filename, data)
        data = list(FromFilenameParser(filename, format, **parser_kw))
    if aligned:
        if hasattr(aligned, '__call__'):
            return aligned(data=data, moltype=moltype, name=name, label_to_name=label_to_name, **constructor_kw)
        else:
            return Alignment(data=data, moltype=moltype, name=name, label_to_name=label_to_name, **constructor_kw)
    else:
        return SequenceCollection(data, moltype=moltype, name=name, label_to_name=label_to_name, **constructor_kw)

