def main():
    module = ForemanEntityApypieAnsibleModule(argument_spec=dict(name=dict(required=True), network_type=dict(choices=['IPv4', 'IPv6'], default='IPv4'), dns_primary=dict(), dns_secondary=dict(), domains=dict(type='list'), gateway=dict(), network=dict(required=True), cidr=dict(type='int'), mask=dict(), from_ip=dict(), to_ip=dict(), boot_mode=dict(choices=['DHCP', 'Static'], default='DHCP'), ipam=dict(choices=['DHCP', 'Internal DB'], default='DHCP'), dhcp_proxy=dict(), tftp_proxy=dict(), discovery_proxy=dict(), dns_proxy=dict(), remote_execution_proxies=dict(type='list'), vlanid=dict(type='int'), mtu=dict(type='int'), locations=dict(type='list'), organizations=dict(type='list'), parameters=dict(type='list', elements='dict', options=dict(name=dict(required=True), value=dict(type='raw', required=True), parameter_type=dict(default='string', choices=['string', 'boolean', 'integer', 'real', 'array', 'hash', 'yaml', 'json'])))), required_one_of=[['cidr', 'mask']], name_map=name_map)
    entity_dict = module.clean_params()
    module.connect()
    entity = module.find_resource_by_name('subnets', entity_dict['name'], failsafe=True)
    if not module.desired_absent:
        if 'mask' in entity_dict and 'cidr' not in entity_dict:
            entity_dict['cidr'] = IPNetwork('%s/%s' % (entity_dict['network'], entity_dict['mask'])).prefixlen
        elif 'mask' not in entity_dict and 'cidr' in entity_dict:
            entity_dict['mask'] = str(IPNetwork('%s/%s' % (entity_dict['network'], entity_dict['cidr'])).netmask)
        if 'domains' in entity_dict:
            entity_dict['domains'] = module.find_resources('domains', entity_dict['domains'], thin=True)
        for feature in ('dhcp_proxy', 'tftp_proxy', 'discovery_proxy', 'dns_proxy', 'remote_execution_proxies'):
            if feature in entity_dict:
                entity_dict[feature] = module.find_resource_by_name('smart_proxies', entity_dict[feature], thin=True)
        if 'organizations' in entity_dict:
            entity_dict['organizations'] = module.find_resources_by_name('organizations', entity_dict['organizations'], thin=True)
        if 'locations' in entity_dict:
            entity_dict['locations'] = module.find_resources_by_title('locations', entity_dict['locations'], thin=True)
    parameters = entity_dict.get('parameters')
    (changed, subnet) = module.ensure_resource('subnets', entity_dict, entity)
    scope = {'subnet': subnet}
    changed |= module.ensure_scoped_parameters(scope, entity, parameters)
    module.exit_json(changed=changed)

def _projection(self, widget=None):
    models = self._get_projectable_models()
    if not models:
        return
    self.core.get('update_progress')('Calculating 2D projection')
    total_models = len(models)
    for (index, model) in enumerate(models):
        self.core.get('update_progress')('Processing model %d of %d' % (index + 1, total_models))
        for (objname, z_level) in (('ProjectionModelTop', model.maxz), ('ProjectionModelMiddle', (model.minz + model.maxz) / 2.0), ('ProjectionModelBottom', model.minz), ('ProjectionModelCustom', self.gui.get_object('ProjectionZLevel').get_value())):
            if self.gui.get_object(objname).get_active():
                plane = Plane(Point(0, 0, z_level), Vector(0, 0, 1))
                self.log.info('Projecting 3D model at level z=%g' % plane.p.z)
                new_model = model.get_waterline_contour(plane)
                if new_model:
                    self.core.get('load_model')(new_model)
                    model_manager = self.core.get('models')
                    try:
                        original_name = model_manager.get_attr(model, 'name').split('(')[0].strip()
                        new_name = model_manager.get_attr(new_model, 'name')
                        model_manager.set_attr(new_model, 'name', '%s (projection of %s)' % (new_name, original_name))
                    except LookupError:
                        pass
                else:
                    self.log.warn('The 2D projection at z=%g is empty. Aborted.' % plane.p.z)
                break

def check_scales(scales):
    if isinstance(scales, (int, float)):
        return [scales]
    elif len(scales) == 1 and isinstance(scales[0], (int, float)):
        return list(scales)
    elif len(scales) > 1:
        return check_scales(scales[0]) + check_scales(scales[1:])
    else:
        raise ValueError('scales must be an int/float or a list/tuple of int/float')

