def remove_plugins(self, type_plugins):
    if not type_plugins:
        return
    removed = set()
    self.log_debug('Requested deletion of plugins: %s' % type_plugins)
    for (type, name) in type_plugins:
        rootplugins = os.path.join(pypath, 'module', 'plugins')
        folder = type + 's' if type in ('account', 'hook') else type
        for dir in ('userplugins', rootplugins):
            py_filename = fs_join(dir, folder, name + '.py')
            pyc_filename = py_filename + 'c'
            if type == 'hook':
                try:
                    self.manager.deactivateHook(name)
                except Exception as e:
                    self.log_debug(e, trace=True)
            for filename in (py_filename, pyc_filename):
                if not exists(filename):
                    continue
                try:
                    os.remove(filename)
                except OSError as e:
                    self.log_warning(_('Error removing: %s') % filename, e)
                else:
                    id = (type, name)
                    removed.add(id)
    return list(removed)

def service_to_instances(service, version=10):
    service_instances = []
    if not service.supported_protocol_bindings:
        raise Exception('No supported protocol bindings configured')
    for binding in service.supported_protocol_bindings:
        address = service.address
        if binding in PROTOCOL_TO_SCHEME:
            scheme = PROTOCOL_TO_SCHEME[binding]
            if scheme and (not address.startswith(scheme)):
                address = scheme + address
        if version == 10:
            stype = service.service_type
            if stype == SVC_COLLECTION_MANAGEMENT:
                stype = SVC_FEED_MANAGEMENT
            instance = tm10.ServiceInstance(service_type=stype, services_version=VID_TAXII_SERVICES_10, available=service.enabled, protocol_binding=binding, service_address=address, message_bindings=service.supported_message_bindings, message=service.description)
        elif version == 11:
            instance = tm11.ServiceInstance(service_type=service.service_type, services_version=VID_TAXII_SERVICES_11, available=service.enabled, protocol_binding=binding, service_address=address, message_bindings=service.supported_message_bindings, message=service.description)
        service_instances.append(instance)
    return service_instances

def verify_message_hash(self, sig_string: bytes, msg_hash: bytes) -> bool:
    assert_bytes(sig_string)
    if len(sig_string) != 64:
        return False
    if not (isinstance(msg_hash, bytes) and len(msg_hash) == 32):
        return False
    sig = create_string_buffer(64)
    ret = _libsecp256k1.secp256k1_ecdsa_signature_parse_compact(_libsecp256k1.ctx, sig, sig_string)
    if not ret:
        return False
    ret = _libsecp256k1.secp256k1_ecdsa_signature_normalize(_libsecp256k1.ctx, sig, sig)
    pubkey = self._to_libsecp256k1_pubkey_ptr()
    if 1 != _libsecp256k1.secp256k1_ecdsa_verify(_libsecp256k1.ctx, sig, msg_hash, pubkey):
        return False
    return True

