def uploadFile(self, entity, filename=None, used=None, executed=None):
    if isinstance(entity, basestring):
        if not filename:
            raise Exception('No filename specified in call to uploadFile')
        entity = self._getEntity(entity)
    if filename is None:
        if 'path' in entity:
            filename = entity['path']
        else:
            raise Exception("can't upload a file without a file path or URL")
    if 'name' not in entity or entity['name'] is None:
        entity['name'] = os.path.basename(filename)
    if is_locationable(entity):
        if not 'id' in entity:
            entity = self._createEntity(entity)
        entity.update(self._uploadFileAsLocation(entity, filename))
    else:
        if 'entityType' not in entity:
            entity['entityType'] = 'org.sagebionetworks.repo.model.FileEntity'
        if entity['entityType'] != 'org.sagebionetworks.repo.model.FileEntity':
            raise Exception('Files can only be uploaded to FileEntity entities')
        synapseStore = entity['synapseStore'] if 'synapseStore' in entity else None
        fileHandle = self._uploadToFileHandleService(filename, synapseStore=synapseStore)
        entity['dataFileHandleId'] = fileHandle['id']
    if 'id' in entity:
        return self.updateEntity(entity, used=used, executed=executed)
    else:
        return self.createEntity(entity, used=used, executed=executed)

def _format_arg(self, opt, spec, val):
    if opt == 'fixed_image_mask':
        if isdefined(self.inputs.moving_image_mask):
            return '--masks [ %s, %s ]' % (self.inputs.fixed_image_mask, self.inputs.moving_image_mask)
        else:
            return '--masks %s' % self.inputs.fixed_image_mask
    elif opt == 'transforms':
        return self._formatRegistration()
    elif opt == 'initial_moving_transform':
        try:
            doInvertTransform = int(self.inputs.invert_initial_moving_transform)
        except:
            doInvertTransform = 0
        return '--initial-moving-transform [ %s, %d ]' % (self.inputs.initial_moving_transform, doInvertTransform)
    elif opt == 'initial_moving_transform_com':
        try:
            doCenterOfMassInit = int(self.inputs.initial_moving_transform_com)
        except:
            doCenterOfMassInit = 0
        return '--initial-moving-transform [ %s, %s, %d ]' % (self.inputs.fixed_image[0], self.inputs.moving_image[0], doCenterOfMassInit)
    elif opt == 'interpolation':
        if self.inputs.interpolation in ['multilabel', 'gaussian', 'bspline']:
            return '--interpolation %s' % self.inputs.interpolation
        else:
            return '--interpolation %s' % self.inputs.interpolation
    elif opt == 'output_transform_prefix':
        out_filename = self._get_outputfilenames(inverse=False)
        inv_out_filename = self._get_outputfilenames(inverse=True)
        if out_filename and inv_out_filename:
            return '--output [ %s, %s, %s ]' % (self.inputs.output_transform_prefix, out_filename, inv_out_filename)
        elif out_filename:
            return '--output [ %s, %s ]' % (self.inputs.output_transform_prefix, out_filename)
        else:
            return '--output %s' % self.inputs.output_transform_prefix
    elif opt == 'winsorize_upper_quantile' or opt == 'winsorize_lower_quantile':
        if not self._quantilesDone:
            return self._formatWinsorizeImageIntensities()
        return ''
    return super(Registration, self)._format_arg(opt, spec, val)

def add_class(self, cls):
    if self.has_class(cls):
        return
    ns = cls.get_namespace()
    tn = cls.get_type_name()
    if not ns in self.imports:
        self.imports[ns] = set()
    extends = getattr(cls, '__extends__', None)
    if not extends is None:
        self.add_class(extends)
        parent_ns = extends.get_namespace()
        if parent_ns != ns and (not parent_ns in self.imports[ns]):
            self.imports[ns].add(parent_ns)
            logger.debug('\timporting %r to %r because %r extends %r' % (parent_ns, ns, cls.get_type_name(), extends.get_type_name()))
    bt = getattr(cls, '__base_type__', None)
    if not bt is None:
        self.add_class(bt)
        parent_ns = bt.get_namespace()
        if parent_ns != ns and (not parent_ns in self.imports[ns]) and self.is_valid_import(parent_ns):
            self.imports[ns].add(parent_ns)
            logger.debug('\timporting %r to %r because %r extends %r' % (parent_ns, ns, cls.get_type_name(), bt.get_type_name()))
    class_key = '{%s}%s' % (ns, tn)
    logger.debug('\tadding class %r for %r' % (repr(cls), class_key))
    assert class_key not in self.classes, "Somehow, you're trying to overwrite %r by %r for class key %r." % (self.classes[class_key], cls, class_key)
    self.classes[class_key] = cls
    if ns == self.get_tns():
        self.classes[tn] = cls
    if issubclass(cls, ComplexModelBase):
        for (k, v) in cls._type_info.items():
            if v is None:
                continue
            self.add_class(v)
            child_ns = v.get_namespace()
            if child_ns != ns and (not child_ns in self.imports[ns]) and self.is_valid_import(child_ns):
                self.imports[ns].add(child_ns)
                logger.debug('\timporting %r to %r for %s.%s(%r)' % (child_ns, ns, cls.get_type_name(), k, v))

def testEmergency(self):
    wrongTypeCounter = 0
    for regionCode in phonenumberutil.SUPPORTED_SHORT_REGIONS:
        if regionCode == 'PG':
            continue
        metadata = PhoneMetadata.short_metadata_for_region(regionCode, None)
        desc = metadata.emergency
        if desc.example_number is not None:
            exampleNumber = desc.example_number
            if not fullmatch(re.compile(desc.possible_number_pattern), exampleNumber) or not is_emergency_number(exampleNumber, regionCode):
                wrongTypeCounter += 1
                prnt('Emergency example number test failed for %s' % regionCode, file=sys.stderr)
            else:
                emergencyNumber = phonenumberutil.parse(exampleNumber, regionCode)
                if shortnumberinfo.expected_cost(emergencyNumber) != ShortNumberCost.TOLL_FREE:
                    wrongTypeCounter += 1
                    prnt('Emergency example number not toll free for %s' % regionCode, file=sys.stderr)
    self.assertEqual(0, wrongTypeCounter)

