def normalized(self) -> bool:
    for bb in self.basic_blocks:
        if len(bb.cfg_in) <= 1:
            continue
        for in_bb in bb.cfg_in:
            if len(in_bb.cfg_out) > 1:
                return False
            jump_inst = in_bb.instructions[-1]
            if jump_inst.opcode in ('jnz', 'djmp'):
                return False
    return True

def login(context, request):
    from kotti.views.util import TemplateAPIEdit
    root = get_root(request)
    api = TemplateAPIEdit(root, request)
    came_from = request.params.get('came_from', request.url)
    (login, password) = (u'', u'')
    if 'submitted' in request.POST:
        login = request.params['login']
        password = request.params['password']
        principals = get_principals()
        principal = principals.get(login)
        if principal is None:
            try:
                Email().to_python(login)
            except Exception:
                pass
            else:
                for p in principals.search(login):
                    if p.email == login:
                        principal = p
                        break
        if principal is not None and principal.password == principals.hash_password(password):
            headers = remember(request, login)
            request.session.flash(u'Welcome, %s!' % principal.title or principal.name, 'success')
            return HTTPFound(location=came_from, headers=headers)
        request.session.flash(u'Login failed.', 'error')
    return {'api': api, 'url': request.application_url + '/@@login', 'came_from': came_from, 'login': login, 'password': password}

def validate_role_yaml(role_data=None, role_path=None):
    if role_data and role_path or (not role_data and (not role_path)):
        raise ValueError('Either role_data OR role_path must be specified')
    if role_path:
        with open(role_path, 'r') as f:
            role_data = f.read()
    try:
        role = yaml.safe_load(role_data)[0]
    except yaml.YAMLError:
        raise RoleMetadataError('Unable to parse role yaml')
    schema = {'name': {'type': str}, 'CountDefault': {'type': int}, 'HostnameFormatDefault': {'type': str}, 'upgrade_batch_size': {'type': int}, 'ServicesDefault': {'type': list}, 'tags': {'type': list}, 'description': {'type': str}, 'networks': {'type': [list, dict]}, 'networks_skip_config': {'type': list}}
    if 'name' not in role:
        raise RoleMetadataError('Role name is missing from the role')
    for k in schema:
        if k in role:
            if k == 'networks':
                if not (isinstance(role[k], schema[k]['type'][0]) or isinstance(role[k], schema[k]['type'][1])):
                    msg = "Role '{}': {} is not of expected type {}".format(role['name'], k, schema[k]['type'])
                    raise RoleMetadataError(msg)
            elif not isinstance(role[k], schema[k]['type']):
                msg = "Role '{}': {} is not of expected type {}".format(role['name'], k, schema[k]['type'])
                raise RoleMetadataError(msg)
    return role

def __init__(self, **kw):
    for (k, v) in kw.items():
        if k not in ['name', 'description']:
            setattr(self, k, v)
    if not kw.has_key('version'):
        try:
            kw['version'] = self.version
        except AttributeError:
            raise AssertionError("Missing required parameter 'version'.")
    if not kw.has_key('description'):
        if self.__doc__ is not None:
            kw['description'] = self.__doc__
        else:
            raise AssertionError("Missing required parameter 'description'.")

    def argparser_factory(*args, **kwargs):
        kwargs.setdefault('conflict_handler', 'error')
        kwargs.setdefault('formatter_class', cli._ext.argparse.RawDescriptionHelpFormatter)
        return cli.app.CommandLineApp.argparser_factory(*args, **kwargs)
    self.argparser_factory = argparser_factory
    cli.app.CommandLineApp.__init__(name=os.path.splitext(os.path.basename(sys.argv[0]))[0], **kw)
    self.verbose_logging_threshold = 0

def process_ses_response(ses_request):
    client_name = 'SES'
    try:
        errors = validate_callback_data(data=ses_request, fields=['Message'], client_name=client_name)
        if errors:
            return errors
        ses_message = json.loads(ses_request['Message'])
        errors = validate_callback_data(data=ses_message, fields=['notificationType'], client_name=client_name)
        if errors:
            return errors
        notification_type = ses_message['notificationType']
        if notification_type == 'Bounce':
            if ses_message['bounce']['bounceType'] == 'Permanent':
                notification_type = ses_message['bounce']['bounceType']
            else:
                notification_type = 'Temporary'
        try:
            aws_response_dict = get_aws_responses(notification_type)
        except KeyError:
            error = '{} callback failed: status {} not found'.format(client_name, notification_type)
            return error
        notification_status = aws_response_dict['notification_status']
        try:
            reference = ses_message['mail']['messageId']
            notification = notifications_dao.update_notification_status_by_reference(reference, notification_status)
            if not notification:
                warning = 'SES callback failed: notification either not found or already updated from sending. Status {} for notification reference {}'.format(notification_status, reference)
                current_app.logger.warning(warning)
                return
            if not aws_response_dict['success']:
                current_app.logger.info('SES delivery failed: notification id {} and reference {} has error found. Status {}'.format(notification.id, reference, aws_response_dict['message']))
            else:
                current_app.logger.info('{} callback return status of {} for notification: {}'.format(client_name, notification_status, notification.id))
            statsd_client.incr('callback.ses.{}'.format(notification_status))
            if notification.sent_at:
                statsd_client.timing_with_dates('callback.ses.elapsed-time'.format(client_name.lower()), datetime.utcnow(), notification.sent_at)
            create_outcome_notification_statistic_tasks(notification)
            return
        except KeyError:
            error = 'SES callback failed: messageId missing'
            return error
    except ValueError:
        error = '{} callback failed: invalid json'.format(client_name)
        return error

def form_valid(self, form):
    form_data = form.cleaned_data
    share_destination = form_data['share_destination']
    selected_targets = self.request.POST.getlist('selected-target')
    data_switch = self.request.POST.get('dataSwitch', False)
    if 'HERMES' in share_destination.upper():
        response = share_data_with_hermes(share_destination, form_data, None, target_id, selected_data)
        sharing_feedback_handler(response, self.request)
    else:
        for target in selected_targets:
            form_data['target'] = Target.objects.get(id=target)
            response = share_target_with_tom(share_destination, form_data, target_lists=[form_data['target_list']])
            sharing_feedback_handler(response, self.request)
            if data_switch:
                response = share_data_with_tom(share_destination, form_data, target_id=target)
                sharing_feedback_handler(response, self.request)
        if not selected_targets:
            messages.error(self.request, f'No targets shared. {form.errors.as_json()}')
            return redirect(self.get_success_url())
    return redirect(self.get_success_url())

