async def _clean(self, from_network_storage=False):
    space_used_bytes = await self.get_space_used_bytes(from_network_storage)
    if from_network_storage:
        storage_limit = self.config.network_storage_limit * 1024 * 1024 if self.config.network_storage_limit else None
    else:
        storage_limit = self.config.blob_storage_limit * 1024 * 1024 if self.config.blob_storage_limit else None
    if self.analytics:
        asyncio.create_task(self.analytics.send_disk_space_used(space_used_bytes, storage_limit))
    if from_network_storage:
        await self.analytics.send_disk_space_used(space_used_bytes, storage_limit)
    if not storage_limit:
        return 0
    delete = []
    available = storage_limit - space_used_bytes
    if available > 0:
        return 0
    for (blob_hash, file_size, _) in await self.db.get_stored_blobs(is_mine=False, orphans=from_network_storage):
        delete.append(blob_hash)
        available += file_size
        if available > 0:
            break
    if delete:
        await self.db.stop_all_files()
        await self.blob_manager.delete_blobs(delete, delete_from_db=True)
    return len(delete)

def LoadProjectXML(project_xml):
    project_xml = project_xml.replace('http://www.plcopen.org/xml/tc6.xsd', 'http://www.plcopen.org/xml/tc6_0201')
    for (cre, repl) in [(re.compile('(?<!<xhtml:p>)(?:<!\\[CDATA\\[)'), '<xhtml:p><![CDATA['), (re.compile('(?:]]>)(?!</xhtml:p>)'), ']></xhtml:p>')]:
        project_xml = cre.sub(repl, project_xml)
    try:
        (tree, error) = PLCOpenParser.LoadXMLString(project_xml)
        if error is not None:
            return (tree, error)
        return (tree, None)
    except Exception as e:
        return (None, e.message)

def parseTargetDirect():
    if not conf.direct:
        return
    details = None
    for dbms in SUPPORTED_DBMS:
        details = re.search("^(?P<dbms>%s)://(?P<credentials>(?P<dbmsUser>.+?)\:(?P<dbmsPass>.+?)\@)?(?P<remote>(?P<hostname>.+?)\:(?P<port>[\d]+)\/)?(?P<dbmsDb>.+?)$" % dbms, conf.direct, re.I)
        if details:
            conf.dbms     = details.group('dbms')
            if details.group('credentials'):
                conf.dbmsUser = details.group('dbmsUser')
                conf.dbmsPass = details.group('dbmsPass')
            else:
                conf.dbmsUser = str()
                conf.dbmsPass = str()
            if details.group('remote'):
                conf.hostname = details.group('hostname')
                conf.port     = int(details.group('port'))
            else:
                conf.hostname = "localhost"
                conf.port     = 0
            conf.dbmsDb   = details.group('dbmsDb')
            conf.parameters[None] = "direct connection"
            break
    if not details:
        errMsg = "invalid target details, valid syntax is for instance: 'mysql://USER:PASSWORD@DBMS_IP:DBMS_PORT/DATABASE_NAME'"
        errMsg += " and/or: 'access://DATABASE_FILEPATH'"
        raise sqlmapSyntaxException, errMsg
    dbmsDict = { "Microsoft SQL Server": [MSSQL_ALIASES, "python-pymssql", "http://pymssql.sourceforge.net/"],
                 "MySQL": [MYSQL_ALIASES, "python-mysqldb", "http://mysql-python.sourceforge.net/"],
                 "PostgreSQL": [PGSQL_ALIASES, "python-psycopg2", "http://initd.org/psycopg/"],
                 "Oracle": [ORACLE_ALIASES, "python cx_Oracle", "http://cx-oracle.sourceforge.net/"],
                 "SQLite": [SQLITE_ALIASES, "", ""],
                 "Access": [ACCESS_ALIASES, "", ""],
                 "Firebird": [FIREBIRD_ALIASES, "", ""] }
    for dbmsName, data in dbmsDict.items():
        if conf.dbms in data[0]:
            try:
                if dbmsName == "Microsoft SQL Server":
                    import pymssql
                elif dbmsName == "MySQL":
                    import MySQLdb
                elif dbmsName == "PostgreSQL":
                    import psycopg2
                elif dbmsName == "Oracle":
                    import cx_Oracle
            except ImportError, _:
                errMsg  = "sqlmap requires %s third-party library " % data[1]
                errMsg += "in order to directly connect to the database "
                errMsg += "%s. Download from %s" % (dbmsName, data[2])
                raise sqlmapMissingDependence, errMsg

def _thread_run(self):
    while self._enabled:
        buf = self._queue.get(timeout=0.1)
        if buf:
            try:
                if buf.command == mmal.MMAL_EVENT_FORMAT_CHANGED:
                    self.inputs[0]._format_changed(buf)
                    for output in self.outputs:
                        out_buf = output.get_buffer()
                        out_buf.copy_from(buf)
                        output.send_buffer(out_buf)
                else:
                    try:
                        if self._callback(self.inputs[0], buf):
                            self._enabled = False
                    except Exception as e:
                        print(f'Error in callback: {e}')
            finally:
                buf.release()

