def getMemberNames(self):
    assert self.isCollection
    childlist = []
    l = len(self.path)
    seen = set()
    for f in self.provider.files:
        if f.startswith(self.path):
            p = f[l:]
            if '/' in p:
                p = p.split('/')[0]
            if p not in seen:
                seen.add(p)
                childlist.append(p)
        elif childlist:
            break
    return childlist

def parameterized_value_from_proto(message: operations_pb2.ParameterizedFloat) -> Union[Symbol, float]:
    if not message.parameter_key:
        return message.raw
    if message.raw != 0:
        raise ValueError('ParameterizedValue has a symbol and a constant.')
    return Symbol(message.parameter_key) if message.parameter_key else message.raw

async def __update_existing_commands(self):
    to_update: Dict[Snowflake, Dict[str, Any]] = {}

    def get_changes(api: AppCommand, local: AppCommand) -> Dict[str, Any]:
        update: Dict[str, Any] = {}
        if api.description != local.description:
            update['description'] = local.description
        if api.default_permission != local.default_permission:
            update['default_permission'] = local.default_permission
        options: List[Dict[str, Any]] = []
        if api.options is not MISSING:
            if len(api.options) == len(local.options):
                for (index, api_option) in enumerate(api.options):
                    opt: Optional[AppCommandOption] = get_index(local.options, index)
                    if opt:
                        options.append(opt.to_dict())
            else:
                options = local.options
        if api.options is not MISSING and list(map(AppCommandOption.from_dict, options)) != api.options:
            update['options'] = options
        return update
    for (idx, api_cmd) in enumerate(self._api_commands):
        for loc_cmd in ChatCommandHandler.register.values():
            if api_cmd.name != loc_cmd.app.name:
                continue
            changes = get_changes(api_cmd, loc_cmd.app)
            if not changes:
                continue
            api_update = []
            if changes.get('options'):
                for option in changes['options']:
                    api_update.append(option.to_dict() if isinstance(option, AppCommandOption) else option)
            to_update[api_cmd.id] = {'options': api_update}
            for (key, change) in changes.items():
                if key == 'options':
                    self._api_commands[idx].options = [AppCommandOption.from_dict(option) for option in change]
                else:
                    setattr(self._api_commands[idx], key, change)
    for (cmd_id, changes) in to_update.items():
        await self.client.http.patch(f'applications/{self.client.bot.id}/commands/{cmd_id}', changes)

