def process_file(self) -> None:
    jinad_file_path = Path(self._workdir) / self.extension
    if jinad_file_path.is_file():
        self.set_args(jinad_file_path)
        return
    _other_jinad_files = glob.glob(f'{Path(self._workdir)}/*{self.extension}')
    if not _other_jinad_files:
        self._logger.warning(f'please add a .jinad file to manage the docker image in the workspace')
    elif len(_other_jinad_files) == 1:
        self.set_args(Path(_other_jinad_files[0]))
    else:
        raise Runtime400Exception(f"Multiple .jinad files found in workspace: {', '.join([os.path.basename(f) for f in _other_jinad_files])}")

def workorderwizard_submit(request):
    if not request.user.is_authenticated:
        return HttpResponse('Unauthorized', status=401)
    data = json.loads(request.body.decode('utf-8'))
    mandatory_fields = ('org', 'event_name', 'location', 'start', 'end', 'setup_complete', 'services')
    if not all((key in data for key in mandatory_fields)):
        return HttpResponse('Unprocessable Entity', status=422)
    reversion.set_comment('Event submitted using work order wizard')
    event = events_models.Event2019()
    event.submitted_by = request.user
    event.submitted_ip = request.META.get('REMOTE_ADDR')
    event.contact = request.user
    event.event_name = data['event_name']
    if 'description' in data:
        event.description = data['description']
    try:
        event.location = events_models.Location.objects.filter(show_in_wo_form=True).get(pk=data['location'])
    except events_models.Location.DoesNotExist:
        return HttpResponse('Unprocessable Entity', status=422)
    event.datetime_setup_complete = parse_datetime(data['setup_complete'])
    event.datetime_start = parse_datetime(data['start'])
    event.datetime_end = parse_datetime(data['end'])
    try:
        org = events_models.Organization.objects.get(pk=data['org'])
    except events_models.Organization.DoesNotExist:
        return HttpResponse('Unprocessable Entity', status=422)
    event.billing_org = org
    event.save()
    event.org.add(org)
    for service_data in data['services']:
        if 'id' not in service_data:
            return HttpResponse('Unprocessable Entity', status=422)
        try:
            service = events_models.Service.objects.filter(enabled_event2019=True).get(shortname=service_data['id'])
        except events_models.Service.DoesNotExist:
            return HttpResponse('Unprocessable Entity', status=422)
        service_instance = events_models.ServiceInstance()
        service_instance.service = service
        service_instance.event = event
        if 'detail' in service_data:
            service_instance.detail = service_data['detail']
        service_instance.save()
    for extra_data in data['extras']:
        if not all((key in extra_data for key in ('id', 'quantity'))):
            return HttpResponse('Unprocessable Entity', status=422)
        try:
            extra = events_models.Extra.objects.filter(disappear=False).get(name=extra_data['id'])
        except events_models.Extra.DoesNotExist:
            return HttpResponse('Unprocessable Entity', status=422)
        extra_instance = events_models.ExtraInstance()
        extra_instance.extra = extra
        extra_instance.event = event
        extra_instance.quant = extra_data['quantity']
        extra_instance.save()
    email_body = 'You have successfully submitted the following event.'
    bcc = [settings.EMAIL_TARGET_VP, settings.EMAIL_TARGET_HP] if event.has_projection else [settings.EMAIL_TARGET_VP]
    email = EventEmailGenerator(event=event, subject='New Event Submitted', to_emails=[request.user.email], body=email_body, bcc=bcc)
    email.send()
    if not request.user.has_perm('events.create_org_event', org):
        email_body = 'The following event was submitted. You are receiving this email because the user who submitted this event is not expressly authorized to submit events on behalf of {}. The organization owner can update authorized users through the website.'.format(org.name)
        email = EventEmailGenerator(event=event, subject='Event Submitted on behalf of {}'.format(org.name), to_emails=[org.exec_email], body=email_body, bcc=[settings.EMAIL_TARGET_W])
        email.send()
    return HttpResponse(json.dumps({'event_url': reverse('events:detail', args=[event.pk])}))

def __init__(self, estimator=None, *, n_estimators=50, learning_rate=1.0, algorithm='SAMME.R', sampling_strategy='auto', replacement=False, random_state=None, base_estimator='deprecated'):
    bagging_classifier_signature = inspect.signature(super().__init__)
    estimator_params = {'base_estimator': base_estimator}
    if 'estimator' in bagging_classifier_signature.parameters:
        estimator_params['estimator'] = estimator
    else:
        self.estimator = estimator
    super().__init__(**estimator_params, n_estimators=n_estimators, learning_rate=learning_rate, algorithm=algorithm, random_state=random_state)
    self.sampling_strategy = sampling_strategy
    self.replacement = replacement

def check_no_contextlib_nested(logical_line, filename):
    msg = 'N324: contextlib.nested is deprecated. With Python 2.7 and later the with-statement supports multiple nested objects. See https://docs.python.org/2/library/contextlib.html#contextlib.nested for more information.'
    ignore_dirs = ['neutron/tests/unit/db', 'neutron/tests/unit/extensions', 'neutron/tests/unit/plugins', 'neutron/tests/unit/scheduler']
    for directory in ignore_dirs:
        if directory in filename:
            return
    if contextlib_nested.match(logical_line):
        yield (0, msg)

def deploy_axis_func(cls, axis, func, num_splits, maintain_partitioning, *partitions, **kwargs):
    manual_partition = kwargs.pop('manual_partition', False)
    lengths = kwargs.pop('_lengths', None)
    dataframe = pandas.concat(list(partitions), axis=axis, copy=False)
    result = func(dataframe, **kwargs)
    if num_splits == 1:
        lengths = None
    elif manual_partition:
        lengths = list(lengths)
    elif num_splits != len(partitions) or not maintain_partitioning:
        lengths = None
    elif axis == 0:
        lengths = [len(part) for part in partitions]
        if sum(lengths) != len(result):
            lengths = None
    else:
        lengths = [len(part.columns) for part in partitions]
        if sum(lengths) != len(result.columns):
            lengths = None
    return split_result_of_axis_func_pandas(axis, num_splits, result, lengths)

def map_features_prot2dna(prot_seqbuddy, dna_seqbuddy):
    prot_dict = SeqIO.to_dict(prot_seqbuddy.records)
    dna_dict = SeqIO.to_dict(dna_seqbuddy.records)
    _new_seqs = {}
    for _seq_id in prot_dict:
        if _seq_id not in dna_dict:
            sys.stderr.write('Warning: %s is in protein file, but not cDNA file\n' % _seq_id)
            continue
        _new_seqs[_seq_id] = dna_dict[_seq_id]
        for feature in prot_dict[_seq_id].features:
            _start = feature.location.start * 3
            _end = feature.location.end * 3
            location = FeatureLocation(_start, _end)
            feature.location = location
            dna_dict[_seq_id].features.append(feature)
    for _seq_id in dna_dict:
        if _seq_id not in prot_dict:
            sys.stderr.write('Warning: %s is in cDNA file, but not protein file\n' % _seq_id)
    _seqs_list = [_new_seqs[_seq_id] for _seq_id in _new_seqs]
    _seqbuddy = SeqBuddy(_seqs_list)
    _seqbuddy.out_format = 'gb'
    return _seqbuddy

