def make_refnode(self, document, env, key):
    cited = env.temp_data.setdefault('bibtex_foot_cited', {})
    for otherkeys in cited.values():
        if key in otherkeys:
            break
    else:
        keys = cited.setdefault(env.temp_data['bibtex_foot_bibliography_id'], oset())
        keys.add(key)
    entry = self.backend.get_entry(key)
    return self.backend.footnote_reference(entry, document)

def returnObsoletes(self, newest=False):
    if not newest:
        return self._computeAggregateDictResult('returnObsoletes')
    obsdict = self._computeAggregateDictResult('returnObsoletes')
    newest_tups = {pkg.pkgtup for pkg in self.returnNewestByName()}
    obsdict = {obstup: obs for (obstup, obs) in obsdict.items() if obstup in newest_tups}
    return obsdict

