def _load_versions(self):
    import pkg_resources
    try:
        from qiskit.providers import aer
        self._version_dict['qiskit-aer'] = aer.__version__
    except Exception:
        self._version_dict['qiskit-aer'] = None
    try:
        from qiskit import ignis
        self._version_dict['qiskit-ignis'] = ignis.__version__
    except Exception:
        self._version_dict['qiskit-ignis'] = None
    try:
        from qiskit.providers import ibmq
        self._version_dict['qiskit-ibmq-provider'] = ibmq.__version__
    except Exception:
        self._version_dict['qiskit-ibmq-provider'] = None
    try:
        from qiskit import aqua
        self._version_dict['qiskit-aqua'] = aqua.__version__
    except Exception:
        self._version_dict['qiskit-aqua'] = None
    try:
        import qiskit_nature
        self._version_dict['qiskit-nature'] = qiskit_nature.__version__
    except Exception:
        self._version_dict['qiskit-nature'] = None
    try:
        import qiskit_finance
        self._version_dict['qiskit-finance'] = qiskit_finance.__version__
    except Exception:
        self._version_dict['qiskit-finance'] = None
    try:
        import qiskit_optimization
        self._version_dict['qiskit-optimization'] = qiskit_optimization.__version__
    except Exception:
        self._version_dict['qiskit-optimization'] = None
    try:
        import qiskit_machine_learning
        self._version_dict['qiskit-machine-learning'] = qiskit_machine_learning.__version__
    except Exception:
        self._version_dict['qiskit-machine-learning'] = None
    try:
        self._version_dict['qiskit'] = pkg_resources.get_distribution('qiskit').version
    except Exception:
        self._version_dict['qiskit'] = None
    self._loaded = True

def feed_output(self, feed):
    try:
        from deluge.ui.client import sclient
    except:
        raise PluginError('Deluge module required')
    config = self.get_config(feed)
    if feed.manager.options.learn:
        return
    if not feed.accepted:
        return
    sclient.set_core_uri()
    opts = {}
    for entry in feed.accepted:
        if config['movedone'] or config['label']:
            before = sclient.get_session_state()
        if 'path' in entry:
            opts['download_location'] = entry['path']
        elif config['path']:
            opts['download_location'] = config['path']
        if not os.path.exists(entry['file']):
            tmp_path = os.path.join(sys.path[0], 'temp')
            log.debug('entry: %s' % entry)
            log.debug('temp: %s' % ', '.join(os.listdir(tmp_path)))
            raise PluginWarning("Downloaded temp file '%s' doesn't exist!?") % entry['file']
        sclient.add_torrent_file([entry['file']], [opts])
        log.info('%s torrent added to deluge with options %s' % (entry['title'], opts))
        if not feed.config.has_key('download'):
            os.remove(entry['file'])
            del entry['file']
        if config['movedone'] or config['label']:
            time.sleep(1)
            after = sclient.get_session_state()
            for item in after:
                if not item in before:
                    if config['movedone']:
                        sclient.set_torrent_move_on_completed(item, True)
                        sclient.set_torrent_move_on_completed_path(item, str(config['movedone']) % entry)
                    if config['label']:
                        if not 'label' in sclient.get_enabled_plugins():
                            sclient.enable_plugin('label')
                        if not config['label'] in sclient.label_get_labels():
                            sclient.label_add(config['label'])
                        sclient.label_set_torrent(item, config['label'])
                    break

def load_nanomax_data(logfile, detector, flatfield, hotpixels, background, normalize='skip', debugging=False):
    import hdf5plugin
    import h5py
    if debugging:
        print(str(logfile['entry']['description'][()])[3:-2])
    mask_2d = np.zeros((detector.nb_pixel_y, detector.nb_pixel_x))
    group_key = list(logfile.keys())[0]
    try:
        tmp_data = logfile['/' + group_key + '/measurement/merlin/frames'][:]
    except KeyError:
        tmp_data = logfile['/' + group_key + 'measurement/Merlin/data'][()]
    nb_img = tmp_data.shape[0]
    print('Number of frames:', nb_img)
    if detector.roi[0] < 0 or detector.roi[1] > detector.nb_pixel_y or detector.roi[2] < 0 or (detector.roi[3] > detector.nb_pixel_x):
        print('Data shape is limited by detector size, loaded data will be smaller than as defined by the ROI.')
    loading_roi = [max(0, detector.roi[0]), min(detector.nb_pixel_y, detector.roi[1]), max(0, detector.roi[2]), min(detector.nb_pixel_x, detector.roi[3])]
    data = np.empty((nb_img, loading_roi[1] - loading_roi[0], loading_roi[3] - loading_roi[2]), dtype=float)
    if normalize == 'sum_roi':
        monitor = np.zeros(nb_img)
    elif normalize == 'monitor':
        monitor = logfile['/' + group_key + '/measurement/alba2'][:]
    else:
        monitor = np.ones(nb_img)
    for idx in range(nb_img):
        ccdraw = np.flipud(tmp_data[idx, :, :])
        if background is not None:
            ccdraw = ccdraw - background
        (ccdraw, mask_2d) = remove_hotpixels(data=ccdraw, mask=mask_2d, hotpixels=hotpixels)
        if detector.name == 'Merlin':
            (ccdraw, mask_2d) = mask_merlin(ccdraw, mask_2d)
        else:
            raise ValueError('Detector ', detector.name, 'not supported for NANOMAX')
        if flatfield is not None:
            ccdraw = flatfield * ccdraw
        if normalize == 'sum_roi':
            monitor[idx] = util.sum_roi(array=ccdraw, roi=detector.sum_roi)
        ccdraw = ccdraw[loading_roi[0]:loading_roi[1], loading_roi[2]:loading_roi[3]]
        data[idx, :, :] = ccdraw
        sys.stdout.write('\rLoading frame {:d}'.format(idx + 1))
        sys.stdout.flush()
    print('')
    mask_2d = mask_2d[loading_roi[0]:loading_roi[1], loading_roi[2]:loading_roi[3]]
    (data, mask_2d) = check_pixels(data=data, mask=mask_2d, debugging=debugging)
    mask3d = np.repeat(mask_2d[np.newaxis, :, :], nb_img, axis=0)
    mask3d[np.isnan(data)] = 1
    data[np.isnan(data)] = 0
    frames_logical = np.ones(nb_img)
    return (data, mask3d, monitor, frames_logical)

