def qt5_plugins_dir():
    if 'QT_PLUGIN_PATH' in os.environ and os.path.isdir(os.environ['QT_PLUGIN_PATH']):
        return str(os.environ['QT_PLUGIN_PATH'])
    qt5_plugin_dirs = eval_statement('from PyQt5.QtCore import QCoreApplication;app=QCoreApplication([]);print([str(path) for path in app.libraryPaths()])')
    if not qt5_plugin_dirs:
        logger.error('Cannot find PyQt5 plugin directories')
        return ''
    for d in qt5_plugin_dirs:
        if os.path.isdir(d):
            return str(d)
    logger.error('Cannot find existing PyQt5 plugin directory')
    return ''

def set(self, item, value):
    if value.ndim == self.ndim - 1:
        value = value.reshape((1,) + value.shape)
    assert value.shape[1:] == self.shape[1:]
    if item in self.items:
        (i, block) = self._find_block(item)
        if not block.can_store(value):
            self._delete_from_block(i, item)
            self._add_new_block(item, value)
        else:
            block.set(item, value)
    else:
        new_items = _insert_into_items(self.items, item, len(self.items))
        self.set_items_norename(new_items)
        self._add_new_block(item, value)

def add_model_components(m, d):
    m.overgeneration_penalty_per_mw = Param(m.LOAD_ZONES, within=NonNegativeReals)
    m.unserved_energy_penalty_per_mw = Param(m.LOAD_ZONES, within=NonNegativeReals)
    m.Overgeneration_MW = Var(m.LOAD_ZONES, m.TIMEPOINTS, within=NonNegativeReals)
    m.Unserved_Energy_MW = Var(m.LOAD_ZONES, m.TIMEPOINTS, within=NonNegativeReals)

    def meet_load_rule(mod, z, tmp):
        return sum((getattr(mod, component)[z, tmp] for component in getattr(d, load_balance_production_components))) == sum((getattr(mod, component)[z, tmp] for component in getattr(d, load_balance_consumption_components)))
    m.Meet_Load_Constraint = Constraint(m.LOAD_ZONES, m.TIMEPOINTS, rule=meet_load_rule)

def __init__(self, ds, center='c', width=None, axes_unit=None, origin='center-window', right_handed=True, fontsize=18, field_parameters=None, window_size=8.0, aspect=None, data_source=None, buff_size=(800, 800), *, north_vector=None):
    if north_vector is not None:
        mylog.warning("Ignoring 'north_vector' keyword as it is ill-defined for an AxisAlignedSlicePlot object.")
        del north_vector
    normal = self._validate_init_args(normal=None, axis=None, fields=None)
    normal = self.sanitize_normal_vector(ds, normal)
    axis = fix_axis(normal, ds)
    (bounds, center, display_center) = get_window_parameters(axis, center, width, ds)
    if field_parameters is None:
        field_parameters = {}
    if isinstance(ds, YTSpatialPlotDataset):
        slc = ds.all_data()
        slc.axis = axis
        if slc.axis != ds.parameters['axis']:
            raise RuntimeError(f"Original slice axis is {ds.parameters['axis']}.\n")
    else:
        slc = ds.slice(axis, center[axis], field_parameters=field_parameters, center=center, data_source=data_source)
        slc.get_data(None)
    validate_mesh_fields(slc, None)
    PWViewerMPL.__init__(self, slc, bounds, origin=origin, fontsize=fontsize, fields=None, window_size=window_size, aspect=aspect, right_handed=right_handed, buff_size=buff_size, geometry=ds.geometry)
    if axes_unit is None:
        axes_unit = get_axes_unit(width, ds)
    self.set_axes_unit(axes_unit)

def follow(self, anchor, context=None):
    if isinstance(anchor, basestring):
        link = None
        for l in (context or self.doc).cssselect('a'):
            if get_all_text(l) == anchor:
                link = l
                break
    elif isinstance(anchor, RE_TYPE):
        link = None
        for l in (context or self.doc).cssselect('a'):
            if re.search(anchor, get_all_text(l)):
                link = l
                break
    elif isinstance(anchor, lxml.etree._Element):
        link = anchor
    else:
        raise ScrapeError('Unexpected type for anchor: %r' % anchor)
    if link is None:
        raise ScrapeError('link %r not found' % anchor)
    href = link.get('href')
    if not href:
        raise ScrapeError('link %r has no href' % link)
    return self.go(href)

