def _get_num_gpus(ray_start_params: Dict[str, str], k8s_resource_limits: Dict[str, Any], group_name: str) -> Optional[int]:
    if 'num-gpus' in ray_start_params:
        return int(ray_start_params['num-gpus'])
    for key in k8s_resource_limits:
        global _GPU_WARNING_LOGGED
        if 'gpu' in key and (not _GPU_WARNING_LOGGED):
            with suppress(Exception):
                if int(k8s_resource_limits[key]) > 0:
                    logger.warning(f'Detected GPUs in container resources for group {group_name}.To ensure Ray and the autoscaler are aware of the GPUs, set the `--num-gpus` rayStartParam.')
                    _GPU_WARNING_LOGGED = True
            break
    return None

def vote():
    annotator = get_current_annotator()
    if annotator.prev.id == int(request.form['prev_id']) and annotator.next.id == int(request.form['next_id']):
        if request.form['action'] == 'Skip':
            annotator.ignore.append(annotator.next)
        elif request.form['action'] == 'SkipNotHere':
            flag_team(annotator)
            annotator.ignore.append(annotator.next)
        else:
            if annotator.prev.active and annotator.next.active:
                if request.form['action'] == 'Previous':
                    perform_vote(annotator, next_won=False)
                    decision = Decision(annotator, winner=annotator.prev, loser=annotator.next)
                    print('Triggered Previous')
                elif request.form['action'] == 'Current':
                    perform_vote(annotator, next_won=True)
                    decision = Decision(annotator, winner=annotator.next, loser=annotator.prev)
                    print('Triggered Current')
                else:
                    return
                db.session.add(decision)
            annotator.next.viewed.append(annotator)
            annotator.prev = annotator.next
            annotator.ignore.append(annotator.prev)
        annotator.update_next(choose_next(annotator))
        db.session.commit()
    return redirect(url_for('index'))

def ENUM(self, _cursor_type):
    _decl = _cursor_type.get_declaration()
    name = self.get_unique_name(_decl)
    if self.is_registered(name):
        obj = self.get_registered(name)
    else:
        obj = self.parse_cursor(_decl)
    return obj

def __array_ufunc__(self, ufunc: np.ufunc, method: str_t, *inputs, **kwargs):
    if any((isinstance(other, (ABCSeries, ABCDataFrame)) for other in inputs)):
        return NotImplemented
    if not (method == '__call__' and ufunc in (np.bitwise_and, np.bitwise_or, np.bitwise_xor)):
        result = arraylike.maybe_dispatch_ufunc_to_dunder_op(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    if 'out' in kwargs:
        return arraylike.dispatch_ufunc_with_out(self, ufunc, method, *inputs, **kwargs)
    if method == 'reduce':
        result = arraylike.dispatch_reduction_ufunc(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    new_inputs = [x if x is not self else x._values for x in inputs]
    result = getattr(ufunc, method)(*new_inputs, **kwargs)
    if ufunc.nout == 2:
        return tuple((self.__array_wrap__(x) for x in result))
    return self.__array_wrap__(result)

def _alloc_image(self, name):
    from pyglet import image
    file = self.file(name)
    img = image.load(name, file=file)
    bin = self._get_texture_atlas_bin(img.width, img.height)
    if bin is None:
        return img.get_texture(True)
    for atlas in bin:
        try:
            return atlas.add(img)
        except rectallocator.AllocatorException:
            pass
    atlas = TextureAtlas(256, 256)
    bin.append(atlas)
    return atlas.add(img)

def get_all_edge_attrs(self) -> List[EdgeAttr]:
    if not hasattr(self, '_edge_attrs'):
        return []
    added_attrs = set()
    edge_attrs = self._edge_attrs.values()
    for attr in edge_attrs:
        attr.size = (self.num_nodes, self.num_nodes)
        added_attrs.add(attr.layout)
    for (layout, attr_name) in EDGE_LAYOUT_TO_ATTR_NAME.items():
        if attr_name in self and layout not in added_attrs:
            edge_attrs.append(EdgeAttr(edge_type=None, layout=layout, size=(self.num_nodes, self.num_nodes)))
    return edge_attrs

