def _load_json(self, protocol_source: ProtocolSource) -> None:
    protocol = self._json_file_reader.read(protocol_source)
    commands = self._json_translator.translate_commands(protocol)
    liquids = self._json_translator.translate_liquids(protocol)
    for liquid in liquids:
        self._protocol_engine.add_liquid(id=liquid.id, name=liquid.displayName, description=liquid.description, color=liquid.displayColor)
    for command in commands:
        self._protocol_engine.add_command(request=command)
    self._task_queue.set_run_func(func=self._protocol_engine.wait_until_complete)

def _prepare_aggregations(self, sort_field: str, start: datetime, end: datetime, having: Sequence[Sequence[Any]]) -> list[Any]:
    extra_aggregations = self.dependency_aggregations.get(sort_field, [])
    required_aggregations = set([sort_field, 'total'] + extra_aggregations)
    for h in having:
        alias = h[0]
        required_aggregations.add(alias)
    aggregations = []
    for alias in required_aggregations:
        aggregation = self.aggregation_defs[alias]
        if callable(aggregation):
            aggregation = aggregation(start, end)
        aggregations.append(aggregation + [alias])
    return aggregations

def close(self) -> None:
    if self.closed:
        return
    if not self.mark_end_on_close or self.ctx_task_deferred:
        self.closed = True
        return
    if self.handler is None:
        self.closed = True
        return
    if self.handler.stream is None or self.handler.stream.closed:
        self.handler.stream = self.handler._open()
    self.emit(logging.makeLogRecord({'msg': self.end_of_log_mark}))
    if self.write_stdout:
        self.handler.close()
        sys.stdout = sys.__stdout__
    super().close()
    self.closed = True

async def run(self) -> RoverState:
    ball_in_frame = True
    center = 0
    radius = 1
    if ball_in_frame:
        ((left, right), distance) = algorithms.follow_marker.drive_to_marker(75, center, radius)
        self.logger.info('Marker in frame')
        if distance < 0.5:
            interfaces.drive_board.stop()
            self.logger.info('Reached Marker')
            core.rovecomm_node.write(core.RoveCommPacket(core.manifest['Autonomy']['Telemetry']['ReachedMarker']['dataId'], 'B', 1), True)
            interfaces.multimedia_board.send_lighting_state(core.OperationState.REACHED_MARKER)
            return self.on_event(core.AutonomyEvents.REACHED_MARKER)
        else:
            self.logger.debug(f'Driving to target with speeds: ({left}, {right})')
            interfaces.drive_board.send_drive(left, right)
    else:
        self.logger.info('Lost sign of marker, returning to Search Pattern')
        return self.on_event(core.AutonomyEvents.MARKER_UNSEEN)
    return self

def process(self, start_state, loop):
    self.start_state = start_state.copy()
    assert loop.isStatementLoop()
    loop_body = loop.getLoopBody()
    if loop_body is not None:
        result = self.onStatementsSequence(loop_body)
        if result is not loop_body:
            loop_body.replaceWith(result)

def _estimator_has(attr):

    def check(self):
        if hasattr(self, 'estimators_'):
            return hasattr(self.estimators_[0], attr)
        elif self.estimator is not None:
            return hasattr(self.estimator, attr)
        else:
            return False
    return check

