    features = _get_features(FeatureToggle.ALLOW_IDCHECK_REGISTRATION, FeatureToggle.AUTO_ACTIVATE_DIGITAL_BOOKINGS, FeatureToggle.DISPLAY_DMS_REDIRECTION, FeatureToggle.ENABLE_ID_CHECK_RETENTION, FeatureToggle.ENABLE_NATIVE_APP_RECAPTCHA, FeatureToggle.ENABLE_NATIVE_EAC_INDIVIDUAL, FeatureToggle.ENABLE_NATIVE_ID_CHECK_VERBOSE_DEBUGGING, FeatureToggle.ENABLE_PHONE_VALIDATION, FeatureToggle.ENABLE_UBBLE, FeatureToggle.ENABLE_UNDERAGE_GENERALISATION, FeatureToggle.ID_CHECK_ADDRESS_AUTOCOMPLETION, FeatureToggle.WEBAPP_V2_ENABLED)
    return serializers.SettingsResponse(account_creation_minimum_age=constants.ACCOUNT_CREATION_MINIMUM_AGE, allow_id_check_registration=features[FeatureToggle.ALLOW_IDCHECK_REGISTRATION], auto_activate_digital_bookings=features[FeatureToggle.AUTO_ACTIVATE_DIGITAL_BOOKINGS], deposit_amount=deposits_conf.GRANTED_DEPOSIT_AMOUNT_18_v2, display_dms_redirection=features[FeatureToggle.DISPLAY_DMS_REDIRECTION], enable_native_eac_individual=features[FeatureToggle.ENABLE_NATIVE_EAC_INDIVIDUAL], enable_ubble=features[FeatureToggle.ENABLE_UBBLE], enable_underage_generalisation=features[FeatureToggle.ENABLE_UNDERAGE_GENERALISATION], id_check_address_autocompletion=features[FeatureToggle.ID_CHECK_ADDRESS_AUTOCOMPLETION], is_recaptcha_enabled=features[FeatureToggle.ENABLE_NATIVE_APP_RECAPTCHA], is_webapp_v2_enabled=features[FeatureToggle.WEBAPP_V2_ENABLED], object_storage_url=OBJECT_STORAGE_URL, enable_native_id_check_verbose_debugging=features[FeatureToggle.ENABLE_NATIVE_ID_CHECK_VERBOSE_DEBUGGING], enable_id_check_retention=features[FeatureToggle.ENABLE_ID_CHECK_RETENTION], enable_phone_validation=features[FeatureToggle.ENABLE_PHONE_VALIDATION])

def log_object(self, tag, object_, allow_scalar_logging=True, allow_image_logging=True, allow_histogram_logging=True):
    assert isinstance(tag, str)
    if isinstance(object_, (list, tuple)):
        for (object_num, _object) in enumerate(object_):
            self.log_object('{}_{}'.format(tag, object_num), _object, allow_scalar_logging, allow_image_logging, allow_histogram_logging)
        return
    if tu.is_scalar_tensor(object_) and allow_scalar_logging:
        value = tu.unwrap(object_.float(), extract_item=True)
        self.log_scalar(tag, value, step=self.trainer.iteration_count)
    elif isinstance(object_, (float, int)) and allow_scalar_logging:
        value = float(object_)
        self.log_scalar(tag, value, step=self.trainer.iteration_count)
    elif tu.is_label_image_or_volume_tensor(object_) and allow_image_logging:
        self.log_image_or_volume_batch(tag, object_[:, None, ...], self.trainer.iteration_count)
    elif tu.is_image_or_volume_tensor(object_):
        if allow_image_logging:
            self.log_image_or_volume_batch(tag, object_, self.trainer.iteration_count)
    elif tu.is_vector_tensor(object_) and allow_histogram_logging:
        values = tu.unwrap(object_, as_numpy=True)
        self.log_histogram(tag, values, self.trainer.iteration_count)
    elif tu.is_tensor(object_):
        warnings.warn('Unsupported attempt to log tensor `{}` of shape `{}`'.format(tag, object_.size()))

def api_ping_list(hosts, bind=None, timeout=None, threads=10):
    if len(hosts) == 0:
        return {}
    pool = multiprocessing.dummy.Pool(processes=min(len(hosts), threads))
    pool_args = [(host, timeout) for host in hosts]
    result = {}

    def ping_one(arg):
        (host, timeout) = arg
        (up, _) = api_ping(host, bind=bind, timeout=timeout)
        return (host, up)
    for (host, state) in pool.imap(ping_one, pool_args, chunksize=1):
        result[host] = state
    pool.close()
    return result

def _capture_stdout(argv, ignore_retval=False):
    try:
        import subprocess
        p = subprocess.Popen(argv, stdout=subprocess.PIPE)
        stdout = p.stdout.read()
        retval = p.wait()
    except ImportError:
        pass
    if retval and (not ignore_retval):
        raise RuntimeError("error running '%s'" % ' '.join(argv))
    return stdout

def _updatePosition(self, axes_to_update=None):
    pos = {}
    axes_to_update = axes_to_update or range(len(self._axes_names))
    for i in axes_to_update:
        pos[self._axes_names[i]] = self.GetAxisParam(i, 1) * self._ustepsize[i]
    self.position._value = pos
    self.position.notify(self.position.value)

def ValidateSyntax(rdf_artifact):
    if not rdf_artifact.doc:
        raise rdf_artifacts.ArtifactSyntaxError(rdf_artifact, 'missing doc')
    for supp_os in rdf_artifact.supported_os:
        valid_os = rdf_artifact.SUPPORTED_OS_LIST
        if supp_os not in valid_os:
            detail = "invalid `supported_os` ('%s' not in %s)" % (supp_os, valid_os)
            raise rdf_artifacts.ArtifactSyntaxError(rdf_artifact, detail)
    for condition in rdf_artifact.conditions:
        of = objectfilter.Parser(condition).Parse()
        of.Compile(objectfilter.BaseFilterImplementation)
    valid_provides = rdf_client.KnowledgeBase().GetKbFieldNames()
    for kb_var in rdf_artifact.provides:
        if kb_var not in valid_provides:
            detail = "broken `provides` ('%s' not in %s)" % (kb_var, valid_provides)
            raise rdf_artifacts.ArtifactSyntaxError(rdf_artifact, detail)
    for dep in GetArtifactPathDependencies(rdf_artifact):
        if dep not in valid_provides:
            detail = "broken path dependencies ('%s' not in %s)" % (dep, valid_provides)
            raise rdf_artifacts.ArtifactSyntaxError(rdf_artifact, detail)
    for source in rdf_artifact.sources:
        try:
            source.Validate()
        except rdf_artifacts.ArtifactSourceSyntaxError as e:
            raise rdf_artifacts.ArtifactSyntaxError(rdf_artifact, 'bad source', e)

def _get_mappings(self, account, tpl):
    mapping = dict()
    if account.owner_type == self.const.entity_group:
        group = self._get_group(account.owner_id, idtype='id')
        mapping['group'] = group.group_name
    elif account.owner_type == self.const.entity_person:
        person = self._get_person('id', account.owner_id)
        mapping['fullname'] = person.get_name(self.const.system_cached, self.const.name_full)
    else:
        raise CerebrumError('Unsupported account owner type %s' % account.owner_type)
    if tpl.get('lang', '').endswith('letter'):
        if account.owner_type != self.const.entity_person:
            raise CerebrumError('Cannot make letter to non-personal account %s ' % account.account_name)
        mapping['barcode'] = 'barcode_%s.eps' % account.entity_id
        address = None
        for (source, kind) in ((self.const.system_sap, self.const.address_post), (self.const.system_fs, self.const.address_post), (self.const.system_sap, self.const.address_post_private), (self.const.system_fs, self.const.address_post_private)):
            address = person.get_entity_address(source=source, type=kind)
            if address:
                break
        if not address:
            raise CerebrumError("Couldn't get authoritative address for %s" % account.account_name)
        address = address[0]
        alines = address['address_text'].split('\n') + ['']
        mapping['address_line1'] = mapping['fullname']
        if alines:
            mapping['address_line2'] = alines[0]
            mapping['address_line3'] = alines[1]
        else:
            mapping['address_line2'] = ''
            mapping['address_line3'] = ''
        mapping['zip'] = address['postal_number']
        mapping['city'] = address['city']
        mapping['country'] = address['country']
        mapping['birthdate'] = person.birth_date.strftime('%Y-%m-%d')

    def unicodify(value):
        if isinstance(value, str):
            try:
                value = value.decode('UTF-8')
            except UnicodeDecodeError:
                value = value.decode('ISO-8859-1')
        return value
    for (k, v) in mapping.items():
        if not v:
            continue
        mapping[k] = unicodify(v).encode('UTF-8')
    return mapping

def organization(self):
    first_organization = self.get_first_organization()
    return first_organization

def get_success_url(self) -> str:
    if self.request.POST.get('show_next', '0').strip() == '1':
        next_submission = Review.find_missing_reviews(self.request.event, self.request.user).first()
        if next_submission:
            messages.success(self.request, _('Keep it up!'))
            return next_submission.orga_urls.reviews
        else:
            messages.success(self.request, _('Nice, you have no submissions left to review!'))
            return self.request.event.orga_urls.reviews
    return self.submission.orga_urls.reviews

def inject_files(self, files):
    if files:
        self.cfg['dir_inject'] = os.path.dirname(files[0])
        try:
            (error_files, foreign_files) = self.ovl_data.inject(files, self.show_temp_files)
            self.file_widget.dirty = True
            if foreign_files:
                for name_ext in foreign_files:
                    if interaction.showdialog(f'Do you want to add {name_ext} to this ovl?', ask=True):
                        logging.info(f'Adding new file {name_ext}')
        except Exception as ex:
            traceback.print_exc()
            interaction.showdialog(str(ex))

def upsert_table_schema(self, cur, stream_buffer):
    (existing_table_schema, key_properties) = self._get_schema(cur, 'public', stream_buffer.stream)
    if existing_table_schema:
        schema = self._merge_put_schemas(cur, 'public', stream_buffer.stream, existing_table_schema, stream_buffer.schema)
        table_name = self._get_temp_table_name(stream_buffer.stream)
    else:
        schema = stream_buffer.schema
        table_name = stream_buffer.stream
    self._create_table(cur, 'public', table_name, schema, stream_buffer.key_properties)
    return (table_name, existing_table_schema is not None)

def __init__(self, request, *args, **kwargs):
    super(ConfigureNodegroupsAction, self).__init__(request, *args, **kwargs)
    templates = []
    count = int(request.session.get('groups_count', 0))
    for dictionary in args:
        if dictionary.get('general_hidden_configure_field', None) == 'create_nodegroup':
            count += 1
            request.session['groups_count'] = count
            break
    for idx in range(0, count, 1):
        self.fields['group_' + str(idx) + '_name'] = forms.CharField(label=_('Name'), required=True)
        self.fields['group_' + str(idx) + '_template'] = forms.ChoiceField(label=_('Node group template'), required=True, choices=templates)
        self.fields['group_' + str(idx) + '_count'] = forms.IntegerField(label=_('Count'), required=True, min_value=1)

def fix_nametable(ttFont):
    if 'fvar' in ttFont:
        return
    family_name = font_familyname(ttFont)
    style_name = font_stylename(ttFont)
    update_nametable(ttFont, family_name, style_name)

def parse_revdep_config(revdep_confdir):
    search_dirs = set()
    masked_dirs = set()
    masked_files = set()
    for _file in os.listdir(revdep_confdir):
        for line in open(os.path.join('/etc/revdep-rebuild', _file)):
            line = line.strip()
            if not line.startswith('#'):
                m = re.match('LD_LIBRARY_MASK=\\"([^"]+)\\"', line)
                if m is not None:
                    s = m.group(1).split(' ')
                    masked_files = masked_files.union(s)
                    continue
                m = re.match('SEARCH_DIRS_MASK=\\"([^"]+)\\"', line)
                if m is not None:
                    s = m.group(1).split(' ')
                    for ss in s:
                        masked_dirs = masked_dirs.union(glob.glob(ss))
                    continue
                m = re.match('SEARCH_DIRS=\\"([^"]+)\\"', line)
                if m is not None:
                    s = m.group(1).split()
                    for ss in s:
                        search_dirs = search_dirs.union(glob.glob(ss))
                    continue
    return (masked_dirs, masked_files, search_dirs)
